window.OTB_DATA = {"version": "v5.0", "snapshotDate": "2026-11-07", "sources": {"entry": {"path": "src/backend/tcop/postgres.c", "sha256": "ddf5ebf6feef82da41e46a13780a8842a7a31f65ac44fb98ac27f1dde2ea2cea", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/backend/tcop/postgres.c", "lines": [{"n": 1135, "text": " * the parameter list is not passed initially. Therefore, we need to add a"}, {"n": 1136, "text": " * function parameter called cached_param_num to record the original number"}, {"n": 1137, "text": " * of parameters."}, {"n": 1138, "text": " */"}, {"n": 1139, "text": "PlannedStmt *"}, {"n": 1140, "text": "pg_plan_query(Query *querytree, int cursorOptions,"}, {"n": 1141, "text": "\t\t\t\t\t\tParamListInfo boundParams,"}, {"n": 1142, "text": "\t\t\t\t\t\tint cached_param_num,"}, {"n": 1143, "text": "\t\t\t\t\t\tbool explain)"}, {"n": 1144, "text": "{"}, {"n": 1145, "text": "\tPlannedStmt *plan;"}, {"n": 1146, "text": ""}, {"n": 1147, "text": "\t/* Utility commands have no plans. */"}, {"n": 1148, "text": "\tif (querytree->commandType == CMD_UTILITY)"}, {"n": 1149, "text": "\t\treturn NULL;"}, {"n": 1150, "text": ""}, {"n": 1151, "text": "\t/* Planner must have a snapshot in case it calls user-defined functions. */"}, {"n": 1152, "text": "\tAssert(ActiveSnapshotSet() || !g_snapshot_for_analyze);"}, {"n": 1153, "text": ""}, {"n": 1154, "text": "\tTRACE_POSTGRESQL_QUERY_PLAN_START();"}, {"n": 1155, "text": ""}, {"n": 1156, "text": "\tif (log_planner_stats)"}, {"n": 1157, "text": "\t\tResetUsage();"}, {"n": 1158, "text": ""}, {"n": 1159, "text": "\tSPMFillGUC();"}, {"n": 1160, "text": ""}, {"n": 1161, "text": "\t/* call the optimizer */"}, {"n": 1162, "text": "\tplan = planner(querytree, cursorOptions, boundParams,"}, {"n": 1163, "text": "\t\t\t\t\tcached_param_num, explain);"}, {"n": 1164, "text": ""}, {"n": 1165, "text": "#ifdef __AUDIT__"}, {"n": 1166, "text": "\tplan->queryString = NULL;"}, {"n": 1167, "text": "\tplan->parseTree = copyObject(querytree);"}, {"n": 1168, "text": "#endif"}, {"n": 1169, "text": ""}, {"n": 1170, "text": "\tif (log_planner_stats)"}, {"n": 1171, "text": "\t\tShowUsage(\"PLANNER STATISTICS\");"}, {"n": 1172, "text": ""}, {"n": 1173, "text": "#ifdef COPY_PARSE_PLAN_TREES"}, {"n": 1174, "text": "\t/* Optional debugging check: pass plan output through copyObject() */"}, {"n": 1175, "text": "\t{"}, {"n": 1176, "text": "\t\tPlannedStmt *new_plan = copyObject(plan);"}, {"n": 1177, "text": ""}, {"n": 1178, "text": "\t\t/*"}, {"n": 1179, "text": "\t\t * equal() currently does not have routines to compare Plan nodes, so"}, {"n": 1180, "text": "\t\t * don't try to test equality here.  Perhaps fix someday?"}, {"n": 1181, "text": "\t\t */"}, {"n": 1182, "text": "#ifdef NOT_USED"}, {"n": 1183, "text": "\t\t/* This checks both copyObject() and the equal() routines... */"}, {"n": 1184, "text": "\t\tif (!equal(new_plan, plan))"}, {"n": 1185, "text": "\t\t\telog(WARNING, \"copyObject() failed to produce an equal plan tree\");"}, {"n": 1186, "text": "\t\telse"}, {"n": 1187, "text": "#endif"}, {"n": 1188, "text": "\t\t\tplan = new_plan;"}, {"n": 1189, "text": "\t}"}, {"n": 1190, "text": "#endif"}, {"n": 1191, "text": ""}, {"n": 1192, "text": "\t/*"}, {"n": 1193, "text": "\t * Print plan if debugging."}, {"n": 1194, "text": "\t */"}, {"n": 1195, "text": "\tif (Debug_print_plan)"}, {"n": 1196, "text": "\t\telog_node_display(LOG, \"plan\", plan, Debug_pretty_print);"}, {"n": 1197, "text": ""}, {"n": 1198, "text": "\tSPMFillExtraData(plan);"}, {"n": 1199, "text": ""}, {"n": 1200, "text": "\tTRACE_POSTGRESQL_QUERY_PLAN_DONE();"}, {"n": 1201, "text": ""}, {"n": 1202, "text": "\treturn plan;"}, {"n": 1203, "text": "}"}, {"n": 1204, "text": ""}, {"n": 1205, "text": "List *"}, {"n": 1206, "text": "pg_plan_queries(List *querytrees, int cursorOptions, ParamListInfo boundParams)"}, {"n": 1207, "text": "{"}, {"n": 1208, "text": "\treturn pg_plan_queries_internal(querytrees, cursorOptions, boundParams, 0);"}, {"n": 1209, "text": "}"}, {"n": 1210, "text": ""}, {"n": 1211, "text": "/*"}, {"n": 1212, "text": " * Generate plans for a list of already-rewritten queries."}, {"n": 1213, "text": " *"}, {"n": 1214, "text": " * For normal optimizable statements, invoke the planner.  For utility"}, {"n": 1215, "text": " * statements, just make a wrapper PlannedStmt node."}, {"n": 1216, "text": " *"}, {"n": 1217, "text": " * The result is a list of PlannedStmt nodes."}, {"n": 1218, "text": " */"}, {"n": 1219, "text": "List *"}, {"n": 1220, "text": "pg_plan_queries_internal(List *querytrees, int cursorOptions,"}, {"n": 1221, "text": "\t\t\t\t\t\t\tParamListInfo boundParams, int cached_param_num)"}, {"n": 1222, "text": "{"}, {"n": 1223, "text": "\tList\t   *stmt_list = NIL;"}, {"n": 1224, "text": "\tListCell   *query_list;"}, {"n": 1225, "text": ""}, {"n": 1226, "text": "\tforeach(query_list, querytrees)"}, {"n": 1227, "text": "\t{"}, {"n": 1228, "text": "\t\tQuery\t   *query = lfirst_node(Query, query_list);"}, {"n": 1229, "text": "\t\tPlannedStmt *stmt;"}, {"n": 1230, "text": ""}, {"n": 1231, "text": "\t\tif (query->commandType == CMD_UTILITY)"}, {"n": 1232, "text": "\t\t{"}, {"n": 1233, "text": "\t\t\t/* Utility commands require no planning. */"}, {"n": 1234, "text": "\t\t\tstmt = makeNode(PlannedStmt);"}, {"n": 1235, "text": "\t\t\tstmt->commandType = CMD_UTILITY;"}, {"n": 1236, "text": "\t\t\tstmt->canSetTag = query->canSetTag;"}, {"n": 1237, "text": "\t\t\tstmt->utilityStmt = query->utilityStmt;"}, {"n": 1238, "text": "\t\t\tstmt->stmt_location = query->stmt_location;"}, {"n": 1239, "text": "\t\t\tstmt->stmt_len = query->stmt_len;"}, {"n": 1240, "text": "\t\t\tstmt->guc_str = NULL;"}, {"n": 1241, "text": "\t\t}"}, {"n": 1242, "text": "\t\telse"}, {"n": 1243, "text": "\t\t{"}, {"n": 1244, "text": "\t\t\tstmt = pg_plan_query(query, cursorOptions, boundParams,"}, {"n": 1245, "text": "\t\t\t\t\t\t\t\t\tcached_param_num, false);"}, {"n": 1246, "text": "\t\t}"}, {"n": 1247, "text": ""}, {"n": 1248, "text": "\t\tstmt_list = lappend(stmt_list, stmt);"}, {"n": 1249, "text": "\t}"}, {"n": 1250, "text": ""}, {"n": 1251, "text": "\treturn stmt_list;"}, {"n": 1252, "text": "}"}, {"n": 1253, "text": ""}, {"n": 1254, "text": "/*"}, {"n": 1255, "text": " * Get a single query string from the original query string if the query string"}, {"n": 1256, "text": " * contains multi stmts."}, {"n": 1257, "text": " */"}, {"n": 1258, "text": "static char*"}, {"n": 1259, "text": "get_single_query_string(const char* query_string, RawStmt *parsetree)"}, {"n": 1260, "text": "{"}, {"n": 1365, "text": " * exec_simple_query"}, {"n": 1366, "text": " *"}, {"n": 1367, "text": " * Execute a \"simple Query\" protocol message."}, {"n": 1368, "text": " */"}, {"n": 1369, "text": "static void"}, {"n": 1370, "text": "exec_simple_query(const char *query_string)"}, {"n": 1371, "text": "{"}, {"n": 1372, "text": "\tCommandDest dest = whereToSendOutput;"}, {"n": 1373, "text": "\tMemoryContext oldcontext;"}, {"n": 1374, "text": "\tList\t   *parsetree_list;"}, {"n": 1375, "text": "\tListCell   *parsetree_item;"}, {"n": 1376, "text": "\tbool\t\tsave_log_statement_stats = log_statement_stats;"}, {"n": 1377, "text": "\tbool\t\twas_logged = false;"}, {"n": 1378, "text": "\tbool\t\tisTopLevel;"}, {"n": 1379, "text": "\tchar\t\tmsec_str[32];"}, {"n": 1380, "text": "\tbool\t\tmultiCommands = false;"}, {"n": 1381, "text": "    origin_query_string = debug_query_string = query_string;"}, {"n": 1382, "text": ""}, {"n": 1383, "text": "\tTRACE_POSTGRESQL_QUERY_START(query_string);"}, {"n": 1384, "text": ""}, {"n": 1385, "text": "\t/*"}, {"n": 1386, "text": "\t * We use save_log_statement_stats so ShowUsage doesn't report incorrect"}, {"n": 1387, "text": "\t * results because ResetUsage wasn't called."}, {"n": 1388, "text": "\t */"}, {"n": 1389, "text": "\tif (save_log_statement_stats)"}, {"n": 1390, "text": "\t\tResetUsage();"}, {"n": 1391, "text": ""}, {"n": 1392, "text": "\t/*"}, {"n": 1393, "text": "\t * Start up a transaction command.  All queries generated by the"}, {"n": 1394, "text": "\t * query_string will be in this same command block, *unless* we find a"}, {"n": 1395, "text": "\t * BEGIN/COMMIT/ABORT statement; we have to force a new xact command after"}, {"n": 1396, "text": "\t * one of those, else bad things will happen in xact.c. (Note that this"}, {"n": 1397, "text": "\t * will normally change current memory context.)"}, {"n": 1398, "text": "\t */"}, {"n": 1399, "text": "\tstart_xact_command();"}, {"n": 1400, "text": ""}, {"n": 1401, "text": ""}, {"n": 1402, "text": "\t/*"}, {"n": 1403, "text": "\t * Zap any pre-existing unnamed statement.  (While not strictly necessary,"}, {"n": 1404, "text": "\t * it seems best to define simple-Query mode as if it used the unnamed"}, {"n": 1405, "text": "\t * statement and portal; this ensures we recover any storage used by prior"}, {"n": 1406, "text": "\t * unnamed operations.)"}, {"n": 1407, "text": "\t */"}, {"n": 1408, "text": "\tdrop_unnamed_stmt();"}, {"n": 1409, "text": ""}, {"n": 1410, "text": "\t/*"}, {"n": 1411, "text": "\t * Switch to appropriate context for constructing parsetrees."}, {"n": 1412, "text": "\t */"}, {"n": 1413, "text": "\toldcontext = MemoryContextSwitchTo(MessageContext);"}, {"n": 1414, "text": ""}, {"n": 1415, "text": "\t/*"}, {"n": 1416, "text": "\t * Do basic parsing of the query or queries (this should be safe even if"}, {"n": 1417, "text": "\t * we are in aborted transaction state!)"}, {"n": 1418, "text": "\t */"}, {"n": 1419, "text": "\tif (post_query_replace_hook)"}, {"n": 1420, "text": "\t{"}, {"n": 1421, "text": "\t\tchar *rewrite_query = NULL;"}, {"n": 1422, "text": ""}, {"n": 1423, "text": "\t\tif ((*post_query_replace_hook)(query_string, &rewrite_query))"}, {"n": 1424, "text": "\t\t{"}, {"n": 1425, "text": "\t\t\tquery_string = pstrdup(rewrite_query);"}, {"n": 1426, "text": "\t\t\tpfree(rewrite_query);"}, {"n": 1427, "text": "\t\t}"}, {"n": 1428, "text": "\t}"}, {"n": 1429, "text": ""}, {"n": 1430, "text": "\tparsetree_list = pg_parse_query(query_string);"}, {"n": 1431, "text": ""}, {"n": 1432, "text": ""}, {"n": 1433, "text": "#ifdef XCP"}, {"n": 1434, "text": "\tif (IS_PGXC_LOCAL_COORDINATOR && list_length(parsetree_list) > 1)"}, {"n": 1435, "text": "\t{"}, {"n": 1436, "text": "\t\t/*"}, {"n": 1437, "text": "\t\t * There is a bug in old code, if one query contains multiple utility"}, {"n": 1438, "text": "\t\t * statements, entire query may be sent multiple times to the Datanodes"}, {"n": 1439, "text": "\t\t * for execution. That is becoming a severe problem, if query contains"}, {"n": 1440, "text": "\t\t * COMMIT or ROLLBACK. After executed for the first time the transaction"}, {"n": 1441, "text": "\t\t * handling statement would write CLOG entry for current xid, but other"}, {"n": 1442, "text": "\t\t * executions would be done with the same xid, causing PANIC on the"}, {"n": 1443, "text": "\t\t * Datanodes because of already existing CLOG record. Datanode is"}, {"n": 1444, "text": "\t\t * restarting all sessions if it PANICs, and affects all cluster users."}, {"n": 1445, "text": "\t\t * Multiple utility statements may result in strange error messages,"}, {"n": 1446, "text": "\t\t * but somteime they work, and used in many applications, so we do not"}, {"n": 1447, "text": "\t\t * want to disable them completely, just protect against severe"}, {"n": 1448, "text": "\t\t * vulnerability here."}, {"n": 1449, "text": "\t\t */"}, {"n": 1450, "text": "\t\tforeach(parsetree_item, parsetree_list)"}, {"n": 1451, "text": "\t\t{"}, {"n": 1452, "text": "\t\t\tNode\t   *parsetree = (Node *) lfirst(parsetree_item);"}, {"n": 1453, "text": ""}, {"n": 1454, "text": "\t\t\tif (IsTransactionExitStmt(parsetree))"}, {"n": 1455, "text": "\t\t\t\tereport(ERROR,"}, {"n": 1456, "text": "\t\t\t\t\t\t(errcode(ERRCODE_STATEMENT_TOO_COMPLEX),"}, {"n": 1457, "text": "\t\t\t\t\t\t errmsg(\"COMMIT or ROLLBACK \""}, {"n": 1458, "text": "\t\t\t\t\t\t\t\t\"in multi-statement queries not allowed\")));"}, {"n": 1459, "text": "\t\t}"}, {"n": 1460, "text": ""}, {"n": 1461, "text": "\t\tmult_sql_query_containing = true;"}, {"n": 1462, "text": "\t}"}, {"n": 1463, "text": "\telse"}, {"n": 1464, "text": "\t\tmult_sql_query_containing = false;"}, {"n": 1465, "text": ""}, {"n": 1466, "text": "\t/*"}, {"n": 1467, "text": "\t * XXX We may receive multi-command string and the coordinator is not"}, {"n": 1468, "text": "\t * equipped to handle multiple command-complete messages. So just send a"}, {"n": 1469, "text": "\t * single command-complete until we fix the coordinator side of things"}, {"n": 1470, "text": "\t */"}, {"n": 1471, "text": "\tif (!IS_LOCAL_ACCESS_NODE && list_length(parsetree_list) > 1)"}, {"n": 1472, "text": "\t\tmultiCommands = true;"}, {"n": 1473, "text": "#endif"}, {"n": 1474, "text": ""}, {"n": 1475, "text": "\t/* Log immediately if dictated by log_statement */"}, {"n": 1476, "text": "\tif (check_log_statement(parsetree_list))"}, {"n": 1477, "text": "\t{"}, {"n": 1478, "text": "\t\tereport(LOG,"}, {"n": 1479, "text": "\t\t\t\t(errmsg(\"statement: %s\", debug_query_string),"}, {"n": 1480, "text": "\t\t\t\t errhidestmt(true),"}, {"n": 1481, "text": "\t\t\t\t errdetail_execute(parsetree_list)));"}, {"n": 1482, "text": "\t\twas_logged = true;"}, {"n": 1483, "text": "\t}"}, {"n": 1484, "text": ""}, {"n": 1485, "text": "\t/*"}, {"n": 1486, "text": "\t * Switch back to transaction context to enter the loop."}, {"n": 1487, "text": "\t */"}, {"n": 1488, "text": "\tMemoryContextSwitchTo(oldcontext);"}, {"n": 1489, "text": ""}, {"n": 1490, "text": "\t/*"}, {"n": 1491, "text": "\t * We'll tell PortalRun it's a top-level command iff there's exactly one"}, {"n": 1492, "text": "\t * raw parsetree.  If more than one, it's effectively a transaction block"}, {"n": 1493, "text": "\t * and we want PreventTransactionChain to reject unsafe commands. (Note:"}, {"n": 1494, "text": "\t * we're assuming that query rewrite cannot add commands that are"}, {"n": 1495, "text": "\t * significant to PreventTransactionChain.)"}, {"n": 1496, "text": "\t */"}, {"n": 1497, "text": "\tisTopLevel = (list_length(parsetree_list) == 1);"}, {"n": 1498, "text": ""}, {"n": 1499, "text": "\t/*"}, {"n": 1500, "text": "\t * Run through the raw parsetree(s) and process each one."}, {"n": 1501, "text": "\t */"}, {"n": 1502, "text": "\tforeach(parsetree_item, parsetree_list)"}, {"n": 1503, "text": "\t{"}, {"n": 1504, "text": "\t\tRawStmt    *parsetree = lfirst_node(RawStmt, parsetree_item);"}, {"n": 1505, "text": "\t\tbool\t\tsnapshot_set = false;"}, {"n": 1506, "text": "\t\tconst char *commandTag;"}, {"n": 1507, "text": "\t\tchar\t\tcompletionTag[COMPLETION_TAG_BUFSIZE];"}, {"n": 1508, "text": "\t\tList\t   *querytree_list,"}, {"n": 1509, "text": "\t\t\t\t   *plantree_list;"}, {"n": 1510, "text": "\t\tPortal\t\tportal;"}, {"n": 1511, "text": "\t\tDestReceiver *receiver;"}, {"n": 1512, "text": "\t\tint16\t\tformat;"}, {"n": 1513, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 1514, "text": "\t\tOid\t\t\t*relids = NULL;"}, {"n": 1515, "text": "\t\tchar\t\t*resultcache = NULL;"}, {"n": 1516, "text": "\t\tuint32\t\tqueryid = 0;"}, {"n": 1517, "text": "\t\tbool\t\treturn_cache = false;"}, {"n": 1518, "text": "#endif"}, {"n": 1519, "text": "\t\tconst char\t*single_origin_query_str;"}, {"n": 1520, "text": "\t\tconst char *current_query_string;"}, {"n": 1521, "text": ""}, {"n": 1522, "text": "\t\t/*"}, {"n": 1523, "text": "\t\t * OK to analyze, rewrite, and plan this query."}, {"n": 1524, "text": "\t\t *"}, {"n": 1525, "text": "\t\t * Switch to appropriate context for constructing querytrees (again,"}, {"n": 1526, "text": "\t\t * these must outlive the execution context)."}, {"n": 1527, "text": "\t\t */"}, {"n": 1528, "text": "\t\toldcontext = MemoryContextSwitchTo(MessageContext);"}, {"n": 1529, "text": ""}, {"n": 1530, "text": "\t\t/* get this portal's query when has multi parse tree */"}, {"n": 1531, "text": "\t\tcurrent_query_string = isTopLevel ? debug_query_string : "}, {"n": 1532, "text": "\t\t\t\t\t\t\t\t\t\t\t(const char *)get_single_query_string(debug_query_string, parsetree);"}, {"n": 1533, "text": ""}, {"n": 1534, "text": "\t\t/*"}, {"n": 1535, "text": "\t\t * single_origin_query_str  "}, {"n": 1536, "text": "\t\t *\t\t- always keeps the original query string "}, {"n": 1537, "text": "\t\t *"}, {"n": 1538, "text": "\t\t * current_query_string "}, {"n": 1539, "text": "\t\t * \t\t- keeps sanitized query stirng if the original query string"}, {"n": 1540, "text": "\t\t * \t\t  contains sensitive data. otherwise, same as single_origin_query_str"}, {"n": 1541, "text": "\t\t */\t"}, {"n": 1542, "text": "\t\tif (debug_query_string != origin_query_string)"}, {"n": 1543, "text": "\t\t\tsingle_origin_query_str = isTopLevel ? origin_query_string:"}, {"n": 1544, "text": "\t\t\t\t\t(const char *)get_single_query_string(origin_query_string, parsetree);"}, {"n": 1545, "text": "\t\telse"}, {"n": 1546, "text": "\t\t\tsingle_origin_query_str = current_query_string;"}, {"n": 1547, "text": "#ifdef PGXC"}, {"n": 1548, "text": ""}, {"n": 1549, "text": "\t\t/*"}, {"n": 1550, "text": "\t\t * By default we do not want Datanodes or client Coordinators to contact GTM directly,"}, {"n": 1551, "text": "\t\t * it should get this information passed down to it."}, {"n": 1552, "text": "\t\t */"}, {"n": 1553, "text": "\t\tif (IS_PGXC_DATANODE || IsConnFromCoord())"}, {"n": 1554, "text": "\t\t\tSetForceXidFromGTM(false);"}, {"n": 1555, "text": "#endif"}, {"n": 1556, "text": ""}, {"n": 1557, "text": "\t\t/*"}, {"n": 1558, "text": "\t\t * Switch back to transaction context"}, {"n": 1559, "text": "\t\t */"}, {"n": 1560, "text": "\t\tMemoryContextSwitchTo(oldcontext);"}, {"n": 1561, "text": ""}, {"n": 1562, "text": "\t\t/*"}, {"n": 1563, "text": "\t\t * Get the command name for use in status display (it also becomes the"}, {"n": 1564, "text": "\t\t * default completion tag, down inside PortalRun).  Set ps_status and"}, {"n": 1565, "text": "\t\t * do any special start-of-SQL-command processing needed by the"}, {"n": 1566, "text": "\t\t * destination."}, {"n": 1567, "text": "\t\t */"}, {"n": 1568, "text": "\t\tcommandTag = CreateCommandTag(parsetree->stmt);"}, {"n": 1569, "text": ""}, {"n": 1570, "text": "#ifdef __AUDIT_FGA__"}, {"n": 1571, "text": "\t\tg_commandTag = commandTag;"}, {"n": 1572, "text": "#endif"}, {"n": 1573, "text": ""}, {"n": 1574, "text": "#ifdef __OPENTENBASE__"}, {"n": 1575, "text": "\t\tHeavyLockCheck(commandTag, CMD_UNKNOWN,current_query_string, parsetree);"}, {"n": 1576, "text": ""}, {"n": 1577, "text": "\t\texplain_stmt = false;"}, {"n": 1578, "text": ""}, {"n": 1579, "text": "\t\tif (strcmp(commandTag, \"EXPLAIN\") == 0)"}, {"n": 1580, "text": "\t\t{"}, {"n": 1581, "text": "\t\t\texplain_stmt = true;"}, {"n": 1582, "text": "\t\t}"}, {"n": 1583, "text": "#endif"}, {"n": 1584, "text": ""}, {"n": 1585, "text": "\t\tset_ps_display(commandTag, false);"}, {"n": 1586, "text": ""}, {"n": 1587, "text": "\t\tBeginCommand(commandTag, dest);"}, {"n": 1588, "text": ""}, {"n": 1589, "text": "\t\t/*"}, {"n": 1590, "text": "\t\t * If we are in an aborted transaction, reject all commands except"}, {"n": 1591, "text": "\t\t * COMMIT/ABORT.  It is important that this test occur before we try"}, {"n": 1592, "text": "\t\t * to do parse analysis, rewrite, or planning, since all those phases"}, {"n": 1593, "text": "\t\t * try to do database accesses, which may fail in abort state. (It"}, {"n": 1594, "text": "\t\t * might be safe to allow some additional utility commands in this"}, {"n": 1595, "text": "\t\t * state, but not many...)"}, {"n": 1596, "text": "\t\t */"}, {"n": 1597, "text": "\t\tif (IsAbortedTransactionBlockState() &&"}, {"n": 1598, "text": "\t\t\t!IsTransactionExitStmt(parsetree->stmt))"}, {"n": 1599, "text": "\t\t\tereport(ERROR,"}, {"n": 1600, "text": "\t\t\t\t\t(errcode(ERRCODE_IN_FAILED_SQL_TRANSACTION),"}, {"n": 1601, "text": "\t\t\t\t\t errmsg(\"current transaction is aborted, \""}, {"n": 1602, "text": "\t\t\t\t\t\t\t\"commands ignored until end of transaction block\"),"}, {"n": 1603, "text": "\t\t\t\t\t errdetail_abort()));"}, {"n": 1604, "text": ""}, {"n": 1605, "text": "\t\t/* Make sure we are in a transaction command */"}, {"n": 1606, "text": "\t\tstart_xact_command();"}, {"n": 1607, "text": "\t\t/* If we got a cancel signal in parsing or prior command, quit */"}, {"n": 1608, "text": "\t\tCHECK_FOR_INTERRUPTS();"}, {"n": 1609, "text": ""}, {"n": 1610, "text": "\t\t/*"}, {"n": 1611, "text": "\t\t * Set up a snapshot if parse analysis/planning will need one."}, {"n": 1612, "text": "\t\t */"}, {"n": 1613, "text": "\t\tif (analyze_requires_snapshot(parsetree) && g_snapshot_for_analyze)"}, {"n": 1614, "text": "\t\t{"}, {"n": 1615, "text": "\t\t\tPushActiveSnapshot(GetSnapshotByParseTree(parsetree));"}, {"n": 1616, "text": "\t\t\tsnapshot_set = true;"}, {"n": 1617, "text": "\t\t}"}, {"n": 1618, "text": ""}, {"n": 1619, "text": "\t\t/*"}, {"n": 1620, "text": "\t\t * OK to analyze, rewrite, and plan this query."}, {"n": 1621, "text": "\t\t *"}, {"n": 1622, "text": "\t\t * Switch to appropriate context for constructing querytrees (again,"}, {"n": 1623, "text": "\t\t * these must outlive the execution context)."}, {"n": 1624, "text": "\t\t */"}, {"n": 1625, "text": "\t\toldcontext = MemoryContextSwitchTo(MessageContext);"}, {"n": 1626, "text": ""}, {"n": 1627, "text": "\t\tquerytree_list = pg_analyze_and_rewrite(parsetree,"}, {"n": 1628, "text": "\t\t\t\t\t\t\t\t\t\t\t\tcurrent_query_string, NULL, 0,"}, {"n": 1629, "text": "\t\t\t\t\t\t\t\t\t\t\t\tNULL);"}, {"n": 1630, "text": "\t\t\t\t\t\t\t\t\t\t\t\t"}, {"n": 1631, "text": "#ifdef __AUDIT__"}, {"n": 1632, "text": "\t\tif (xact_started)"}, {"n": 1633, "text": "\t\t{"}, {"n": 1634, "text": "\t\t\tAuditReadQueryList(current_query_string, querytree_list);"}, {"n": 1635, "text": "\t\t}"}, {"n": 1636, "text": "#endif"}, {"n": 1637, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 1638, "text": "\t\tif (dest == DestRemote"}, {"n": 1639, "text": "\t\t\t&& PG_PROTOCOL_MAJOR(FrontendProtocol) >= 3"}, {"n": 1640, "text": "\t\t\t&& CheckQuerySatisfyCache(querytree_list))"}, {"n": 1641, "text": "\t\t{"}, {"n": 1642, "text": "\t\t\tQuery *query = linitial_node(Query, querytree_list);"}, {"n": 1643, "text": "\t\t\t"}, {"n": 1644, "text": "\t\t\tqueryid = QueryTreeGetEncodedQueryId(query);"}, {"n": 1645, "text": "\t\t\tresultcache = SearchQueryResultCache(queryid);"}, {"n": 1646, "text": "\t\t\tif (resultcache == NULL)"}, {"n": 1647, "text": "\t\t\t{"}, {"n": 1648, "text": "\t\t\t\trelids = QueryTreeGetRelids(query);"}, {"n": 1649, "text": "\t\t\t}"}, {"n": 1650, "text": "\t\t}"}, {"n": 1651, "text": "\t\t/* check again in case we convert CALL to SELECT */"}, {"n": 1652, "text": "\t\tif (!snapshot_set)"}, {"n": 1653, "text": "\t\t{"}, {"n": 1654, "text": "\t\t\tListCell   *query_list;"}, {"n": 1655, "text": "\t\t\tforeach (query_list, querytree_list)"}, {"n": 1656, "text": "\t\t\t{"}, {"n": 1657, "text": "\t\t\t\tQuery\t   *query = lfirst_node(Query, query_list);"}, {"n": 1658, "text": "\t\t\t\tif (query->commandType != CMD_UTILITY)"}, {"n": 1659, "text": "\t\t\t\t{"}, {"n": 1660, "text": "\t\t\t\t\tPushActiveSnapshot(GetTransactionSnapshot());"}, {"n": 1661, "text": "\t\t\t\t\tsnapshot_set = true;"}, {"n": 1662, "text": "\t\t\t\t\tbreak;"}, {"n": 1663, "text": "\t\t\t\t}"}, {"n": 1664, "text": "\t\t\t}"}, {"n": 1665, "text": "\t\t}"}, {"n": 1666, "text": "#endif"}, {"n": 1667, "text": "\t\tplantree_list = pg_plan_queries(querytree_list,"}, {"n": 1668, "text": "\t\t\t\t\t\t\t\t\t\tCURSOR_OPT_PARALLEL_OK, NULL);"}, {"n": 1669, "text": ""}, {"n": 1670, "text": "\t\t/* Done with the snapshot used for parsing/planning */"}, {"n": 1671, "text": "\t\tif (snapshot_set)"}, {"n": 1672, "text": "\t\t\tPopActiveSnapshot();"}, {"n": 1673, "text": ""}, {"n": 1674, "text": "\t\t/* If we got a cancel signal in analysis or planning, quit */"}, {"n": 1675, "text": "\t\tCHECK_FOR_INTERRUPTS();"}, {"n": 1676, "text": ""}, {"n": 1677, "text": "#ifdef PGXC"}, {"n": 1678, "text": "\t\t/* "}, {"n": 1679, "text": "\t\t * Force getting Xid from GTM for vacuum, cluster and reindex for"}, {"n": 1680, "text": "\t\t * database or schema"}, {"n": 1681, "text": "\t\t */"}, {"n": 1682, "text": "\t\tif (IS_PGXC_DATANODE && IsPostmasterEnvironment)"}, {"n": 1683, "text": "\t\t{"}, {"n": 1684, "text": "\t\t\tif (IsA(parsetree->stmt, VacuumStmt) || IsA(parsetree->stmt, ClusterStmt))"}, {"n": 1685, "text": "\t\t\t\t SetForceXidFromGTM(true);"}, {"n": 1686, "text": "\t\t\telse if (IsA(parsetree->stmt, ReindexStmt))"}, {"n": 1687, "text": "\t\t\t{"}, {"n": 1688, "text": "\t\t\t\tReindexStmt *stmt = (ReindexStmt *) parsetree->stmt;"}, {"n": 1689, "text": "\t\t\t\tif (stmt->kind == REINDEX_OBJECT_SCHEMA ||"}, {"n": 1690, "text": "\t\t\t\t\tstmt->kind == REINDEX_OBJECT_DATABASE)"}, {"n": 1691, "text": "\t\t\t\t\tSetForceXidFromGTM(true);"}, {"n": 1692, "text": "\t\t\t}"}, {"n": 1693, "text": "\t\t}"}, {"n": 1694, "text": "#endif"}, {"n": 1695, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 1696, "text": "\t\t/*"}, {"n": 1697, "text": "\t\t * Check if query tree satisfy result cache"}, {"n": 1698, "text": "\t\t *"}, {"n": 1699, "text": "\t\t */"}, {"n": 1700, "text": "\t\tif (resultcache != NULL)"}, {"n": 1701, "text": "\t\t{"}, {"n": 1702, "text": "\t\t\t/*"}, {"n": 1703, "text": "\t\t\t * Send result to client if valid result is in cache"}, {"n": 1704, "text": "\t\t\t */"}, {"n": 1705, "text": "\t\t\treceiver = CreateDestReceiver(dest);"}, {"n": 1706, "text": "\t\t\tprinttup_resultcache(resultcache);"}, {"n": 1707, "text": "\t\t\t(*receiver->rShutdown) (receiver);"}, {"n": 1708, "text": "\t\t\t(*receiver->rDestroy) (receiver);"}, {"n": 1709, "text": "\t\t\tpfree(resultcache);"}, {"n": 1710, "text": "\t\t\treturn_cache = true;"}, {"n": 1711, "text": "\t\t}"}, {"n": 1712, "text": "\t\t"}, {"n": 1713, "text": "\t\tif (!return_cache)"}, {"n": 1714, "text": "\t\t{"}, {"n": 1715, "text": "#endif"}, {"n": 1716, "text": "\t\t/*"}, {"n": 1717, "text": "\t\t * Create unnamed portal to run the query or queries in. If there"}, {"n": 1718, "text": "\t\t * already is one, silently drop it."}, {"n": 1719, "text": "\t\t */"}, {"n": 1720, "text": "\t\tportal = CreatePortal(\"\", true, true, false, parsetree->stmt);"}, {"n": 1721, "text": "\t\t/* Don't display the portal in pg_cursors */"}, {"n": 1722, "text": "\t\tportal->visible = false;"}, {"n": 1723, "text": "#ifdef __OPENTENBASE__"}, {"n": 1724, "text": "\t\t/*"}, {"n": 1725, "text": "\t\t * try to transform 'insert into values...' to 'COPY FROM'"}, {"n": 1726, "text": "\t\t */"}, {"n": 1727, "text": "\t\tif (IS_PGXC_COORDINATOR && IsA(parsetree->stmt, InsertStmt) &&"}, {"n": 1728, "text": "\t\t\tlist_length(plantree_list) == 1)"}, {"n": 1729, "text": "\t\t{"}, {"n": 1730, "text": "\t\t\tPlannedStmt *planstmt = (PlannedStmt *)linitial(plantree_list);"}, {"n": 1731, "text": "\t\t\tQuery *parse = planstmt->parseTree;"}, {"n": 1732, "text": ""}, {"n": 1733, "text": "\t\t\t/* only handle multi-values without triggers */"}, {"n": 1734, "text": "\t\t\tif (parse->isMultiValues && !parse->hasUnshippableDml)"}, {"n": 1735, "text": "\t\t\t{"}, {"n": 1736, "text": "\t\t\t\tbool success;"}, {"n": 1737, "text": "\t\t\t\tInsertStmt *insert_stmt = (InsertStmt*)parsetree->stmt;"}, {"n": 1738, "text": ""}, {"n": 1739, "text": "\t\t\t\tplantree_list = transformInsertValuesIntoCopyFromPlan(NULL, insert_stmt, &success,"}, {"n": 1740, "text": "\t\t\t\t                                                      parse->copy_filename, parse);"}, {"n": 1741, "text": "\t\t\t}"}, {"n": 1742, "text": "\t\t}"}, {"n": 1743, "text": "#endif"}, {"n": 1744, "text": "\t\t/*"}, {"n": 1745, "text": "\t\t * We don't have to copy anything into the portal, because everything"}, {"n": 1746, "text": "\t\t * we are passing here is in MessageContext, which will outlive the"}, {"n": 1747, "text": "\t\t * portal anyway."}, {"n": 1748, "text": "\t\t */"}, {"n": 1749, "text": "\t\tPortalDefineQuery(portal,"}, {"n": 1750, "text": "\t\t\t\t\t\t  NULL,"}, {"n": 1751, "text": "\t\t\t\t\t\t  single_origin_query_str,"}, {"n": 1752, "text": "\t\t\t\t\t\t  commandTag,"}, {"n": 1753, "text": "\t\t\t\t\t\t  plantree_list,"}, {"n": 1754, "text": "\t\t\t\t\t\t  NULL);"}, {"n": 1755, "text": ""}, {"n": 1756, "text": "\t\t/*"}, {"n": 1757, "text": "\t\t * Start the portal.  No parameters here."}, {"n": 1758, "text": "\t\t */"}, {"n": 1759, "text": "\t\tPortalStart(portal, NULL, 0, InvalidSnapshot);"}, {"n": 1760, "text": ""}, {"n": 1761, "text": "\t\t/*"}, {"n": 1762, "text": "\t\t * Select the appropriate output format: text unless we are doing a"}, {"n": 1763, "text": "\t\t * FETCH from a binary cursor.  (Pretty grotty to have to do this here"}, {"n": 1764, "text": "\t\t * --- but it avoids grottiness in other places.  Ah, the joys of"}, {"n": 1765, "text": "\t\t * backward compatibility...)"}, {"n": 1766, "text": "\t\t */"}, {"n": 1767, "text": "\t\tformat = 0;\t\t\t\t/* TEXT is default */"}, {"n": 1768, "text": "\t\tif (IsA(parsetree->stmt, FetchStmt))"}, {"n": 1769, "text": "\t\t{"}, {"n": 1770, "text": "\t\t\tFetchStmt  *stmt = (FetchStmt *) parsetree->stmt;"}, {"n": 1771, "text": ""}, {"n": 1772, "text": "\t\t\tif (!stmt->ismove)"}, {"n": 1773, "text": "\t\t\t{"}, {"n": 1774, "text": "\t\t\t\tPortal\t\tfportal = GetPortalByName(stmt->portalname);"}, {"n": 1775, "text": ""}, {"n": 1776, "text": "\t\t\t\tif (PortalIsValid(fportal) &&"}, {"n": 1777, "text": "\t\t\t\t\t(fportal->cursorOptions & CURSOR_OPT_BINARY))"}, {"n": 1778, "text": "\t\t\t\t\tformat = 1; /* BINARY */"}, {"n": 1779, "text": "\t\t\t}"}, {"n": 1780, "text": "\t\t}"}, {"n": 1781, "text": "\t\tPortalSetResultFormat(portal, 1, &format);"}, {"n": 1782, "text": ""}, {"n": 1783, "text": "\t\t/*"}, {"n": 1784, "text": "\t\t * Now we can create the destination receiver object."}, {"n": 1785, "text": "\t\t */"}, {"n": 1786, "text": "\t\treceiver = CreateDestReceiver(dest);"}, {"n": 1787, "text": "\t\tif (dest == DestRemote)"}, {"n": 1788, "text": "\t\t{"}, {"n": 1789, "text": "\t\t\tSetRemoteDestReceiverParams(receiver, portal);"}, {"n": 1790, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 1791, "text": "\t\t\tif (relids != NULL)"}, {"n": 1792, "text": "\t\t\t\tSetRemoteDestReceiverResultCache(receiver, relids, queryid);"}, {"n": 1793, "text": "#endif"}, {"n": 1794, "text": "\t\t}"}, {"n": 1795, "text": ""}, {"n": 1796, "text": "\t\t/*"}, {"n": 1797, "text": "\t\t * Switch back to transaction context for execution."}, {"n": 1798, "text": "\t\t */"}, {"n": 1799, "text": "\t\tMemoryContextSwitchTo(oldcontext);"}, {"n": 1800, "text": ""}, {"n": 1801, "text": "\t\t/*"}, {"n": 1802, "text": "\t\t * Run the portal to completion, and then drop it (and the receiver)."}, {"n": 1803, "text": "\t\t */"}, {"n": 1804, "text": "\t\t(void) PortalRun(portal,"}, {"n": 1805, "text": "\t\t\t\t\t\t FETCH_ALL,"}, {"n": 1806, "text": "\t\t\t\t\t\t isTopLevel,"}, {"n": 1807, "text": "\t\t\t\t\t\t true,"}, {"n": 1808, "text": "\t\t\t\t\t\t receiver,"}, {"n": 1809, "text": "\t\t\t\t\t\t receiver,"}, {"n": 1810, "text": "\t\t\t\t\t\t completionTag);"}, {"n": 1811, "text": ""}, {"n": 1812, "text": "\t\treceiver->rDestroy(receiver);"}, {"n": 1813, "text": ""}, {"n": 1814, "text": "\t\tPortalDrop(portal, false);"}, {"n": 1815, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 1816, "text": "\t\t}"}, {"n": 1817, "text": "#endif"}, {"n": 1818, "text": ""}, {"n": 1819, "text": "\t\tif (IsA(parsetree->stmt, TransactionStmt))"}, {"n": 1820, "text": "\t\t{"}, {"n": 1821, "text": "#ifdef __AUDIT__"}, {"n": 1822, "text": "\t\t\tif (xact_started)"}, {"n": 1823, "text": "\t\t\t{"}, {"n": 1824, "text": "\t\t\t\tAuditProcessResultInfo(true);"}, {"n": 1825, "text": "\t\t\t}"}, {"n": 1826, "text": "#endif"}, {"n": 1827, "text": "\t\t\t/*"}, {"n": 1828, "text": "\t\t\t * If this was a transaction control statement, commit it. We will"}, {"n": 1829, "text": "\t\t\t * start a new xact command for the next command (if any)."}, {"n": 1830, "text": "\t\t\t */"}, {"n": 1831, "text": "\t\t\tfinish_xact_command();"}, {"n": 1832, "text": "\t\t}"}, {"n": 1833, "text": "\t\telse if (lnext(parsetree_item) == NULL)"}, {"n": 1834, "text": "\t\t{"}, {"n": 1835, "text": "#ifdef __AUDIT__"}, {"n": 1836, "text": "\t\t\tif (xact_started)"}, {"n": 1837, "text": "\t\t\t{"}, {"n": 1838, "text": "\t\t\t\tAuditProcessResultInfo(true);"}, {"n": 1839, "text": "\t\t\t}"}, {"n": 1840, "text": "#endif"}, {"n": 1841, "text": "\t\t\t/*"}, {"n": 1842, "text": "\t\t\t * If this is the last parsetree of the query string, close down"}, {"n": 1843, "text": "\t\t\t * transaction statement before reporting command-complete.  This"}, {"n": 1844, "text": "\t\t\t * is so that any end-of-transaction errors are reported before"}, {"n": 1845, "text": "\t\t\t * the command-complete message is issued, to avoid confusing"}, {"n": 1846, "text": "\t\t\t * clients who will expect either a command-complete message or an"}, {"n": 1847, "text": "\t\t\t * error, not one and then the other.  But for compatibility with"}, {"n": 1848, "text": "\t\t\t * historical Postgres behavior, we do not force a transaction"}, {"n": 1849, "text": "\t\t\t * boundary between queries appearing in a single query string."}, {"n": 1850, "text": "\t\t\t */"}, {"n": 1851, "text": "\t\t\tfinish_xact_command();"}, {"n": 1852, "text": "\t\t}"}, {"n": 1853, "text": "\t\telse"}, {"n": 1854, "text": "\t\t{"}, {"n": 1855, "text": "\t\t\t/*"}, {"n": 1856, "text": "\t\t\t * We need a CommandCounterIncrement after every query, except"}, {"n": 1857, "text": "\t\t\t * those that start or end a transaction block."}, {"n": 1858, "text": "\t\t\t */"}, {"n": 1859, "text": "\t\t\tCommandCounterIncrement();"}, {"n": 1860, "text": "\t\t}"}, {"n": 1861, "text": ""}, {"n": 1862, "text": "\t\t/*"}, {"n": 1863, "text": "\t\t * Tell client that we're done with this query.  Note we emit exactly"}, {"n": 1864, "text": "\t\t * one EndCommand report for each raw parsetree, thus one for each SQL"}, {"n": 1865, "text": "\t\t * command the client sent, regardless of rewriting. (But a command"}, {"n": 1866, "text": "\t\t * aborted by error will not send an EndCommand report at all.)"}, {"n": 1867, "text": "\t\t */"}, {"n": 1868, "text": "\t\tif (!multiCommands)"}, {"n": 1869, "text": "\t\t\tEndCommand(completionTag, dest);"}, {"n": 1870, "text": "\t}\t\t\t\t\t\t\t/* end loop over parsetrees */"}, {"n": 1871, "text": ""}, {"n": 1872, "text": "\tif (multiCommands)"}, {"n": 1873, "text": "\t\tEndCommand(\"MultiCommand\", dest);"}, {"n": 1874, "text": ""}, {"n": 1875, "text": "#ifdef __AUDIT__"}, {"n": 1876, "text": "\tif (xact_started)"}, {"n": 1877, "text": "\t{"}, {"n": 1878, "text": "\t\tAuditProcessResultInfo(true);"}, {"n": 1879, "text": "\t}"}, {"n": 1880, "text": "#endif"}, {"n": 1881, "text": ""}, {"n": 1882, "text": "\t/*"}, {"n": 1883, "text": "\t * Close down transaction statement, if one is open."}, {"n": 1884, "text": "\t */"}, {"n": 1885, "text": "\tfinish_xact_command();"}, {"n": 1886, "text": "\t/*"}, {"n": 1887, "text": "\t * If there were no parsetrees, return EmptyQueryResponse message."}, {"n": 1888, "text": "\t */"}, {"n": 1889, "text": "\tif (!parsetree_list)"}, {"n": 1890, "text": "\t\tNullCommand(dest);"}, {"n": 1891, "text": ""}, {"n": 1892, "text": "\t/*"}, {"n": 1893, "text": "\t * Emit duration logging if appropriate."}, {"n": 1894, "text": "\t */"}, {"n": 1895, "text": "\tswitch (check_log_duration(msec_str, was_logged))"}, {"n": 1896, "text": "\t{"}, {"n": 1897, "text": "\t\tcase 1:"}, {"n": 1898, "text": "\t\t\tereport(LOG,"}, {"n": 1899, "text": "\t\t\t\t\t(errmsg(\"duration: %s ms\", msec_str),"}, {"n": 1900, "text": "\t\t\t\t\t errhidestmt(true)));"}, {"n": 1901, "text": "\t\t\tbreak;"}, {"n": 1902, "text": "\t\tcase 2:"}, {"n": 1903, "text": "\t\t\tereport(LOG,"}, {"n": 1904, "text": "\t\t\t\t\t(errmsg(\"duration: %s ms  statement: %s\","}, {"n": 1905, "text": "\t\t\t\t\t\t\tmsec_str, query_string),"}, {"n": 1906, "text": "\t\t\t\t\t errhidestmt(true),"}, {"n": 1907, "text": "\t\t\t\t\t errdetail_execute(parsetree_list)));"}, {"n": 1908, "text": "\t\t\tbreak;"}, {"n": 1909, "text": "\t}"}, {"n": 1910, "text": ""}, {"n": 1911, "text": "\tif (save_log_statement_stats)"}, {"n": 1912, "text": "\t\tShowUsage(\"QUERY STATISTICS\");"}, {"n": 1913, "text": ""}, {"n": 1914, "text": "\tTRACE_POSTGRESQL_QUERY_DONE(query_string);"}, {"n": 1915, "text": ""}, {"n": 1916, "text": ""}, {"n": 1917, "text": ""}, {"n": 1918, "text": "\tdebug_query_string = NULL;"}, {"n": 1919, "text": "}"}, {"n": 1920, "text": ""}, {"n": 1921, "text": "/*"}]}, "planner": {"path": "src/backend/optimizer/plan/planner.c", "sha256": "338b049cd9d6be590a57d861764e16e391ffa75d65794e5cecbad003b5934ca1", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/backend/optimizer/plan/planner.c", "lines": [{"n": 355, "text": " * Note to plugin authors: standard_planner() scribbles on its Query input,"}, {"n": 356, "text": " * so you'd better copy that data structure if you want to plan more than once."}, {"n": 357, "text": " *"}, {"n": 358, "text": " *****************************************************************************/"}, {"n": 359, "text": "PlannedStmt *"}, {"n": 360, "text": "planner(Query *parse, int cursorOptions, ParamListInfo boundParams, "}, {"n": 361, "text": "\t\tint cached_param_num, bool explain)"}, {"n": 362, "text": "{"}, {"n": 363, "text": "\tPlannedStmt *result;"}, {"n": 364, "text": ""}, {"n": 365, "text": "\tplanning_dml_sql = false;"}, {"n": 366, "text": "\tif (is_parallel_allowed_for_modify(parse))"}, {"n": 367, "text": "\t\tplanning_dml_sql = true;"}, {"n": 368, "text": "\t"}, {"n": 369, "text": "\tif (planner_hook)"}, {"n": 370, "text": "\t\tresult = (*planner_hook) (parse, cursorOptions, boundParams, "}, {"n": 371, "text": "\t\t\t\t\t\t\t\t\tcached_param_num, explain);"}, {"n": 372, "text": "\telse"}, {"n": 373, "text": "#ifdef PGXC"}, {"n": 374, "text": "\t\t/*"}, {"n": 375, "text": "\t\t * A Coordinator receiving a query from another Coordinator"}, {"n": 376, "text": "\t\t * is not allowed to go into PGXC planner."}, {"n": 377, "text": "\t\t */"}, {"n": 378, "text": "\t\tif (IS_PGXC_LOCAL_COORDINATOR)"}, {"n": 379, "text": "\t\t\tresult = pgxc_planner(parse, cursorOptions, boundParams, "}, {"n": 380, "text": "\t\t\t\t\t\t\t\t\tcached_param_num, explain);"}, {"n": 381, "text": "\t\telse"}, {"n": 382, "text": "#endif"}, {"n": 383, "text": "\t\t\tresult = standard_planner(parse, cursorOptions, boundParams);"}, {"n": 384, "text": "\treturn result;"}, {"n": 385, "text": "}"}, {"n": 386, "text": ""}, {"n": 387, "text": "PlannedStmt *"}, {"n": 388, "text": "standard_planner(Query *parse, int cursorOptions, ParamListInfo boundParams)"}, {"n": 389, "text": "{"}, {"n": 390, "text": "\tPlannedStmt *result;"}, {"n": 391, "text": "\tPlannerGlobal *glob;"}, {"n": 392, "text": "\tdouble\t\ttuple_fraction;"}, {"n": 393, "text": "\tPlannerInfo *root;"}, {"n": 394, "text": "\tRelOptInfo *final_rel;"}, {"n": 395, "text": "\tPath\t   *best_path;"}, {"n": 396, "text": "\tPlan\t   *top_plan;"}, {"n": 397, "text": "\tListCell   *lp,"}, {"n": 398, "text": "\t\t\t   *lr;"}, {"n": 399, "text": "    RangeTblEntry *rte;"}, {"n": 400, "text": "    bool is_foreign_rte;"}, {"n": 401, "text": "    Query      *orig_query = copyObject(parse);"}, {"n": 402, "text": "\tbool        is_cursorstmt = false;"}, {"n": 403, "text": "\tbool is_hdfsforeign_rte = false;"}, {"n": 404, "text": "\tListCell   *lc;"}, {"n": 405, "text": ""}, {"n": 406, "text": "    /* has nextval and parallel safe */"}, {"n": 407, "text": "    bool nextval_parallel_safe = false;"}, {"n": 408, "text": ""}, {"n": 409, "text": "#ifdef XCP"}, {"n": 410, "text": "\tif (IS_PGXC_LOCAL_COORDINATOR && parse->utilityStmt &&"}, {"n": 411, "text": "\t\t\tIsA(parse->utilityStmt, RemoteQuery))"}, {"n": 412, "text": "\t\treturn pgxc_direct_planner(parse, cursorOptions, boundParams);"}, {"n": 413, "text": "#endif"}, {"n": 414, "text": "\t/*"}, {"n": 415, "text": "\t * Set up global state for this planner invocation.  This data is needed"}, {"n": 416, "text": "\t * across all levels of sub-Query that might exist in the given command,"}, {"n": 417, "text": "\t * so we keep it in a separate struct that's linked to by each per-Query"}, {"n": 418, "text": "\t * PlannerInfo."}, {"n": 419, "text": "\t */"}, {"n": 420, "text": "\tglob = makeNode(PlannerGlobal);"}, {"n": 421, "text": ""}, {"n": 422, "text": "\tglob->boundParams = boundParams;"}, {"n": 423, "text": "\tglob->subplans = NIL;"}, {"n": 424, "text": "\tglob->subroots = NIL;"}, {"n": 425, "text": "\tglob->subplan_nodes = NIL;"}, {"n": 426, "text": "\tglob->rewindPlanIDs = NULL;"}, {"n": 427, "text": "\tglob->finalrtable = NIL;"}, {"n": 428, "text": "\tglob->finalrowmarks = NIL;"}, {"n": 429, "text": "\tglob->resultRelations = NIL;"}, {"n": 430, "text": "\tglob->nonleafResultRelations = NIL;"}, {"n": 431, "text": "\tglob->rootResultRelations = NIL;"}, {"n": 432, "text": "\tglob->relationOids = NIL;"}, {"n": 433, "text": "\tglob->invalItems = NIL;"}, {"n": 434, "text": "\tglob->paramExecTypes = NIL;"}, {"n": 435, "text": "\tglob->lastPHId = 0;"}, {"n": 436, "text": "\tglob->lastRowMarkId = 0;"}, {"n": 437, "text": "\tglob->lastPlanNodeId = 0;"}, {"n": 438, "text": "\tglob->transientPlan = false;"}, {"n": 439, "text": "\tglob->dependsOnRole = false;"}, {"n": 440, "text": "\tglob->has_val_func = false;"}, {"n": 441, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 442, "text": "\tglob->sharedCtePlans = NULL;"}, {"n": 443, "text": "\tglob->sharedCtePlanIds = NULL;"}, {"n": 444, "text": "\tglob->subquery_seq_no = 1;"}, {"n": 445, "text": "\tglob->plannerinfo_seq_no = 1;"}, {"n": 446, "text": ""}, {"n": 447, "text": "\treset_internal_index();"}, {"n": 448, "text": "#endif"}, {"n": 449, "text": ""}, {"n": 450, "text": "\t/*"}, {"n": 451, "text": "\t * Assess whether it's feasible to use parallel mode for this query. We"}, {"n": 452, "text": "\t * can't do this in a standalone backend, or if the command will try to"}, {"n": 453, "text": "\t * modify any data (except for Insert), or if this is a cursor operation,"}, {"n": 454, "text": "\t * or if GUCs are set to values that don't permit parallelism, or if"}, {"n": 455, "text": "\t * parallel-unsafe functions are present in the query tree."}, {"n": 456, "text": "\t *"}, {"n": 457, "text": "\t * MATERIALIZED VIEW to use parallel plans, but as of now, only the leader"}, {"n": 458, "text": "\t * backend writes into a completely new table.  In the future, we can"}, {"n": 459, "text": "\t * extend it to allow workers to write into the table.  However, to allow"}, {"n": 460, "text": "\t * parallel updates and deletes, we have to solve other problems,"}, {"n": 461, "text": "\t * especially around combo CIDs.)"}, {"n": 462, "text": "\t *"}, {"n": 463, "text": "\t * For now, we don't try to use parallel mode if we're running inside a"}, {"n": 464, "text": "\t * parallel worker.  We might eventually be able to relax this"}, {"n": 465, "text": "\t * restriction, but for now it seems best not to have parallel workers"}, {"n": 466, "text": "\t * trying to create their own parallel workers."}, {"n": 467, "text": "\t *"}, {"n": 468, "text": "\t * We can't use parallelism in serializable mode because the predicate"}, {"n": 469, "text": "\t * locking code is not parallel-aware.  It's not catastrophic if someone"}, {"n": 470, "text": "\t * tries to run a parallel plan in serializable mode; it just won't get"}, {"n": 471, "text": "\t * any workers and will run serially.  But it seems like a good heuristic"}, {"n": 472, "text": "\t * to assume that the same serialization level will be in effect at plan"}, {"n": 473, "text": "\t * time and execution time, so don't generate a parallel plan if we're in"}, {"n": 474, "text": "\t * serializable mode."}, {"n": 475, "text": "\t */"}, {"n": 476, "text": "\tif ((cursorOptions & CURSOR_OPT_PARALLEL_OK) != 0 &&"}, {"n": 477, "text": "\t\tIsUnderPostmaster &&"}, {"n": 478, "text": "\t\tdynamic_shared_memory_type != DSM_IMPL_NONE &&"}, {"n": 479, "text": "\t\t(parse->commandType == CMD_SELECT ||"}, {"n": 480, "text": "\t\t is_parallel_allowed_for_modify(parse)) &&"}, {"n": 481, "text": "\t\t!parse->hasModifyingCTE &&"}, {"n": 482, "text": "\t\tmax_parallel_workers_per_gather > 0 &&"}, {"n": 483, "text": "\t\t!IsParallelWorker() &&"}, {"n": 484, "text": "\t\t!IsolationIsSerializable())"}, {"n": 485, "text": "\t{"}, {"n": 486, "text": "\t\t/* all the cheap tests pass, so scan the query tree */"}, {"n": 487, "text": "\t\tglob->maxParallelHazard = max_parallel_hazard(parse, &nextval_parallel_safe);"}, {"n": 488, "text": "\t\tglob->parallelModeOK = (glob->maxParallelHazard != PROPARALLEL_UNSAFE);"}, {"n": 489, "text": "\t}"}, {"n": 490, "text": "\telse"}, {"n": 491, "text": "\t{"}, {"n": 492, "text": "\t\t/* skip the query tree scan, just assume it's unsafe */"}, {"n": 493, "text": "\t\tglob->maxParallelHazard = PROPARALLEL_UNSAFE;"}, {"n": 494, "text": "\t\tglob->parallelModeOK = false;"}, {"n": 495, "text": "\t}"}, {"n": 496, "text": ""}, {"n": 497, "text": "\t/*"}, {"n": 498, "text": "\t * glob->parallelModeNeeded is normally set to false here and changed to"}, {"n": 499, "text": "\t * true during plan creation if a Gather or Gather Merge plan is actually"}, {"n": 500, "text": "\t * created (cf. create_gather_plan, create_gather_merge_plan)."}, {"n": 501, "text": "\t *"}, {"n": 502, "text": "\t * However, if force_parallel_mode = on or force_parallel_mode = regress,"}, {"n": 503, "text": "\t * then we impose parallel mode whenever it's safe to do so, even if the"}, {"n": 504, "text": "\t * final plan doesn't use parallelism.  It's not safe to do so if the"}, {"n": 505, "text": "\t * query contains anything parallel-unsafe; parallelModeOK will be false"}, {"n": 506, "text": "\t * in that case.  Note that parallelModeOK can't change after this point."}, {"n": 507, "text": "\t * Otherwise, everything in the query is either parallel-safe or"}, {"n": 508, "text": "\t * parallel-restricted, and in either case it should be OK to impose"}, {"n": 509, "text": "\t * parallel-mode restrictions.  If that ends up breaking something, then"}, {"n": 510, "text": "\t * either some function the user included in the query is incorrectly"}, {"n": 511, "text": "\t * labelled as parallel-safe or parallel-restricted when in reality it's"}, {"n": 512, "text": "\t * parallel-unsafe, or else the query planner itself has a bug."}, {"n": 513, "text": "\t */"}, {"n": 514, "text": "\tglob->parallelModeNeeded = glob->parallelModeOK &&"}, {"n": 515, "text": "\t\t(force_parallel_mode != FORCE_PARALLEL_OFF);"}, {"n": 516, "text": ""}, {"n": 517, "text": "\t/* Determine what fraction of the plan is likely to be scanned */"}, {"n": 518, "text": "\tif (cursorOptions & CURSOR_OPT_FAST_PLAN)"}, {"n": 519, "text": "\t{"}, {"n": 520, "text": "\t\t/*"}, {"n": 521, "text": "\t\t * We have no real idea how many tuples the user will ultimately FETCH"}, {"n": 522, "text": "\t\t * from a cursor, but it is often the case that he doesn't want 'em"}, {"n": 523, "text": "\t\t * all, or would prefer a fast-start plan anyway so that he can"}, {"n": 524, "text": "\t\t * process some of the tuples sooner.  Use a GUC parameter to decide"}, {"n": 525, "text": "\t\t * what fraction to optimize for."}, {"n": 526, "text": "\t\t */"}, {"n": 527, "text": "\t\ttuple_fraction = cursor_tuple_fraction;"}, {"n": 528, "text": ""}, {"n": 529, "text": "\t\t/*"}, {"n": 530, "text": "\t\t * We document cursor_tuple_fraction as simply being a fraction, which"}, {"n": 531, "text": "\t\t * means the edge cases 0 and 1 have to be treated specially here.  We"}, {"n": 532, "text": "\t\t * convert 1 to 0 (\"all the tuples\") and 0 to a very small fraction."}, {"n": 533, "text": "\t\t */"}, {"n": 534, "text": "\t\tif (tuple_fraction >= 1.0)"}, {"n": 535, "text": "\t\t\ttuple_fraction = 0.0;"}, {"n": 536, "text": "\t\telse if (tuple_fraction <= 0.0)"}, {"n": 537, "text": "\t\t\ttuple_fraction = 1e-10;"}, {"n": 538, "text": "\t}"}, {"n": 539, "text": "\telse"}, {"n": 540, "text": "\t{"}, {"n": 541, "text": "\t\t/* Default assumption is we need all the tuples */"}, {"n": 542, "text": "\t\ttuple_fraction = 0.0;"}, {"n": 543, "text": "\t}"}, {"n": 544, "text": "\t/* primary planning entry point (may recurse for subqueries) */"}, {"n": 545, "text": "\troot = subquery_planner(glob, parse, NULL,"}, {"n": 546, "text": "\t\t\t\t\t\t\tfalse, tuple_fraction);"}, {"n": 547, "text": ""}, {"n": 548, "text": "\t/* Select best Path and turn it into a Plan */"}, {"n": 549, "text": "\tfinal_rel = fetch_upper_rel(root, UPPERREL_FINAL, NULL);"}, {"n": 550, "text": "\tbest_path = get_cheapest_fractional_path(final_rel, tuple_fraction);"}, {"n": 551, "text": ""}, {"n": 552, "text": "    if (IsA(best_path, ModifyTablePath) && IS_CENTRALIZED_DATANODE && root -> parallel_dml)"}, {"n": 553, "text": "    {"}, {"n": 554, "text": "        best_path->total_cost -= best_path->dml_cost;"}, {"n": 555, "text": "    }"}, {"n": 556, "text": ""}, {"n": 557, "text": "\tif (!root->distribution && !IS_CENTRALIZED_MODE)"}, {"n": 558, "text": "\t\troot->distribution = best_path->distribution;"}, {"n": 559, "text": ""}, {"n": 560, "text": "#ifdef __OPENTENBASE__"}, {"n": 561, "text": "\tif (root->distribution && !parse->hasUnshippableDml)"}, {"n": 562, "text": "\t{"}, {"n": 563, "text": "\t    remote_subplan_depth++;"}, {"n": 564, "text": "\t}"}, {"n": 565, "text": "#endif"}, {"n": 566, "text": ""}, {"n": 567, "text": "\ttop_plan = create_plan(root, best_path);"}, {"n": 568, "text": "#ifdef XCP"}, {"n": 569, "text": "#ifdef __OPENTENBASE__"}, {"n": 570, "text": "\t/* dblink supports DML:insert/update/delete */"}, {"n": 571, "text": "    is_foreign_rte = false;"}, {"n": 572, "text": "    if (root->parse->resultRelation)"}, {"n": 573, "text": "\t{"}, {"n": 574, "text": "        rte = rt_fetch(root->parse->resultRelation, root->parse->rtable);"}, {"n": 575, "text": "\t\tis_foreign_rte = (rte->relkind == RELKIND_FOREIGN_TABLE && "}, {"n": 576, "text": "\t\t\t\t\t\t\t!rel_is_external_table(rte->relid) &&"}, {"n": 577, "text": "\t\t\t\t\t\t\t!rel_is_hdfsfdw_table(rte->relid));"}, {"n": 578, "text": "    }"}, {"n": 579, "text": "\tif (root->distribution && !parse->hasUnshippableDml && !is_foreign_rte)"}, {"n": 580, "text": "#else"}, {"n": 581, "text": "\tif (root->distribution)"}, {"n": 582, "text": "#endif"}, {"n": 583, "text": "\t{"}, {"n": 584, "text": "\t\t/*"}, {"n": 585, "text": "         * If distribution is needed, we need pass the sort information"}, {"n": 586, "text": "         * to remote plan so that cn can sort results from distributed"}, {"n": 587, "text": "         * dns. But when \"order by\" in the inner layer of the SQL "}, {"n": 588, "text": "         * statement, the sort information will be generated in the "}, {"n": 589, "text": "         * subplan so that we can't generate remote plan with top_plan"}, {"n": 590, "text": "         * directly. In order to generate remote plan corretly, we "}, {"n": 591, "text": "         * pass subplan that owns sort information to remote subplan."}, {"n": 592, "text": "         */"}, {"n": 593, "text": "\t\tbool remote_set = false;"}, {"n": 594, "text": "\t\tif (IsA(best_path, SubqueryScanPath) && IsA(top_plan, SubqueryScan))"}, {"n": 595, "text": "\t\t{"}, {"n": 596, "text": "\t\t\tSubqueryScan    *sub_plan = (SubqueryScan *) top_plan;"}, {"n": 597, "text": "\t\t\tAssert(best_path->parent && best_path->parent->subroot);"}, {"n": 598, "text": ""}, {"n": 599, "text": "\t\t\t/*"}, {"n": 600, "text": "\t\t\t * We use subroot here to solve the sitution that the plan"}, {"n": 601, "text": "\t\t\t * doesn't have a sort operator but need to merge sort."}, {"n": 602, "text": "\t\t\t */"}, {"n": 603, "text": "\t\t\tif (best_path->parent->subroot->sort_pathkeys)"}, {"n": 604, "text": "\t\t\t{"}, {"n": 605, "text": "\t\t\t\tsub_plan->subplan ="}, {"n": 606, "text": "\t\t\t\t\t(Plan *) make_remotesubplan(root, sub_plan->subplan, NULL,"}, {"n": 607, "text": "\t\t\t\t\t\t\t\t\t\t\t\troot->distribution,"}, {"n": 608, "text": "\t\t\t\t\t\t\t\t\t\t\t\tbest_path->parent->subroot->sort_pathkeys,"}, {"n": 609, "text": "\t\t\t\t\t\t\t\t\t\t\t\tfalse,"}, {"n": 610, "text": "\t\t\t\t\t\t\t\t\t\t\t\tbest_path->parent->relids);"}, {"n": 611, "text": "\t\t\t\tremote_set = true;"}, {"n": 612, "text": "\t\t\t}"}, {"n": 613, "text": "\t\t}"}, {"n": 614, "text": "\t\tif (!remote_set)"}, {"n": 615, "text": "\t\t{"}, {"n": 616, "text": "\t\t\t/*"}, {"n": 617, "text": "\t\t\t * FIXME, this keeps adding RemoteSubplan at a top of queries that"}, {"n": 618, "text": "\t\t\t * don't really need it (e.g above a MergeAppend with subplans pushed"}, {"n": 619, "text": "\t\t\t * to remote nodes). Not sure why it's happening, though ..."}, {"n": 620, "text": "\t\t\t */"}, {"n": 621, "text": "\t\t\ttop_plan = (Plan *) make_remotesubplan(root, top_plan, NULL,"}, {"n": 622, "text": "\t\t\t\t\t\t\t\t\t\t\t\t   root->distribution,"}, {"n": 623, "text": "\t\t\t\t\t\t\t\t\t\t\t\t   root->sort_pathkeys ? root->sort_pathkeys : best_path->pathkeys,"}, {"n": 624, "text": "\t\t\t\t\t\t\t\t\t\t\t\t   false,"}, {"n": 625, "text": "\t\t\t\t\t\t\t\t\t\t\t\t   best_path->parent->relids);"}, {"n": 626, "text": "\t\t}"}, {"n": 627, "text": "\t\tif ((parse->commandType == CMD_UPDATE || parse->commandType == CMD_DELETE ||"}, {"n": 628, "text": "\t\t     parse->commandType == CMD_INSERT || parse->commandType == CMD_MERGE) &&"}, {"n": 629, "text": "\t\t    (root->distribution->distributionType == LOCATOR_TYPE_SHARD ||"}, {"n": 630, "text": "\t\t     root->distribution->distributionType == LOCATOR_TYPE_HASH))"}, {"n": 631, "text": "\t\t{"}, {"n": 632, "text": "\t\t\tModifyTable *mt = NULL;"}, {"n": 633, "text": "\t\t\tPlan        *old_plan = top_plan;"}, {"n": 634, "text": "\t\t\t"}, {"n": 635, "text": "\t\t\t/*"}, {"n": 636, "text": "\t\t\t * The plan now should be like:"}, {"n": 637, "text": "\t\t\t * Remote Subquery Scan"}, {"n": 638, "text": "\t\t\t *      -> Update"}, {"n": 639, "text": "\t\t\t *              -> Some scan or Join"}, {"n": 640, "text": "\t\t\t */"}, {"n": 641, "text": "\t\t\tAssert(IsA(top_plan, RemoteSubplan));"}, {"n": 642, "text": "\t\t\tAssert(IsA(top_plan->lefttree, ModifyTable) || IsA(top_plan->lefttree, MultiModifyTable));"}, {"n": 643, "text": ""}, {"n": 644, "text": "\t\t\t/* MultiModifyTable no need do it. */"}, {"n": 645, "text": "\t\t\tif (IsA(top_plan->lefttree, ModifyTable))"}, {"n": 646, "text": "\t\t\t{"}, {"n": 647, "text": "\t\t\t\tmt = (ModifyTable *) top_plan->lefttree;"}, {"n": 648, "text": "\t\t\t\ttop_plan = make_remote_modifytable(root, top_plan, mt);"}, {"n": 649, "text": "\t\t\t}"}, {"n": 650, "text": "\t\t\tif (old_plan != top_plan)"}, {"n": 651, "text": "\t\t\t\tSS_attach_initplans(root, top_plan);"}, {"n": 652, "text": "\t\t}"}, {"n": 653, "text": "\t\tremote_subplan_depth--;"}, {"n": 654, "text": "\t}"}, {"n": 655, "text": "#endif"}, {"n": 656, "text": ""}, {"n": 657, "text": "\t/* if exist hdfs fdw foreign table, deny to FQS*/"}, {"n": 658, "text": "\tforeach(lc, root->parse->rtable)"}, {"n": 659, "text": "\t{"}, {"n": 660, "text": "\t\tRangeTblEntry *rte = (RangeTblEntry *) lfirst(lc);"}, {"n": 661, "text": "\t\tis_hdfsforeign_rte = (rte->relkind == RELKIND_FOREIGN_TABLE && rel_is_hdfsfdw_table(rte->relid));"}, {"n": 662, "text": "\t\tif (is_hdfsforeign_rte) "}, {"n": 663, "text": "\t\t\tbreak;"}, {"n": 664, "text": "\t}"}, {"n": 665, "text": ""}, {"n": 666, "text": "\tis_cursorstmt = cursorOptions & (CURSOR_OPT_BINARY | CURSOR_OPT_SCROLL | CURSOR_OPT_NO_SCROLL |"}, {"n": 667, "text": "\t                                 CURSOR_OPT_INSENSITIVE | CURSOR_OPT_HOLD);"}, {"n": 668, "text": ""}, {"n": 669, "text": "\t/*"}, {"n": 670, "text": "\t * The currently supported SQL features for FQS (Fast Query Shipping) are as follows:"}, {"n": 671, "text": "\t * Requirements: Non-user-defined functions, non-for-update statements, non-global indexes, non-cursor"}, {"n": 672, "text": "\t * operations, and the statement must be a SELECT query."}, {"n": 673, "text": "\t *"}, {"n": 674, "text": "\t * Additional support is provided for executing"}, {"n": 675, "text": "\t * distributed queries spanning multiple nodes, but only if there is a single layer of remote subplan"}, {"n": 676, "text": "\t * at the topmost level, allowing it to qualify for FQS."}, {"n": 677, "text": "\t */"}, {"n": 678, "text": "\tif (enable_fast_query_shipping &&"}, {"n": 679, "text": "\t\tparse->canShip &&"}, {"n": 680, "text": "\t    (list_length(glob->execNodeSet) == 1 ||"}, {"n": 681, "text": "\t     (list_length(glob->execNodeSet) > 1 && glob->remotesubplan_nums == 1 &&"}, {"n": 682, "text": "\t      IsA(top_plan, RemoteSubplan) && ((RemoteSubplan *) top_plan)->sort == NULL)) &&"}, {"n": 683, "text": "\t\tglob->lastRowMarkId == 0 &&"}, {"n": 684, "text": "\t\t!glob->has_gidx_plan &&"}, {"n": 685, "text": "\t\t!is_cursorstmt &&"}, {"n": 686, "text": "\t\t!is_hdfsforeign_rte &&"}, {"n": 687, "text": "\t\tparse->commandType == CMD_SELECT)"}, {"n": 688, "text": "\t{"}, {"n": 689, "text": "\t\tQuery     *query = orig_query;"}, {"n": 690, "text": "\t\tList      *rte_list = NULL;"}, {"n": 691, "text": "\t\tExecNodes *exec_nodes = makeNode(ExecNodes);"}, {"n": 692, "text": ""}, {"n": 693, "text": "\t\texec_nodes->nodeList = glob->execNodeSet;"}, {"n": 694, "text": "\t\ttop_plan = (Plan *) pgxc_FQS_create_remote_plan(query, exec_nodes, false, FQS_MODE_STD_PLANER);"}, {"n": 695, "text": ""}, {"n": 696, "text": "\t\tif (query->returningList)"}, {"n": 697, "text": "\t\t\ttop_plan->targetlist = query->returningList;"}, {"n": 698, "text": ""}, {"n": 699, "text": "\t\ttop_plan = set_plan_references(root, top_plan);"}, {"n": 700, "text": ""}, {"n": 701, "text": "\t\t/* build the PlannedStmt result */"}, {"n": 702, "text": "\t\tresult = makeNode(PlannedStmt);"}, {"n": 703, "text": "\t\t/* Try and set what we can, rest must have been zeroed out by makeNode() */"}, {"n": 704, "text": "\t\tresult->commandType = query->commandType;"}, {"n": 705, "text": "\t\tresult->canSetTag = query->canSetTag;"}, {"n": 706, "text": "\t\tresult->utilityStmt = query->utilityStmt;"}, {"n": 707, "text": ""}, {"n": 708, "text": "\t\tresult->planTree = top_plan;"}, {"n": 709, "text": "\t\tresult->rtable = query->rtable;"}, {"n": 710, "text": "\t\tresult->queryId = query->queryId;"}, {"n": 711, "text": "\t\tresult->relationOids = glob->relationOids;"}, {"n": 712, "text": "\t\tresult->invalItems = glob->invalItems;"}, {"n": 713, "text": "\t\tresult->rowMarks = glob->finalrowmarks;"}, {"n": 714, "text": "\t\tresult->hasReturning = (query->returningList != NULL);"}, {"n": 715, "text": "\t\tflatten_unplanned_query(&rte_list, query);"}, {"n": 716, "text": "\t\tresult->fqs_rte_list = rte_list;"}, {"n": 717, "text": ""}, {"n": 718, "text": "\t\tresult->p_has_val_func = glob->has_val_func;"}, {"n": 719, "text": "\t\tSetSPMUnsupported();"}, {"n": 720, "text": "\t\treturn result;"}, {"n": 721, "text": "\t}"}, {"n": 722, "text": ""}, {"n": 723, "text": "\t/*"}, {"n": 724, "text": "\t * If creating a plan for a scrollable cursor, make sure it can run"}, {"n": 725, "text": "\t * backwards on demand.  Add a Material node at the top at need."}, {"n": 726, "text": "\t */"}, {"n": 727, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 728, "text": "\tif ((cursorOptions & CURSOR_OPT_SCROLL) || parse->cursor_opt_scroll)"}, {"n": 729, "text": "#else"}, {"n": 730, "text": "\tif (cursorOptions & CURSOR_OPT_SCROLL)"}, {"n": 731, "text": "#endif"}, {"n": 732, "text": "\t{"}, {"n": 733, "text": "\t\tPlan\t*old_plan = top_plan;"}, {"n": 734, "text": ""}, {"n": 735, "text": "\t\tif (!ExecSupportsBackwardScan(top_plan))"}, {"n": 736, "text": "\t\t\ttop_plan = materialize_finished_plan(top_plan);"}, {"n": 737, "text": "\t\t"}, {"n": 738, "text": "\t\tif (IS_PGXC_LOCAL_COORDINATOR)"}, {"n": 739, "text": "\t\t\ttop_plan->remote_flag = -1; /* force*/"}, {"n": 740, "text": "\t\t"}, {"n": 741, "text": "\t\tif (old_plan != top_plan)"}, {"n": 742, "text": "\t\t\tSS_attach_initplans(root, top_plan);"}, {"n": 743, "text": "\t}"}, {"n": 744, "text": ""}, {"n": 745, "text": "\t/*"}, {"n": 746, "text": "\t * Optionally add a Gather node for testing purposes, provided this is"}, {"n": 747, "text": "\t * actually a safe thing to do."}, {"n": 748, "text": "\t */"}, {"n": 749, "text": "\tif (force_parallel_mode != FORCE_PARALLEL_OFF && top_plan->parallel_safe &&"}, {"n": 750, "text": "\t\t!IS_PGXC_COORDINATOR)"}, {"n": 751, "text": "\t{"}, {"n": 752, "text": "\t\tGather\t   *gather = makeNode(Gather);"}, {"n": 753, "text": ""}, {"n": 754, "text": "\t\t/*"}, {"n": 755, "text": "\t\t * If there are any initPlans attached to the formerly-top plan node,"}, {"n": 756, "text": "\t\t * move them up to the Gather node; same as we do for Material node in"}, {"n": 757, "text": "\t\t * materialize_finished_plan."}, {"n": 758, "text": "\t\t */"}, {"n": 759, "text": "\t\tgather->plan.initPlan = top_plan->initPlan;"}, {"n": 760, "text": "\t\ttop_plan->initPlan = NIL;"}, {"n": 761, "text": ""}, {"n": 762, "text": "\t\tgather->plan.targetlist = top_plan->targetlist;"}, {"n": 763, "text": "\t\tgather->plan.qual = NIL;"}, {"n": 764, "text": "\t\tgather->plan.lefttree = top_plan;"}, {"n": 765, "text": "\t\tgather->plan.righttree = NULL;"}, {"n": 766, "text": "\t\tgather->num_workers = 1;"}, {"n": 767, "text": "\t\tgather->single_copy = true;"}, {"n": 768, "text": "\t\tgather->invisible = (force_parallel_mode == FORCE_PARALLEL_REGRESS);"}, {"n": 769, "text": ""}, {"n": 770, "text": "\t\t/*"}, {"n": 771, "text": "\t\t * Since this Gather has no parallel-aware descendants to signal to,"}, {"n": 772, "text": "\t\t * we don't need a rescan Param."}, {"n": 773, "text": "\t\t */"}, {"n": 774, "text": "\t\tgather->rescan_param = -1;"}, {"n": 775, "text": ""}, {"n": 776, "text": "\t\t/*"}, {"n": 777, "text": "\t\t * Ideally we'd use cost_gather here, but setting up dummy path data"}, {"n": 778, "text": "\t\t * to satisfy it doesn't seem much cleaner than knowing what it does."}, {"n": 779, "text": "\t\t */"}, {"n": 780, "text": "\t\tgather->plan.startup_cost = top_plan->startup_cost +"}, {"n": 781, "text": "\t\t\tparallel_setup_cost;"}, {"n": 782, "text": "\t\tgather->plan.total_cost = top_plan->total_cost +"}, {"n": 783, "text": "\t\t\tparallel_setup_cost + parallel_tuple_cost * top_plan->plan_rows;"}, {"n": 784, "text": "\t\tgather->plan.plan_rows = top_plan->plan_rows;"}, {"n": 785, "text": "\t\tgather->plan.plan_width = top_plan->plan_width;"}, {"n": 786, "text": "\t\tgather->plan.parallel_aware = false;"}, {"n": 787, "text": "\t\tgather->plan.parallel_safe = false;"}, {"n": 788, "text": ""}, {"n": 789, "text": "\t\t/* use parallel mode for parallel plans. */"}, {"n": 790, "text": "\t\troot->glob->parallelModeNeeded = true;"}, {"n": 791, "text": ""}, {"n": 792, "text": "\t\ttop_plan = &gather->plan;"}, {"n": 793, "text": "\t}"}, {"n": 794, "text": ""}, {"n": 795, "text": "\t/*"}, {"n": 796, "text": "\t * If any Params were generated, run through the plan tree and compute"}, {"n": 797, "text": "\t * each plan node's extParam/allParam sets.  Ideally we'd merge this into"}, {"n": 798, "text": "\t * set_plan_references' tree traversal, but for now it has to be separate"}, {"n": 799, "text": "\t * because we need to visit subplans before not after main plan."}, {"n": 800, "text": "\t *"}, {"n": 801, "text": "\t * Although there are no parameters, the right tree of the connect by"}, {"n": 802, "text": "\t * clause must be under the subplan."}, {"n": 803, "text": "\t */"}, {"n": 804, "text": "\tif (glob->paramExecTypes != NIL || parse->connectByExpr != NULL)"}, {"n": 805, "text": "\t{"}, {"n": 806, "text": "\t\tAssert(list_length(glob->subplans) == list_length(glob->subroots));"}, {"n": 807, "text": "\t\tforboth(lp, glob->subplans, lr, glob->subroots)"}, {"n": 808, "text": "\t\t{"}, {"n": 809, "text": "\t\t\tPlan\t   *subplan = (Plan *) lfirst(lp);"}, {"n": 810, "text": "\t\t\tPlannerInfo *subroot = (PlannerInfo *) lfirst(lr);"}, {"n": 811, "text": ""}, {"n": 812, "text": "\t\t\tSS_finalize_plan(subroot, subplan);"}, {"n": 813, "text": "\t\t}"}, {"n": 814, "text": "\t\tSS_finalize_plan(root, top_plan);"}, {"n": 815, "text": ""}, {"n": 816, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 817, "text": "\t\t/* adjust plan (for subplan (including withrecursive) and nestloop) */"}, {"n": 818, "text": "\t\tif (IS_PGXC_COORDINATOR)"}, {"n": 819, "text": "\t\t{"}, {"n": 820, "text": "\t\t\tforeach(lp, glob->subplans)"}, {"n": 821, "text": "\t\t\t{"}, {"n": 822, "text": "\t\t\t\tPlan\t   *subplan = (Plan *) lfirst(lp);"}, {"n": 823, "text": ""}, {"n": 824, "text": "\t\t\t\tif (subplan->is_subplan || subplan->extParam)"}, {"n": 825, "text": "\t\t\t\t\tlfirst(lp) = SS_adjust_plan(subplan, true);"}, {"n": 826, "text": "\t\t\t\telse"}, {"n": 827, "text": "\t\t\t\t\t(void) SS_adjust_plan(subplan, false);"}, {"n": 828, "text": "\t\t\t}"}, {"n": 829, "text": "\t\t\t(void) SS_adjust_plan(top_plan, false);"}, {"n": 830, "text": "\t\t}"}, {"n": 831, "text": "#endif"}, {"n": 832, "text": "\t}"}, {"n": 833, "text": ""}, {"n": 834, "text": "\t/* final cleanup of the plan */"}, {"n": 835, "text": "\tAssert(glob->finalrtable == NIL);"}, {"n": 836, "text": "\tAssert(glob->finalrowmarks == NIL);"}, {"n": 837, "text": "\tAssert(glob->resultRelations == NIL);"}, {"n": 838, "text": "\tAssert(glob->nonleafResultRelations == NIL);"}, {"n": 839, "text": "\tAssert(glob->rootResultRelations == NIL);"}, {"n": 840, "text": "\ttop_plan = set_plan_references(root, top_plan);"}, {"n": 841, "text": "\t/* ... and the subplans (both regular subplans and initplans) */"}, {"n": 842, "text": "\tAssert(list_length(glob->subplans) == list_length(glob->subroots));"}, {"n": 843, "text": ""}, {"n": 844, "text": "\tglob->exec_subplan = list_concat_unique_ptr(glob->exec_subplan, root->init_plans);"}, {"n": 845, "text": ""}, {"n": 846, "text": "\tforboth(lp, glob->subplans, lr, glob->subroots)"}, {"n": 847, "text": "\t{"}, {"n": 848, "text": "\t\tPlan\t   *subplan = (Plan *) lfirst(lp);"}, {"n": 849, "text": "\t\tPlannerInfo *subroot = (PlannerInfo *) lfirst(lr);"}, {"n": 850, "text": ""}, {"n": 851, "text": "\t\tlfirst(lp) = set_plan_references(subroot, subplan);"}, {"n": 852, "text": ""}, {"n": 853, "text": "\t\tglob->exec_subplan = list_concat_unique_ptr(glob->exec_subplan, subroot->init_plans);"}, {"n": 854, "text": "\t\tSS_set_subplan(subroot, lfirst(lp));"}, {"n": 855, "text": "\t}"}, {"n": 856, "text": ""}, {"n": 857, "text": "\tSS_set_subplan(root, top_plan);"}, {"n": 858, "text": ""}, {"n": 859, "text": "\t/*"}, {"n": 860, "text": "\t * Redirect initplan of top_plan, if it's not a remote fragment,"}, {"n": 861, "text": "\t * it must be root fragment"}, {"n": 862, "text": "\t */"}, {"n": 863, "text": "\tif (!IsA(top_plan, RemoteSubplan) && IS_PGXC_COORDINATOR)"}, {"n": 864, "text": "\t{"}, {"n": 865, "text": "\t\t/* attach any unprocessed initplans to top_plan */"}, {"n": 866, "text": "\t\ttop_plan->exec_subplan ="}, {"n": 867, "text": "\t\t\tlist_concat_unique_ptr(top_plan->exec_subplan, glob->exec_subplan);"}, {"n": 868, "text": "\t\tredirect_remote_subplan_send(glob, top_plan);"}, {"n": 869, "text": "\t}"}, {"n": 870, "text": ""}, {"n": 871, "text": "\t/* build the PlannedStmt result */"}, {"n": 872, "text": "\tresult = makeNode(PlannedStmt);"}, {"n": 873, "text": ""}, {"n": 874, "text": "\tresult->commandType = parse->commandType;"}, {"n": 875, "text": "\tresult->queryId = parse->queryId;"}, {"n": 876, "text": "\tresult->hasReturning = (parse->returningList != NIL);"}, {"n": 877, "text": "\tresult->hasModifyingCTE = parse->hasModifyingCTE;"}, {"n": 878, "text": "\tresult->canSetTag = parse->canSetTag;"}, {"n": 879, "text": "\tresult->transientPlan = glob->transientPlan;"}, {"n": 880, "text": "\tresult->dependsOnRole = glob->dependsOnRole;"}, {"n": 881, "text": "\tresult->parallelModeNeeded = glob->parallelModeNeeded;"}, {"n": 882, "text": "    result->canNextvalParallel = nextval_parallel_safe;"}, {"n": 883, "text": "\tresult->planTree = top_plan;"}, {"n": 884, "text": "\tresult->rtable = glob->finalrtable;"}, {"n": 885, "text": "\tresult->resultRelations = glob->resultRelations;"}, {"n": 886, "text": "\tresult->nonleafResultRelations = glob->nonleafResultRelations;"}, {"n": 887, "text": "\tresult->rootResultRelations = glob->rootResultRelations;"}, {"n": 888, "text": "\tresult->subplans = glob->subplans;"}, {"n": 889, "text": "\tresult->rewindPlanIDs = glob->rewindPlanIDs;"}, {"n": 890, "text": "\tresult->rowMarks = glob->finalrowmarks;"}, {"n": 891, "text": "\tresult->relationOids = glob->relationOids;"}, {"n": 892, "text": "\tresult->invalItems = glob->invalItems;"}, {"n": 893, "text": "\tresult->paramExecTypes = glob->paramExecTypes;"}, {"n": 894, "text": "\tresult->p_has_val_func = glob->has_val_func;"}, {"n": 895, "text": ""}, {"n": 896, "text": "\t/* utilityStmt should be null, but we might as well copy it */"}, {"n": 897, "text": "\tresult->utilityStmt = parse->utilityStmt;"}, {"n": 898, "text": "\tresult->stmt_location = parse->stmt_location;"}, {"n": 899, "text": "\tresult->stmt_len = parse->stmt_len;"}, {"n": 900, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 901, "text": "\tresult->sharedCtePlans = glob->sharedCtePlans;"}, {"n": 902, "text": "\tresult->sharedCtePlanIds = glob->sharedCtePlanIds;"}, {"n": 903, "text": "\t/* Add the shared CTE fragments and root fragment as total */"}, {"n": 904, "text": "\tresult->fragmentNum = glob->fragmentNum + list_length(glob->sharedCtePlans) + 1;"}, {"n": 905, "text": "\tresult->guc_str = NULL;"}, {"n": 906, "text": ""}, {"n": 907, "text": "\tif (query_mem > 0 || IsResGroupActivated())"}, {"n": 908, "text": "\t{"}, {"n": 909, "text": "\t\t/*"}, {"n": 910, "text": "\t\t * When query_mem is set, we calculate the total memory used by"}, {"n": 911, "text": "\t\t * the plan tree. If the estimated memory is larger than query_mem,"}, {"n": 912, "text": "\t\t * we adjust it to query_mem by reducing work_mem."}, {"n": 913, "text": "\t\t * The value will be used in resource control."}, {"n": 914, "text": "\t\t */"}, {"n": 915, "text": "\t\tint curr_query_mem = query_mem;"}, {"n": 916, "text": ""}, {"n": 917, "text": "\t\tif (IsResGroupActivated())"}, {"n": 918, "text": "\t\t{"}, {"n": 919, "text": "\t\t\t/* reset query_mem for current query if resgroup activated */"}, {"n": 920, "text": "\t\t\tint groupMemLimit = ResourceGroupGetQueryMemoryLimit();"}, {"n": 921, "text": ""}, {"n": 922, "text": "\t\t\tif (groupMemLimit > 0)"}, {"n": 923, "text": "\t\t\t{"}, {"n": 924, "text": "\t\t\t\tif (curr_query_mem == 0 || curr_query_mem > groupMemLimit)"}, {"n": 925, "text": "\t\t\t\t\tcurr_query_mem = Max(groupMemLimit, SIMPLE_QUERY_THRESHOLD);"}, {"n": 926, "text": "\t\t\t}"}, {"n": 927, "text": "\t\t}"}, {"n": 928, "text": ""}, {"n": 929, "text": "\t\tif (curr_query_mem > 0)"}, {"n": 930, "text": "\t\t\tset_plan_querymem(result, curr_query_mem);"}, {"n": 931, "text": "\t}"}, {"n": 932, "text": "#endif"}, {"n": 933, "text": ""}, {"n": 934, "text": "\tresult->jitFlags = PGJIT_NONE;"}, {"n": 935, "text": "\tif (jit_enabled && jit_above_cost >= 0 &&"}, {"n": 936, "text": "\t\ttop_plan->total_cost > jit_above_cost &&"}, {"n": 937, "text": "\t\texperiment_feature && !ORA_MODE)"}, {"n": 938, "text": "\t{"}, {"n": 939, "text": "\t\tresult->jitFlags |= PGJIT_PERFORM;"}, {"n": 940, "text": ""}, {"n": 941, "text": "\t\t/*"}, {"n": 942, "text": "\t\t * Decide how much effort should be put into generating better code."}, {"n": 943, "text": "\t\t */"}, {"n": 944, "text": "\t\tif (jit_optimize_above_cost >= 0 &&"}, {"n": 945, "text": "\t\t\ttop_plan->total_cost > jit_optimize_above_cost)"}, {"n": 946, "text": "\t\t\tresult->jitFlags |= PGJIT_OPT3;"}, {"n": 947, "text": "\t\tif (jit_inline_above_cost >= 0 &&"}, {"n": 948, "text": "\t\t\ttop_plan->total_cost > jit_inline_above_cost)"}, {"n": 949, "text": "\t\t\tresult->jitFlags |= PGJIT_INLINE;"}, {"n": 950, "text": ""}, {"n": 951, "text": "\t\t/*"}, {"n": 952, "text": "\t\t * Decide which operations should be JITed."}, {"n": 953, "text": "\t\t */"}, {"n": 954, "text": "\t\tif (jit_expressions)"}, {"n": 955, "text": "\t\t\tresult->jitFlags |= PGJIT_EXPR;"}, {"n": 956, "text": "\t\tif (jit_tuple_deforming)"}, {"n": 957, "text": "\t\t\tresult->jitFlags |= PGJIT_DEFORM;"}, {"n": 958, "text": "\t}"}, {"n": 959, "text": ""}, {"n": 960, "text": "\treturn result;"}, {"n": 961, "text": "}"}, {"n": 962, "text": ""}, {"n": 963, "text": "/*"}]}, "fqs": {"path": "src/backend/pgxc/plan/planner.c", "sha256": "d0a0eda12093590b6180ff6b9992788e25270e669f463540fab24660f8660cc0", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/backend/pgxc/plan/planner.c", "lines": [{"n": 232, "text": " *    again we use standard_planner() to plan the statement."}, {"n": 233, "text": " *"}, {"n": 234, "text": " * The plan generated in either of the above cases is returned."}, {"n": 235, "text": " */"}, {"n": 236, "text": "PlannedStmt *"}, {"n": 237, "text": "pgxc_planner(Query *query, int cursorOptions, ParamListInfo boundParams, "}, {"n": 238, "text": "\t\t\t\tint cached_param_num, bool explain)"}, {"n": 239, "text": "{"}, {"n": 240, "text": "\tPlannedStmt *result;"}, {"n": 241, "text": ""}, {"n": 242, "text": "\t/* see if can ship the query completely */"}, {"n": 243, "text": "\tresult = pgxc_FQS_planner(query, cursorOptions, boundParams, "}, {"n": 244, "text": "\t\t\t\t\t\t\t\tcached_param_num, explain);"}, {"n": 245, "text": "\tif (result)"}, {"n": 246, "text": "\t\treturn result;"}, {"n": 247, "text": ""}, {"n": 248, "text": "\t/* we need Coordinator for evaluation, invoke standard planner */"}, {"n": 249, "text": "\tresult = standard_planner(query, cursorOptions, boundParams);"}, {"n": 250, "text": "\treturn result;"}, {"n": 251, "text": "}"}, {"n": 252, "text": ""}, {"n": 253, "text": "/*"}, {"n": 254, "text": " * replace targetlist and processed_tlist expr with param"}, {"n": 255, "text": " */"}, {"n": 256, "text": "static void"}, {"n": 257, "text": "replace_tlist_disattr_expr(List *targetlist, List *processed_tlist, "}, {"n": 258, "text": "\t\t\t\t\t\t\tList *dist_attno, Expr **dis_exprs, "}, {"n": 385, "text": " * statement."}, {"n": 386, "text": " *"}, {"n": 387, "text": " * fqs in the name of function is acronym for fast query shipping."}, {"n": 388, "text": " */"}, {"n": 389, "text": "static PlannedStmt *"}, {"n": 390, "text": "pgxc_FQS_planner(Query *query, int cursorOptions, ParamListInfo boundParams, "}, {"n": 391, "text": "\t\t\t\t\tint cached_param_num, bool explain)"}, {"n": 392, "text": "{"}, {"n": 393, "text": "\tPlannedStmt\t\t*result;"}, {"n": 394, "text": "\tPlannedStmt     *std_plan = NULL;"}, {"n": 395, "text": "\tPlannerGlobal\t*glob;"}, {"n": 396, "text": "\tPlannerInfo\t\t*root;"}, {"n": 397, "text": "\tExecNodes\t\t*exec_nodes;"}, {"n": 398, "text": "\tPlan\t\t\t*top_plan;"}, {"n": 399, "text": "\tQuery\t\t\t*copy = NULL;"}, {"n": 400, "text": "\tList            *rte_list = NULL;"}, {"n": 401, "text": ""}, {"n": 402, "text": "\t/*"}, {"n": 403, "text": "\t * begin ora_compatible"}, {"n": 404, "text": "\t * Disable FQS for multi-insertion."}, {"n": 405, "text": "\t */"}, {"n": 406, "text": "\tif (query->multi_inserts != NULL)"}, {"n": 407, "text": "\t{"}, {"n": 408, "text": "\t\tListCell    *info_cell;"}, {"n": 409, "text": ""}, {"n": 410, "text": "\t\tforeach(info_cell, query->multi_inserts)"}, {"n": 411, "text": "\t\t{"}, {"n": 412, "text": "\t\t\tMultiInsertInto *info = (MultiInsertInto *) lfirst(info_cell);"}, {"n": 413, "text": "\t\t\tListCell    *sub_query_lc;"}, {"n": 414, "text": ""}, {"n": 415, "text": "\t\t\tforeach(sub_query_lc, info->sub_intos)"}, {"n": 416, "text": "\t\t\t{"}, {"n": 417, "text": "\t\t\t\tQuery *sub_query = (Query *) lfirst(sub_query_lc);"}, {"n": 418, "text": ""}, {"n": 419, "text": "\t\t\t\t/* call this walker to ensure triggers work */"}, {"n": 420, "text": "\t\t\t\tpgxc_is_query_shippable(sub_query, 0, boundParams, cached_param_num);"}, {"n": 421, "text": "\t\t\t\tif (sub_query->hasUnshippableDml)"}, {"n": 422, "text": "\t\t\t\t{"}, {"n": 423, "text": "\t\t\t\t\tListCell *again;"}, {"n": 424, "text": ""}, {"n": 425, "text": "\t\t\t\t\t/*"}, {"n": 426, "text": "\t\t\t\t\t * once we found a resultRelation with triggers, set all the"}, {"n": 427, "text": "\t\t\t\t\t * other relations force to execute trigger process:"}, {"n": 428, "text": "\t\t\t\t\t * 1. set flag"}, {"n": 429, "text": "\t\t\t\t\t * 2. create remote dml query inside it's own plan"}, {"n": 430, "text": "\t\t\t\t\t * 3. execute remote dml on CN"}, {"n": 431, "text": "\t\t\t\t\t */"}, {"n": 432, "text": "\t\t\t\t\tforeach(again, info->sub_intos)"}, {"n": 433, "text": "\t\t\t\t\t{"}, {"n": 434, "text": "\t\t\t\t\t\tsub_query = (Query *) lfirst(again);"}, {"n": 435, "text": "\t\t\t\t\t\tsub_query->hasUnshippableDml = true;"}, {"n": 436, "text": "\t\t\t\t\t}"}, {"n": 437, "text": "\t\t\t\t\t/*"}, {"n": 438, "text": "\t\t\t\t\t * also set parant query has triggers, make sure there is no"}, {"n": 439, "text": "\t\t\t\t\t * remote subplan on top of plan, then break"}, {"n": 440, "text": "\t\t\t\t\t */"}, {"n": 441, "text": "\t\t\t\t\tquery->hasUnshippableDml = true;"}, {"n": 442, "text": "\t\t\t\t\tbreak;"}, {"n": 443, "text": "\t\t\t\t}"}, {"n": 444, "text": "\t\t\t} /* break out of here */"}, {"n": 445, "text": "\t\t}"}, {"n": 446, "text": "\t\treturn NULL;"}, {"n": 447, "text": "\t}"}, {"n": 448, "text": "\t/* end ora_compatible */"}, {"n": 449, "text": ""}, {"n": 450, "text": "\t/*"}, {"n": 451, "text": "\t * If the query can not be or need not be shipped to the Datanodes, don't"}, {"n": 452, "text": "\t * create any plan here. standard_planner() will take care of it."}, {"n": 453, "text": "\t * XXX: Check this before guc enable_fast_query_shipping in case it is off"}, {"n": 454, "text": "\t *      and we want triggers work correctly. Check this after multi_inserts. "}, {"n": 455, "text": "\t */"}, {"n": 456, "text": "\texec_nodes = pgxc_is_query_shippable(query, 0, boundParams, cached_param_num);"}, {"n": 457, "text": "\tif (exec_nodes == NULL)"}, {"n": 458, "text": "\t\treturn NULL;"}, {"n": 459, "text": ""}, {"n": 460, "text": "\t/* Try by-passing standard planner, if fast query shipping is enabled */"}, {"n": 461, "text": "\tif (!enable_fast_query_shipping)"}, {"n": 462, "text": "\t\treturn NULL;"}, {"n": 463, "text": ""}, {"n": 464, "text": ""}, {"n": 465, "text": "\t/* Do not FQS cursor statements that require backward scrolling */"}, {"n": 466, "text": "\tif (cursorOptions & CURSOR_OPT_SCROLL)"}, {"n": 467, "text": "\t\treturn NULL;"}, {"n": 468, "text": ""}, {"n": 469, "text": "\t/* Do not FQS EXEC DIRECT statements */"}, {"n": 470, "text": "\tif (query->utilityStmt && IsA(query->utilityStmt, RemoteQuery))"}, {"n": 471, "text": "\t{"}, {"n": 472, "text": "\t\tRemoteQuery *stmt = (RemoteQuery *) query->utilityStmt;"}, {"n": 473, "text": "\t\tif (stmt->exec_direct_type != EXEC_DIRECT_NONE)"}, {"n": 474, "text": "\t\t\treturn NULL;"}, {"n": 475, "text": "\t}"}, {"n": 476, "text": ""}, {"n": 477, "text": "\t/* Avoid fast query shipping when DML statement contains function generate_series*/"}, {"n": 478, "text": "\tif (query->commandType != CMD_SELECT)"}, {"n": 479, "text": "\t{"}, {"n": 480, "text": "\t\tListCell *lc;"}, {"n": 481, "text": ""}, {"n": 482, "text": "\t\tforeach(lc, query->targetList)"}, {"n": 483, "text": "\t\t{"}, {"n": 484, "text": "\t\t\tTargetEntry* target_entry = (TargetEntry* ) lfirst(lc);"}, {"n": 485, "text": ""}, {"n": 486, "text": "\t\t\tif (IsA(target_entry->expr, FuncExpr))"}, {"n": 487, "text": "\t\t\t{"}, {"n": 488, "text": "\t\t\t\tOid func_id = ((FuncExpr *) target_entry->expr)->funcid;"}, {"n": 489, "text": ""}, {"n": 490, "text": "\t\t\t\tif (func_id == 1066 ||"}, {"n": 491, "text": "\t\t\t\t\tfunc_id == 1067 ||"}, {"n": 492, "text": "\t\t\t\t\tfunc_id == 1068 ||"}, {"n": 493, "text": "\t\t\t\t\tfunc_id == 1069 ||"}, {"n": 494, "text": "\t\t\t\t\tfunc_id == 3259 ||"}, {"n": 495, "text": "\t\t\t\t\tfunc_id == 3260 ||"}, {"n": 496, "text": "\t\t\t\t\tfunc_id == 938 ||"}, {"n": 497, "text": "\t\t\t\t\tfunc_id == 939)"}, {"n": 498, "text": "\t\t\t\t{"}, {"n": 499, "text": "\t\t\t\t\treturn NULL;"}, {"n": 500, "text": "\t\t\t\t}"}, {"n": 501, "text": "\t\t\t}"}, {"n": 502, "text": "\t\t}"}, {"n": 503, "text": "\t}"}, {"n": 504, "text": ""}, {"n": 505, "text": "\t/* Avoid unstable sublink execution. */"}, {"n": 506, "text": "\tif (check_multi_distkey_volatile(query))"}, {"n": 507, "text": "\t{"}, {"n": 508, "text": "\t\treturn NULL;"}, {"n": 509, "text": "\t}"}, {"n": 510, "text": ""}, {"n": 511, "text": "\tglob = makeNode(PlannerGlobal);"}, {"n": 512, "text": "\tglob->boundParams = boundParams;"}, {"n": 513, "text": "\t/* Create a PlannerInfo data structure, usually it is done for a subquery */"}, {"n": 514, "text": "\troot = makeNode(PlannerInfo);"}, {"n": 515, "text": "\t/* preprocess_targetlist may change query */"}, {"n": 516, "text": "\troot->parse = copyObject(query);"}, {"n": 517, "text": "\troot->glob = glob;"}, {"n": 518, "text": "\troot->query_level = 1;"}, {"n": 519, "text": "\troot->planner_cxt = CurrentMemoryContext;"}, {"n": 520, "text": "\tpreprocess_rowmarks(root);"}, {"n": 521, "text": "\tpreprocess_targetlist(root);"}, {"n": 522, "text": ""}, {"n": 523, "text": "\t/* make remote modify node for dist-update */"}, {"n": 524, "text": "\tif (root->distribution &&"}, {"n": 525, "text": "\t    (query->commandType == CMD_UPDATE ||"}, {"n": 526, "text": "\t     query->commandType == CMD_DELETE ||"}, {"n": 527, "text": "\t     query->commandType == CMD_INSERT) &&"}, {"n": 528, "text": "\t    (root->distribution->distributionType == LOCATOR_TYPE_SHARD ||"}, {"n": 529, "text": "\t     root->distribution->distributionType == LOCATOR_TYPE_HASH))"}, {"n": 530, "text": "\t{"}, {"n": 531, "text": "\t\t/*"}, {"n": 532, "text": "\t\t * Use the standard planner to generate a full remote DML plan."}, {"n": 533, "text": "\t\t * Notice it will change some part of query it self, so we use"}, {"n": 534, "text": "\t\t * a copy to make sure remote sql string correct."}, {"n": 535, "text": "\t\t */"}, {"n": 536, "text": "\t\tcopy = copyObject(query);"}, {"n": 537, "text": "\t\t\t\t"}, {"n": 538, "text": "\t\tstd_plan = standard_planner(copy, cursorOptions, boundParams);"}, {"n": 539, "text": "\t\t"}, {"n": 540, "text": "\t\tif (IsA(std_plan->planTree, RemoteModifyTable))"}, {"n": 541, "text": "\t\t{"}, {"n": 542, "text": "\t\t\tRemoteModifyTable *rmt = (RemoteModifyTable *) std_plan->planTree;"}, {"n": 543, "text": "\t\t\tModifyTable *mt = castNode(ModifyTable, std_plan->planTree->lefttree->lefttree);"}, {"n": 544, "text": "\t\t\t"}, {"n": 545, "text": "\t\t\tif (rmt->global_index)"}, {"n": 546, "text": "\t\t\t{"}, {"n": 547, "text": "\t\t\t\tListCell *lc;"}, {"n": 548, "text": "\t\t\t\t"}, {"n": 549, "text": "\t\t\t\tAssert(list_length(mt->returningLists) == 1);"}, {"n": 550, "text": "\t\t\t\tquery->returningList = copyObject(linitial(mt->returningLists));"}, {"n": 551, "text": "\t\t\t\t"}, {"n": 552, "text": "\t\t\t\tforeach(lc, query->returningList)"}, {"n": 553, "text": "\t\t\t\t{"}, {"n": 554, "text": "\t\t\t\t\tTargetEntry *tle = lfirst_node(TargetEntry, lc);"}, {"n": 555, "text": "\t\t\t\t\tif (tle->resname != NULL &&"}, {"n": 556, "text": "\t\t\t\t\t    (strcmp(tle->resname, \"ctid\") == 0 ||"}, {"n": 557, "text": "\t\t\t\t\t     strcmp(tle->resname, \"shardid\") == 0 ||"}, {"n": 558, "text": "\t\t\t\t\t     strcmp(tle->resname, \"tableoid\") == 0 ||"}, {"n": 559, "text": "\t\t\t\t\t     strcmp(tle->resname, \"xc_node_id\") == 0))"}, {"n": 560, "text": "\t\t\t\t\t{"}, {"n": 561, "text": "\t\t\t\t\t\ttle->resjunk = false;"}, {"n": 562, "text": "\t\t\t\t\t}"}, {"n": 563, "text": "\t\t\t\t}"}, {"n": 564, "text": "\t\t\t}"}, {"n": 565, "text": "\t\t\telse"}, {"n": 566, "text": "\t\t\t\tstd_plan = NULL;"}, {"n": 567, "text": "\t\t}"}, {"n": 568, "text": "\t\telse"}, {"n": 569, "text": "\t\t\tstd_plan = NULL;"}, {"n": 570, "text": "\t}"}, {"n": 571, "text": "\t"}, {"n": 572, "text": "\t/* Now we are ready for generating FQS sql, replace foo() with a Param */"}, {"n": 573, "text": "\tif (!explain && exec_nodes->en_param_expr)"}, {"n": 574, "text": "\t{"}, {"n": 575, "text": "\t\tAssert(query->commandType == CMD_INSERT);"}, {"n": 576, "text": "\t\treplace_tlist_disattr_expr(query->targetList, root->processed_tlist, "}, {"n": 577, "text": "\t\t\t\t\t\t\t\t\texec_nodes->dist_attno, "}, {"n": 578, "text": "\t\t\t\t\t\t\t\t\texec_nodes->dis_exprs,"}, {"n": 579, "text": "\t\t\t\t\t\t\t\t\texec_nodes->en_param_expr);"}, {"n": 580, "text": "\t}"}, {"n": 581, "text": "\t"}, {"n": 582, "text": "\t/*"}, {"n": 583, "text": "\t * We decided to ship the query to the Datanode/s, create a RemoteQuery node"}, {"n": 584, "text": "\t * for the same."}, {"n": 585, "text": "\t */"}, {"n": 586, "text": "\ttop_plan = (Plan *)pgxc_FQS_create_remote_plan(query, exec_nodes, false, FQS_MODE_FQS_PLANER);"}, {"n": 587, "text": "\ttop_plan->targetlist = root->processed_tlist;"}, {"n": 588, "text": ""}, {"n": 589, "text": "\t/* Now we have a proper top_plan, use the transformed query for instead if any */"}, {"n": 590, "text": "\tif (copy != NULL)"}, {"n": 591, "text": "\t{"}, {"n": 592, "text": "\t\t/* reset the returning list, it may be set to mt->returningLists above */"}, {"n": 593, "text": "\t\tquery->returningList = copy->returningList;"}, {"n": 594, "text": "\t\tquery = copy;"}, {"n": 595, "text": "\t}"}, {"n": 596, "text": "\tif (query->returningList)"}, {"n": 597, "text": "\t\ttop_plan->targetlist = query->returningList;"}, {"n": 598, "text": ""}, {"n": 599, "text": ""}, {"n": 600, "text": "\tif (std_plan != NULL)"}, {"n": 601, "text": "\t{"}, {"n": 602, "text": "\t\tRemoteQuery *rq = (RemoteQuery *) top_plan;"}, {"n": 603, "text": "\t\tRemoteModifyTable *rmt = (RemoteModifyTable *) std_plan->planTree;"}, {"n": 604, "text": "\t\t"}, {"n": 605, "text": "\t\t/*"}, {"n": 606, "text": "\t\t * The top_plan now should be like:"}, {"n": 607, "text": "\t\t * Remote Query"}, {"n": 608, "text": "\t\t *      -> Update or Insert or Delete"}, {"n": 609, "text": "\t\t *              -> Some scan or Join"}, {"n": 610, "text": "\t\t */"}, {"n": 611, "text": "\t\trq->remote_mt ="}, {"n": 612, "text": "\t\t\tcastNode(ModifyTable, std_plan->planTree->lefttree->lefttree);"}, {"n": 613, "text": "\t\tif (rmt->global_index)"}, {"n": 614, "text": "\t\t{"}, {"n": 615, "text": "\t\t\ttop_plan->targetlist = copyObject(linitial(rq->remote_mt->returningLists));"}, {"n": 616, "text": "\t\t}"}, {"n": 617, "text": "\t\tstd_plan->planTree->lefttree = top_plan;"}, {"n": 618, "text": "\t\ttop_plan = std_plan->planTree;"}, {"n": 619, "text": "\t}"}, {"n": 620, "text": ""}, {"n": 621, "text": "\t/*"}, {"n": 622, "text": "\t * Just before creating the PlannedStmt, do some final cleanup"}, {"n": 623, "text": "\t * We need to save plan dependencies, so that dropping objects will"}, {"n": 624, "text": "\t * invalidate the cached plan if it depends on those objects. Table"}, {"n": 625, "text": "\t * dependencies are available in glob->relationOids and all other"}, {"n": 626, "text": "\t * dependencies are in glob->invalItems. These fields can be retrieved"}, {"n": 627, "text": "\t * through set_plan_references()."}, {"n": 628, "text": "\t */"}, {"n": 629, "text": "\ttop_plan = set_plan_references(root, top_plan);"}, {"n": 630, "text": ""}, {"n": 631, "text": "\t/* build the PlannedStmt result */"}, {"n": 632, "text": "\tresult = makeNode(PlannedStmt);"}, {"n": 633, "text": "\t/* Try and set what we can, rest must have been zeroed out by makeNode() */"}, {"n": 634, "text": "\tresult->commandType = query->commandType;"}, {"n": 635, "text": "\tresult->canSetTag = query->canSetTag;"}, {"n": 636, "text": "\tresult->utilityStmt = query->utilityStmt;"}, {"n": 637, "text": ""}, {"n": 638, "text": "\t/* Set result relations */"}, {"n": 639, "text": "\tif (std_plan != NULL)"}, {"n": 640, "text": "\t\tresult->resultRelations = list_copy(std_plan->resultRelations);"}, {"n": 641, "text": "\telse if (query->commandType != CMD_SELECT)"}, {"n": 642, "text": "\t\tresult->resultRelations = list_make1_int(query->resultRelation);"}, {"n": 643, "text": ""}, {"n": 644, "text": "\tresult->planTree = top_plan;"}, {"n": 645, "text": "\tresult->rtable = query->rtable;"}, {"n": 646, "text": "\tresult->queryId = query->queryId;"}, {"n": 647, "text": "\tresult->relationOids = glob->relationOids;"}, {"n": 648, "text": "\tresult->invalItems = glob->invalItems;"}, {"n": 649, "text": "\tresult->rowMarks = glob->finalrowmarks;"}, {"n": 650, "text": "\tresult->hasReturning = (query->returningList != NULL);"}, {"n": 651, "text": "\tresult->guc_str = NULL;"}, {"n": 652, "text": ""}, {"n": 653, "text": "\tflatten_unplanned_query(&rte_list, query);"}, {"n": 654, "text": "\tresult->fqs_rte_list = rte_list;"}, {"n": 655, "text": ""}, {"n": 656, "text": "\tSetSPMUnsupported();"}, {"n": 657, "text": "\treturn result;"}, {"n": 658, "text": "}"}, {"n": 659, "text": ""}, {"n": 660, "text": "RemoteQuery *"}, {"n": 661, "text": "pgxc_FQS_create_remote_plan(Query *query, ExecNodes *exec_nodes, bool is_exec_direct, FQS_MODE mode)"}, {"n": 662, "text": "{"}, {"n": 663, "text": "\tRemoteQuery *query_step;"}, {"n": 664, "text": "\tStringInfoData buf;"}, {"n": 665, "text": "\tRangeTblEntry\t*dummy_rte;"}, {"n": 666, "text": "\tint i = 0;"}, {"n": 667, "text": ""}, {"n": 668, "text": "\t/* EXECUTE DIRECT statements have their RemoteQuery node already built when analyzing */"}, {"n": 669, "text": "\tif (is_exec_direct)"}, {"n": 670, "text": "\t{"}, {"n": 671, "text": "\t\tAssert(IsA(query->utilityStmt, RemoteQuery));"}, {"n": 672, "text": "\t\tquery_step = (RemoteQuery *)query->utilityStmt;"}, {"n": 673, "text": "\t\tquery->utilityStmt = NULL;"}, {"n": 674, "text": "\t}"}, {"n": 675, "text": "\telse"}, {"n": 676, "text": "\t{"}, {"n": 677, "text": "\t\tquery_step = makeNode(RemoteQuery);"}, {"n": 678, "text": "\t\tquery_step->combine_type = COMBINE_TYPE_NONE;"}, {"n": 679, "text": "\t\tquery_step->exec_type = EXEC_ON_DATANODES;"}, {"n": 680, "text": "\t\tquery_step->exec_direct_type = EXEC_DIRECT_NONE;"}, {"n": 681, "text": "\t\tquery_step->exec_nodes = exec_nodes;"}, {"n": 682, "text": "\t}"}, {"n": 683, "text": ""}, {"n": 684, "text": "\tAssert(query_step->exec_nodes);"}, {"n": 685, "text": ""}, {"n": 686, "text": "\t/* Deparse query tree to get step query. */"}, {"n": 687, "text": "\tif (query_step->sql_statement == NULL)"}, {"n": 688, "text": "\t{"}, {"n": 689, "text": "\t\tinitStringInfo(&buf);"}, {"n": 690, "text": "\t\t/*"}, {"n": 691, "text": "\t\t * We always finalise aggregates on datanodes for FQS."}, {"n": 692, "text": "\t\t * Use the expressions for ORDER BY or GROUP BY clauses."}, {"n": 693, "text": "\t\t */"}, {"n": 694, "text": "\t\tdeparse_query(query, &buf, NIL, true, false);"}, {"n": 695, "text": "\t\tquery_step->sql_statement = pstrdup(buf.data);"}, {"n": 696, "text": "\t\tpfree(buf.data);"}, {"n": 697, "text": "\t}"}, {"n": 698, "text": ""}, {"n": 699, "text": "\t/* Optimize multi-node handling */"}, {"n": 700, "text": "\tif (query->commandType == CMD_SELECT && !query->hasForUpdate)"}, {"n": 701, "text": "\t{"}, {"n": 702, "text": "\t\tquery_step->read_only = true;"}, {"n": 703, "text": "\t\t/* connection for RELATION_ACCESS_READ_FQS will be marked read_only */"}, {"n": 704, "text": "\t\tquery_step->exec_nodes->accesstype = RELATION_ACCESS_READ_FQS;"}, {"n": 705, "text": "\t}"}, {"n": 706, "text": "\tquery_step->has_row_marks = query->hasForUpdate;"}, {"n": 707, "text": ""}, {"n": 708, "text": "\t/* Check if temporary tables are in use in query */"}, {"n": 709, "text": "\t/* PGXC_FQS_TODO: scanning the rtable again for the queries should not be"}, {"n": 710, "text": "\t * needed. We should be able to find out if the query has a temporary object"}, {"n": 711, "text": "\t * while finding nodes for the objects. But there is no way we can convey"}, {"n": 712, "text": "\t * that information here. Till such a connection is available, this is it."}, {"n": 713, "text": "\t */"}, {"n": 714, "text": "\tif (contains_temp_tables(query->rtable))"}, {"n": 715, "text": "\t\tquery_step->is_temp = true;"}, {"n": 716, "text": ""}, {"n": 717, "text": "\t/*"}, {"n": 718, "text": "\t * We need to evaluate some expressions like the ExecNodes->en_expr at"}, {"n": 719, "text": "\t * Coordinator, prepare those for evaluation. Ideally we should call"}, {"n": 720, "text": "\t * preprocess_expression, but it needs PlannerInfo structure for the same"}, {"n": 721, "text": "\t */"}, {"n": 722, "text": "\tfor (i = 0; i < query_step->exec_nodes->nExprs; ++i)"}, {"n": 723, "text": "\t{"}, {"n": 724, "text": "\t\tfix_opfuncids((Node *)(query_step->exec_nodes->dis_exprs[i]));"}, {"n": 725, "text": "\t}"}, {"n": 726, "text": "\t/*"}, {"n": 727, "text": "\t * PGXCTODO"}, {"n": 728, "text": "\t * When Postgres runs insert into t (a) values (1); against table"}, {"n": 729, "text": "\t * defined as create table t (a int, b int); the plan is looking"}, {"n": 730, "text": "\t * like insert into t (a,b) values (1,null);"}, {"n": 731, "text": "\t * Later executor is verifying plan, to make sure table has not"}, {"n": 732, "text": "\t * been altered since plan has been created and comparing table"}, {"n": 733, "text": "\t * definition with plan target list and output error if they do"}, {"n": 734, "text": "\t * not match."}, {"n": 735, "text": "\t * I could not find better way to generate targetList for pgxc plan"}, {"n": 736, "text": "\t * then call standard planner and take targetList from the plan"}, {"n": 737, "text": "\t * generated by Postgres."}, {"n": 738, "text": "\t */"}, {"n": 739, "text": "\tquery_step->combine_type = get_plan_combine_type("}, {"n": 740, "text": "\t\t\t\tquery->commandType, query_step->exec_nodes->baselocatortype);"}, {"n": 741, "text": ""}, {"n": 742, "text": "\t/*"}, {"n": 743, "text": "\t * Create a dummy RTE for the remote query being created. Append the dummy"}, {"n": 744, "text": "\t * range table entry to the range table. Note that this modifies the master"}, {"n": 745, "text": "\t * copy the caller passed us, otherwise e.g EXPLAIN VERBOSE will fail to"}, {"n": 746, "text": "\t * find the rte the Vars built below refer to. Also create the tuple"}, {"n": 747, "text": "\t * descriptor for the result of this query from the base_tlist (targetlist"}, {"n": 748, "text": "\t * we used to generate the remote node query)."}, {"n": 749, "text": "\t */"}, {"n": 750, "text": "\tdummy_rte = makeNode(RangeTblEntry);"}, {"n": 751, "text": "\tdummy_rte->rtekind = RTE_REMOTE_DUMMY;"}, {"n": 752, "text": "\t/* Use a dummy relname... */"}, {"n": 753, "text": "\tif (is_exec_direct)"}, {"n": 754, "text": "\t\tdummy_rte->relname = \"__EXECUTE_DIRECT__\";"}, {"n": 755, "text": "\telse"}, {"n": 756, "text": "\t\tdummy_rte->relname\t   = \"__REMOTE_FQS_QUERY__\";"}, {"n": 757, "text": "\tdummy_rte->eref\t\t   = makeAlias(\"__REMOTE_FQS_QUERY__\", NIL);"}, {"n": 758, "text": "\t/* Rest will be zeroed out in makeNode() */"}, {"n": 759, "text": ""}, {"n": 760, "text": "\tquery->rtable = lappend(query->rtable, dummy_rte);"}, {"n": 761, "text": "\tquery_step->scan.scanrelid \t= list_length(query->rtable);"}, {"n": 762, "text": "\tquery_step->scan.plan.targetlist = query->targetList;"}, {"n": 763, "text": "\tquery_step->base_tlist = query->targetList;"}, {"n": 764, "text": "    query_step->fqs_mode = mode;"}, {"n": 765, "text": "    "}, {"n": 766, "text": "\treturn query_step;"}, {"n": 767, "text": "}"}, {"n": 768, "text": "#ifdef __OPENTENBASE__"}, {"n": 769, "text": "RangeTblEntry *"}]}, "ship": {"path": "src/backend/optimizer/util/pgxcship.c", "sha256": "3564015017984d60188296f2720776f249cfe4902e84f0f39f56566f8867c769", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/backend/optimizer/util/pgxcship.c", "lines": [{"n": 2427, "text": " * executed on Datanodes directly without involving Coordinator."}, {"n": 2428, "text": " * If the query is shippable this routine also returns the nodes where the query"}, {"n": 2429, "text": " * should be shipped. If the query is not shippable, it returns NULL."}, {"n": 2430, "text": " */"}, {"n": 2431, "text": "ExecNodes *"}, {"n": 2432, "text": "pgxc_is_query_shippable(Query *query, int query_level, "}, {"n": 2433, "text": "\t\t\t\t\t\tParamListInfo boundParams, int cached_param_num)"}, {"n": 2434, "text": "{"}, {"n": 2435, "text": "\tShippability_context sc_context;"}, {"n": 2436, "text": "\tExecNodes\t*exec_nodes;"}, {"n": 2437, "text": "\tbool\t\tcanShip = true;"}, {"n": 2438, "text": "\tBitmapset\t*shippability;"}, {"n": 2439, "text": ""}, {"n": 2440, "text": "\tmemset(&sc_context, 0, sizeof(sc_context));"}, {"n": 2441, "text": "\t/* let's assume that by default query is shippable */"}, {"n": 2442, "text": "\tsc_context.sc_query = query;"}, {"n": 2443, "text": "\tsc_context.sc_query_level = query_level;"}, {"n": 2444, "text": "\tsc_context.sc_for_expr = false;"}, {"n": 2445, "text": "\tsc_context.boundParams = boundParams;"}, {"n": 2446, "text": "\tsc_context.cached_param_num = cached_param_num;"}, {"n": 2447, "text": ""}, {"n": 2448, "text": "\t/* multi insert can not ship */"}, {"n": 2449, "text": "\tif (ORA_MODE && query->commandType == CMD_INSERT && query->multi_inserts != NULL)"}, {"n": 2450, "text": "\t{"}, {"n": 2451, "text": "\t\tListCell    *info_cell;"}, {"n": 2452, "text": "\t\tExecNodes *mr_ens = NULL;"}, {"n": 2453, "text": ""}, {"n": 2454, "text": "\t\tquery->canShip = true;"}, {"n": 2455, "text": "\t\tforeach(info_cell, query->multi_inserts)"}, {"n": 2456, "text": "\t\t{"}, {"n": 2457, "text": "\t\t\tMultiInsertInto *info = (MultiInsertInto *) lfirst(info_cell);"}, {"n": 2458, "text": "\t\t\tListCell    *sub_query_lc;"}, {"n": 2459, "text": "\t\t\tforeach(sub_query_lc, info->sub_intos)"}, {"n": 2460, "text": "\t\t\t{"}, {"n": 2461, "text": "\t\t\t\tQuery *sub_query = (Query *) lfirst(sub_query_lc);"}, {"n": 2462, "text": ""}, {"n": 2463, "text": "\t\t\t\t/* call this walker to ensure triggers work */"}, {"n": 2464, "text": "\t\t\t\tExecNodes *ens = pgxc_is_query_shippable(sub_query, 0, boundParams, cached_param_num);"}, {"n": 2465, "text": "\t\t\t\tif (!sub_query->canShip)"}, {"n": 2466, "text": "\t\t\t\t\tquery->canShip = false;"}, {"n": 2467, "text": ""}, {"n": 2468, "text": "\t\t\t\tif (sub_query->hasUnshippableDml)"}, {"n": 2469, "text": "\t\t\t\t{"}, {"n": 2470, "text": "\t\t\t\t\tListCell *again;"}, {"n": 2471, "text": ""}, {"n": 2472, "text": "\t\t\t\t\t/*"}, {"n": 2473, "text": "\t\t\t\t\t * once we found a resultRelation with triggers, set all the"}, {"n": 2474, "text": "\t\t\t\t\t * other relations force to execute trigger process:"}, {"n": 2475, "text": "\t\t\t\t\t * 1. set flag"}, {"n": 2476, "text": "\t\t\t\t\t * 2. create remote dml query inside it's own plan"}, {"n": 2477, "text": "\t\t\t\t\t * 3. execute remote dml on CN"}, {"n": 2478, "text": "\t\t\t\t\t */"}, {"n": 2479, "text": "\t\t\t\t\tforeach(again, info->sub_intos)"}, {"n": 2480, "text": "\t\t\t\t\t{"}, {"n": 2481, "text": "\t\t\t\t\t\tsub_query = (Query *) lfirst(again);"}, {"n": 2482, "text": "\t\t\t\t\t\tsub_query->hasUnshippableDml = true;"}, {"n": 2483, "text": "\t\t\t\t\t}"}, {"n": 2484, "text": "\t\t\t\t\t/*"}, {"n": 2485, "text": "\t\t\t\t\t * also set parant query has triggers, make sure there is no"}, {"n": 2486, "text": "\t\t\t\t\t * remote subplan on top of plan, then break"}, {"n": 2487, "text": "\t\t\t\t\t */"}, {"n": 2488, "text": "\t\t\t\t\tquery->hasUnshippableDml = true;"}, {"n": 2489, "text": "\t\t\t\t}"}, {"n": 2490, "text": ""}, {"n": 2491, "text": "\t\t\t\t/* only when all the sub insert can ship to the same single node, the whole multi insert can ship  */"}, {"n": 2492, "text": "\t\t\t\tif (ens == NULL || list_length(ens->nodeList) != 1)"}, {"n": 2493, "text": "\t\t\t\t{"}, {"n": 2494, "text": "\t\t\t\t\tmr_ens = NULL;"}, {"n": 2495, "text": "\t\t\t\t\tquery->canShip = false;"}, {"n": 2496, "text": "\t\t\t\t}"}, {"n": 2497, "text": ""}, {"n": 2498, "text": "\t\t\t\tmr_ens = mr_ens == NULL ? ens : pgxc_merge_exec_nodes(mr_ens, ens);"}, {"n": 2499, "text": "\t\t\t\tif (mr_ens == NULL || list_length(mr_ens->nodeList) != 1)"}, {"n": 2500, "text": "\t\t\t\t{"}, {"n": 2501, "text": "\t\t\t\t\tmr_ens = NULL;"}, {"n": 2502, "text": "\t\t\t\t\tquery->canShip = false;"}, {"n": 2503, "text": "\t\t\t\t}"}, {"n": 2504, "text": "\t\t\t}"}, {"n": 2505, "text": "\t\t}"}, {"n": 2506, "text": ""}, {"n": 2507, "text": "\t\t/* anyway, disable fqs for multi insert here */"}, {"n": 2508, "text": "\t\tmr_ens = NULL;"}, {"n": 2509, "text": "\t\tquery->canShip = false;"}, {"n": 2510, "text": "\t\treturn mr_ens;"}, {"n": 2511, "text": "\t}"}, {"n": 2512, "text": ""}, {"n": 2513, "text": "\t/*"}, {"n": 2514, "text": "\t * We might have already decided not to ship the query to the Datanodes, but"}, {"n": 2515, "text": "\t * still walk it anyway to find out if there are any subqueries which can be"}, {"n": 2516, "text": "\t * shipped."}, {"n": 2517, "text": "\t */"}, {"n": 2518, "text": "\tquery->canShip = true;"}, {"n": 2519, "text": "\tpgxc_shippability_walker((Node *)query, &sc_context);"}, {"n": 2520, "text": ""}, {"n": 2521, "text": "\texec_nodes = sc_context.sc_exec_nodes;"}, {"n": 2522, "text": ""}, {"n": 2523, "text": "\t/*"}, {"n": 2524, "text": "\t * For single datanode and select command, if we don't need coord"}, {"n": 2525, "text": "\t * and exec_nodes exists, return it directly. But if exec_nodes is"}, {"n": 2526, "text": "\t * NULL we make exec_nodes for FQS; SetOperations are excluded"}, {"n": 2527, "text": "\t * because dn planner may append targetlists which coordinator do not know."}, {"n": 2528, "text": "\t */"}, {"n": 2529, "text": "\tif (!bms_is_member(SS_NEEDS_COORD, sc_context.sc_shippability) &&"}, {"n": 2530, "text": "\t\tquery->commandType == CMD_SELECT && query->setOperations == NULL)"}, {"n": 2531, "text": "\t{"}, {"n": 2532, "text": "\t\tint\tdn_nodes_num = NumDataNodes;"}, {"n": 2533, "text": "#ifdef __SUPPORT_CENTRALIZED_MODE__"}, {"n": 2534, "text": "\t\t/*"}, {"n": 2535, "text": "\t\t * We get dn master number by involved PGXCGetAllMasterDnOid"}, {"n": 2536, "text": "\t\t * instead of NumDataNodes, because in centralized mode,"}, {"n": 2537, "text": "\t\t * NumDataNodes include dn master and dn slave."}, {"n": 2538, "text": "\t\t */"}, {"n": 2539, "text": "\t\tif (cluster_mode == CENTRALIZED_MODE)"}, {"n": 2540, "text": "\t\t{"}, {"n": 2541, "text": "\t\t\tOid\t*dn_node_list = (Oid *) palloc0(dn_nodes_num * sizeof(Oid));"}, {"n": 2542, "text": "\t\t\tdn_nodes_num = PGXCGetAllMasterDnOid(dn_node_list);"}, {"n": 2543, "text": "\t\t\tAssert(dn_nodes_num > 0);"}, {"n": 2544, "text": "\t\t\tpfree(dn_node_list);"}, {"n": 2545, "text": "\t\t}"}, {"n": 2546, "text": "#endif"}, {"n": 2547, "text": "\t\tif (dn_nodes_num == 1)"}, {"n": 2548, "text": "\t\t{"}, {"n": 2549, "text": "\t\t\tif (exec_nodes)"}, {"n": 2550, "text": "\t\t\t\treturn exec_nodes;"}, {"n": 2551, "text": "\t\t\treturn make_FQS_single_node();"}, {"n": 2552, "text": "\t\t}"}, {"n": 2553, "text": "\t}"}, {"n": 2554, "text": ""}, {"n": 2555, "text": "\t/*"}, {"n": 2556, "text": "\t * The shippability context contains two ExecNodes, one for the subLinks"}, {"n": 2557, "text": "\t * involved in the Query and other for the relation involved in FromClause."}, {"n": 2558, "text": "\t * They are computed at different times while scanning the query. Merge both"}, {"n": 2559, "text": "\t * of them if they are both replicated. If query doesn't have SubLinks, we"}, {"n": 2560, "text": "\t * don't need to consider corresponding ExecNodes."}, {"n": 2561, "text": "\t * PGXC_FQS_TODO:"}, {"n": 2562, "text": "\t * Merge the subquery ExecNodes if both of them are replicated."}, {"n": 2563, "text": "\t * The logic to merge node lists with other distribution"}, {"n": 2564, "text": "\t * strategy is not clear yet."}, {"n": 2565, "text": "\t */"}, {"n": 2566, "text": "\tif (query->hasSubLinks)"}, {"n": 2567, "text": "\t{"}, {"n": 2568, "text": "        exec_nodes = merge_sublink_exec_nodes(query, &sc_context, exec_nodes);"}, {"n": 2569, "text": "    }"}, {"n": 2570, "text": ""}, {"n": 2571, "text": "\t/*"}, {"n": 2572, "text": "\t * Copy the shippability reasons. We modify the copy for easier handling."}, {"n": 2573, "text": "\t * The original can be saved away"}, {"n": 2574, "text": "\t */"}, {"n": 2575, "text": "\tshippability = bms_copy(sc_context.sc_shippability);"}, {"n": 2576, "text": ""}, {"n": 2577, "text": "\tif (bms_is_member(SS_UNSHIPPABLE_EXPR, shippability))"}, {"n": 2578, "text": "\t\tquery->canShip = false;"}, {"n": 2579, "text": ""}, {"n": 2580, "text": "\t/* If we found the datanodes to ship, use them */"}, {"n": 2581, "text": "\tif (exec_nodes && exec_nodes->nodeList)"}, {"n": 2582, "text": "\t{"}, {"n": 2583, "text": "\t\t/*"}, {"n": 2584, "text": "\t\t * If relations involved in the query are such that ultimate JOIN is"}, {"n": 2585, "text": "\t\t * replicated JOIN, choose only one of them. If one of them is a"}, {"n": 2586, "text": "\t\t * preferred node choose that one, otherwise choose the first one."}, {"n": 2587, "text": "\t\t */"}, {"n": 2588, "text": "\t\tif ((IsLocatorReplicated(exec_nodes->baselocatortype) || LOCATOR_TYPE_FOREIGN == exec_nodes->baselocatortype) &&"}, {"n": 2589, "text": "\t\t    (exec_nodes->accesstype == RELATION_ACCESS_READ ||"}, {"n": 2590, "text": "\t\t     exec_nodes->accesstype == RELATION_ACCESS_READ_FQS ||"}, {"n": 2591, "text": "\t\t     exec_nodes->accesstype == RELATION_ACCESS_READ_FOR_UPDATE))"}, {"n": 2592, "text": "\t\t{"}, {"n": 2593, "text": "\t\t\t/*"}, {"n": 2594, "text": "\t\t\t * Replication table execute \"SELECT FOR UPDATE\", it is necessary to"}, {"n": 2595, "text": "\t\t\t * send the command to all DNs to lock the rows."}, {"n": 2596, "text": "\t\t\t */"}, {"n": 2597, "text": "\t\t\tif (query_level == 0 && exec_nodes->accesstype != RELATION_ACCESS_READ_FOR_UPDATE)"}, {"n": 2598, "text": "\t\t\t{"}, {"n": 2599, "text": "\t\t\t\tList *tmp_list = exec_nodes->nodeList;"}, {"n": 2600, "text": "\t\t\t\texec_nodes->nodeList = GetPreferredReplicationNode(exec_nodes->nodeList);"}, {"n": 2601, "text": "\t\t\t\tlist_free(tmp_list);"}, {"n": 2602, "text": "\t\t\t}"}, {"n": 2603, "text": ""}, {"n": 2604, "text": "\t\t\tshippability = bms_del_member(shippability, SS_REPLICATED_ONLY);"}, {"n": 2605, "text": "\t\t}"}, {"n": 2606, "text": "\t}"}, {"n": 2607, "text": ""}, {"n": 2608, "text": "\tif (query_level != 0 && pgxc_FQS_check_subquery_const(query))"}, {"n": 2609, "text": "\t{"}, {"n": 2610, "text": "\t\tint i;"}, {"n": 2611, "text": ""}, {"n": 2612, "text": "\t\texec_nodes = makeNode(ExecNodes);"}, {"n": 2613, "text": "\t\texec_nodes->baselocatortype = LOCATOR_TYPE_REPLICATED;"}, {"n": 2614, "text": "\t\t/*"}, {"n": 2615, "text": "\t\t * No locate info stored for such subquery RTEs, we use this"}, {"n": 2616, "text": "\t\t * flag to force using the other hand locate info."}, {"n": 2617, "text": "\t\t */"}, {"n": 2618, "text": "\t\texec_nodes->const_subquery = true;"}, {"n": 2619, "text": "\t\tfor (i = 0; i < NumDataNodes; ++i)"}, {"n": 2620, "text": "\t\t\texec_nodes->nodeList = lappend_int(exec_nodes->nodeList, i);"}, {"n": 2621, "text": "\t\treturn exec_nodes;"}, {"n": 2622, "text": "\t}"}, {"n": 2623, "text": ""}, {"n": 2624, "text": "\t/*"}, {"n": 2625, "text": "\t * Look at the information gathered by the walker in Shippability_context and that"}, {"n": 2626, "text": "\t * in the Query structure to decide whether we should ship this query"}, {"n": 2627, "text": "\t * directly to the Datanode or not"}, {"n": 2628, "text": "\t */"}, {"n": 2629, "text": ""}, {"n": 2630, "text": "\t/* SS_NEED_PROCESS_IN_CN: functions should be called in CN. */"}, {"n": 2631, "text": "\tif (ORA_MODE && (query->commandType == CMD_UPDATE ||"}, {"n": 2632, "text": "\t\tquery->commandType == CMD_INSERT ||"}, {"n": 2633, "text": "\t\tquery->commandType == CMD_DELETE) &&"}, {"n": 2634, "text": "\t\tbms_is_member(SS_NEED_PROCESS_IN_CN, shippability))"}, {"n": 2635, "text": "\t\tquery->hasUnshippableDml = true;"}, {"n": 2636, "text": ""}, {"n": 2637, "text": "\t/*"}, {"n": 2638, "text": "\t * If the planner was not able to find the Datanodes to the execute the"}, {"n": 2639, "text": "\t * query, the query is not completely shippable. So, return NULL"}, {"n": 2640, "text": "\t */"}, {"n": 2641, "text": "\tif (!exec_nodes)"}, {"n": 2642, "text": "\t\treturn NULL;"}, {"n": 2643, "text": "\t/*"}, {"n": 2644, "text": "\t * If the query has an expression which renders the shippability to single"}, {"n": 2645, "text": "\t * node, and query needs to be shipped to more than one node, it can not be"}, {"n": 2646, "text": "\t * shipped"}, {"n": 2647, "text": "\t */"}, {"n": 2648, "text": "\tif (bms_is_member(SS_NEED_SINGLENODE, shippability))"}, {"n": 2649, "text": "\t{"}, {"n": 2650, "text": "\t\t/*"}, {"n": 2651, "text": "\t\t * if nodeList has no nodes, it ExecNodes will have other means to know"}, {"n": 2652, "text": "\t\t * the nodes where to execute like distribution column expression. We"}, {"n": 2653, "text": "\t\t * can't tell how many nodes the query will be executed on, hence treat"}, {"n": 2654, "text": "\t\t * that as multiple nodes."}, {"n": 2655, "text": "\t\t * Additionally, replication can be pushed down."}, {"n": 2656, "text": "\t\t */"}, {"n": 2657, "text": "\t\tif (exec_nodes->baselocatortype == LOCATOR_TYPE_REPLICATED)"}, {"n": 2658, "text": "\t\t\tcanShip = true;"}, {"n": 2659, "text": "\t\telse if (list_length(exec_nodes->nodeList) > 1)"}, {"n": 2660, "text": "\t\t\tcanShip = false;"}, {"n": 2661, "text": "\t\telse if (list_length(exec_nodes->nodeList) == 1)"}, {"n": 2662, "text": "\t\t\tcanShip = true;"}, {"n": 2663, "text": "\t\telse if (!((exec_nodes->baselocatortype == LOCATOR_TYPE_HASH ||"}, {"n": 2664, "text": "\t\t            exec_nodes->baselocatortype == LOCATOR_TYPE_SHARD ||"}, {"n": 2665, "text": "\t\t            exec_nodes->baselocatortype == LOCATOR_TYPE_DISTRIBUTED) &&"}, {"n": 2666, "text": "\t\t           (has_all_dis_exprs(exec_nodes) ||"}, {"n": 2667, "text": "\t\t            list_length(exec_nodes->nodeList) == 1)))"}, {"n": 2668, "text": "\t\t\tcanShip = false;"}, {"n": 2669, "text": ""}, {"n": 2670, "text": "\t\t/* We handled the reason here, reset it */"}, {"n": 2671, "text": "\t\tshippability = bms_del_member(shippability, SS_NEED_SINGLENODE);"}, {"n": 2672, "text": "\t}"}, {"n": 2673, "text": ""}, {"n": 2674, "text": "\tif (query_level != 0 && exec_nodes->accesstype == RELATION_ACCESS_READ_FOR_UPDATE)"}, {"n": 2675, "text": "\t\tcanShip = false;"}, {"n": 2676, "text": ""}, {"n": 2677, "text": "\t/*"}, {"n": 2678, "text": "\t * If HAS_AGG_EXPR is set but NEED_SINGLENODE is not set, it means the"}, {"n": 2679, "text": "\t * aggregates are entirely shippable, so don't worry about it."}, {"n": 2680, "text": "\t */"}, {"n": 2681, "text": "\tshippability = bms_del_member(shippability, SS_HAS_AGG_EXPR);"}, {"n": 2682, "text": ""}, {"n": 2683, "text": "\t/*"}, {"n": 2684, "text": "\t * If an insert sql command whose distribute key's value is a"}, {"n": 2685, "text": "\t * function, we allow it to be shipped to datanode. But we must"}, {"n": 2686, "text": "\t * must know the function's result before real execute. So set"}, {"n": 2687, "text": "\t * the flag to identify rewrite in ExecutePlan."}, {"n": 2688, "text": "\t */"}, {"n": 2689, "text": "\tif (bms_is_member(SS_NEED_FUNC_CONVERT_TO_PARAM, shippability) &&"}, {"n": 2690, "text": "\t\t(IsLocatorColumnDistributed(exec_nodes->baselocatortype) ||"}, {"n": 2691, "text": "\t\tIsLocatorDistributedByValue(exec_nodes->baselocatortype)))"}, {"n": 2692, "text": "\t{"}, {"n": 2693, "text": "\t\tshippability = bms_del_member(shippability, SS_NEED_FUNC_CONVERT_TO_PARAM);"}, {"n": 2694, "text": "\t}"}, {"n": 2695, "text": ""}, {"n": 2696, "text": "\t/* Can not ship the query for some reason */"}, {"n": 2697, "text": "\tif (!bms_is_empty(shippability))"}, {"n": 2698, "text": "\t\tcanShip = false;"}, {"n": 2699, "text": ""}, {"n": 2700, "text": "\t/* Always keep this at the end before checking canShip and return */"}, {"n": 2701, "text": "\tif (!canShip && exec_nodes)"}, {"n": 2702, "text": "\t\tFreeExecNodes(&exec_nodes);"}, {"n": 2703, "text": "\t/* If query is to be shipped, we should know where to execute the query */"}, {"n": 2704, "text": "\tAssert (!canShip || exec_nodes);"}, {"n": 2705, "text": ""}, {"n": 2706, "text": "\tbms_free(shippability);"}, {"n": 2707, "text": "\tshippability = NULL;"}, {"n": 2708, "text": ""}, {"n": 2709, "text": "\treturn exec_nodes;"}, {"n": 2710, "text": "}"}, {"n": 2711, "text": ""}, {"n": 2712, "text": "static ExecNodes*"}]}, "remote": {"path": "src/backend/pgxc/pool/execRemote.c", "sha256": "0676a4aeebc7600af9abc7ef1420aec68aa52ab15bf4bd5cb105d9e6a1055d9c", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/backend/pgxc/pool/execRemote.c", "lines": [{"n": 746, "text": " * Handle DataRow ('D') message from a Datanode connection"}, {"n": 747, "text": " * The function returns true if data row is accepted and successfully stored"}, {"n": 748, "text": " * within the combiner."}, {"n": 749, "text": " */"}, {"n": 750, "text": "static bool"}, {"n": 751, "text": "HandleDataRow(ResponseCombiner *combiner, char *msg_body, size_t len, Oid node, bool data_from_remote_tid_scan)"}, {"n": 752, "text": "{"}, {"n": 753, "text": "\t/* We expect previous message is consumed */"}, {"n": 754, "text": "\tAssert(combiner->currentRow == NULL);"}, {"n": 755, "text": ""}, {"n": 756, "text": "\tif (combiner->ignore_datarow)"}, {"n": 757, "text": "\t\treturn false;"}, {"n": 758, "text": ""}, {"n": 759, "text": "\tif (combiner->request_type == REQUEST_TYPE_ERROR)"}, {"n": 760, "text": "\t\treturn false;"}, {"n": 761, "text": ""}, {"n": 762, "text": "\tif (combiner->request_type != REQUEST_TYPE_QUERY)"}, {"n": 763, "text": "\t{"}, {"n": 764, "text": "\t\t/* Inconsistent responses */"}, {"n": 765, "text": "\t\tchar data_buf[4096];"}, {"n": 766, "text": ""}, {"n": 767, "text": "\t\tsnprintf(data_buf, len, \"%s\", msg_body);"}, {"n": 768, "text": "\t\tif (len > 4095)"}, {"n": 769, "text": "\t\t\tlen = 4095;"}, {"n": 770, "text": "\t\tdata_buf[len] = 0;"}, {"n": 771, "text": "\t\tereport(ERROR,"}, {"n": 772, "text": "\t\t\t\t(errcode(ERRCODE_DATA_CORRUPTED),"}, {"n": 773, "text": "\t\t\t\t errmsg(\"Unexpected response from the data nodes for 'D' message, \""}, {"n": 774, "text": "\t\t\t\t\t\t\"current request type %d, data %s\","}, {"n": 775, "text": "\t\t\t\t \t\tcombiner->request_type, data_buf)));"}, {"n": 776, "text": "\t}"}, {"n": 777, "text": ""}, {"n": 778, "text": "\t/*"}, {"n": 779, "text": "\t * If we got an error already ignore incoming data rows from other nodes"}, {"n": 780, "text": "\t * Still we want to continue reading until get CommandComplete"}, {"n": 781, "text": "\t */"}, {"n": 782, "text": "\tif (combiner->errorMessage)"}, {"n": 783, "text": "\t\treturn false;"}, {"n": 784, "text": ""}, {"n": 785, "text": "\t/*"}, {"n": 786, "text": "\t * Replicated INSERT/UPDATE/DELETE with RETURNING: receive only tuples"}, {"n": 787, "text": "\t * from one node, skip others as duplicates"}, {"n": 788, "text": "\t */"}, {"n": 789, "text": "\tif (combiner->combine_type == COMBINE_TYPE_SAME)"}, {"n": 790, "text": "\t{"}, {"n": 791, "text": "\t\t/* Do not return rows when probing primary, instead return when doing"}, {"n": 792, "text": "\t\t * first normal node. Just save some CPU and traffic in case if"}, {"n": 793, "text": "\t\t * probing fails."}, {"n": 794, "text": "\t\t */"}, {"n": 795, "text": "\t\tif (combiner->probing_primary)"}, {"n": 796, "text": "\t\t\treturn false;"}, {"n": 797, "text": "\t\tif (OidIsValid(combiner->returning_node))"}, {"n": 798, "text": "\t\t{"}, {"n": 799, "text": "\t\t\tif (combiner->returning_node != node)"}, {"n": 800, "text": "\t\t\t\treturn false;"}, {"n": 801, "text": "\t\t}"}, {"n": 802, "text": "\t\telse"}, {"n": 803, "text": "\t\t\tcombiner->returning_node = node;"}, {"n": 804, "text": "\t}"}, {"n": 805, "text": ""}, {"n": 806, "text": "\t/*"}, {"n": 807, "text": "\t * We are copying message because it points into connection buffer, and"}, {"n": 808, "text": "\t * will be overwritten on next socket read"}, {"n": 809, "text": "\t */"}, {"n": 810, "text": "\tcombiner->currentRow = (RemoteDataRow) palloc(sizeof(RemoteDataRowData) + len);"}, {"n": 811, "text": "\tmemcpy(combiner->currentRow->msg, msg_body, len);"}, {"n": 812, "text": "\tcombiner->currentRow->msglen = len;"}, {"n": 813, "text": "\tcombiner->currentRow->msgnode = node;"}, {"n": 814, "text": "\tcombiner->currentRow->data_from_remote_tid_scan = data_from_remote_tid_scan;"}, {"n": 815, "text": ""}, {"n": 816, "text": "\treturn true;"}, {"n": 817, "text": "}"}, {"n": 818, "text": ""}, {"n": 819, "text": "/*"}, {"n": 1951, "text": "/*"}, {"n": 1952, "text": " * copy the datarow from combiner to the given slot, in the slot's memory"}, {"n": 1953, "text": " * context"}, {"n": 1954, "text": " */"}, {"n": 1955, "text": "void"}, {"n": 1956, "text": "CopyDataRowTupleToSlot(ResponseCombiner *combiner, TupleTableSlot *slot)"}, {"n": 1957, "text": "{"}, {"n": 1958, "text": "\tRemoteDataRow \tdatarow;"}, {"n": 1959, "text": "\tMemoryContext\toldcontext;"}, {"n": 1960, "text": "\toldcontext = MemoryContextSwitchTo(slot->tts_mcxt);"}, {"n": 1961, "text": "\tdatarow = (RemoteDataRow) palloc(sizeof(RemoteDataRowData) + combiner->currentRow->msglen);"}, {"n": 1962, "text": "\tdatarow->msgnode = combiner->currentRow->msgnode;"}, {"n": 1963, "text": "\tdatarow->msglen = combiner->currentRow->msglen;"}, {"n": 1964, "text": "\tdatarow->data_from_remote_tid_scan = combiner->currentRow->data_from_remote_tid_scan;"}, {"n": 1965, "text": "\tmemcpy(datarow->msg, combiner->currentRow->msg, datarow->msglen);"}, {"n": 1966, "text": "\tExecStoreDataRowTuple(datarow, slot, true);"}, {"n": 1967, "text": "\tpfree(combiner->currentRow);"}, {"n": 1968, "text": "\tcombiner->currentRow = NULL;"}, {"n": 1969, "text": "\tMemoryContextSwitchTo(oldcontext);"}, {"n": 1970, "text": "}"}, {"n": 1971, "text": ""}, {"n": 1972, "text": ""}, {"n": 1985, "text": " * \t\tFunction may wait while more data arrive from the data nodes. If there"}, {"n": 1986, "text": " * is a locally executed subplan function advance it and buffer resulting rows"}, {"n": 1987, "text": " * instead of waiting."}, {"n": 1988, "text": " */"}, {"n": 1989, "text": "TupleTableSlot *"}, {"n": 1990, "text": "FetchTuple(ResponseCombiner *combiner)"}, {"n": 1991, "text": "{"}, {"n": 1992, "text": "\tPGXCNodeHandle *conn;"}, {"n": 1993, "text": "\tTupleTableSlot *slot;"}, {"n": 1994, "text": "\tRemoteFragmentController *ctl = combiner->ss.ps.state->es_remote_controller;"}, {"n": 1995, "text": "\tOid \t\t\tnodeOid = -1;"}, {"n": 1996, "text": ""}, {"n": 1997, "text": "\t/*"}, {"n": 1998, "text": "\t * Get current connection"}, {"n": 1999, "text": "\t */"}, {"n": 2000, "text": "\tif (combiner->conn_count > combiner->current_conn)"}, {"n": 2001, "text": "\t\tconn = combiner->connections[combiner->current_conn];"}, {"n": 2002, "text": "\telse"}, {"n": 2003, "text": "\t\tconn = NULL;"}, {"n": 2004, "text": ""}, {"n": 2005, "text": "\t/*"}, {"n": 2006, "text": "\t * If doing merge sort determine the node number."}, {"n": 2007, "text": "\t * It may be needed to get buffered row."}, {"n": 2008, "text": "\t */"}, {"n": 2009, "text": "\tif (combiner->merge_sort)"}, {"n": 2010, "text": "\t{"}, {"n": 2011, "text": "\t\tAssert(conn || combiner->tapenodes);"}, {"n": 2012, "text": "\t\tnodeOid = conn ? conn->nodeoid :"}, {"n": 2013, "text": "\t\t\t\t\t\t combiner->tapenodes[combiner->current_conn];"}, {"n": 2014, "text": "\t\tAssert(OidIsValid(nodeOid));"}, {"n": 2015, "text": "\t}"}, {"n": 2016, "text": ""}, {"n": 2017, "text": "READ_ROWBUFFER:"}, {"n": 2018, "text": "\t/*"}, {"n": 2019, "text": "\t * First look into the row buffer."}, {"n": 2020, "text": "\t * When we are performing merge sort we need to get from the buffer record"}, {"n": 2021, "text": "\t * from the connection marked as \"current\". Otherwise get first."}, {"n": 2022, "text": "\t */"}, {"n": 2023, "text": "\tif (list_length(combiner->rowBuffer) > 0)"}, {"n": 2024, "text": "\t{"}, {"n": 2025, "text": "\t\tRemoteDataRow dataRow;"}, {"n": 2026, "text": ""}, {"n": 2027, "text": "\t\tAssert(combiner->currentRow == NULL);"}, {"n": 2028, "text": ""}, {"n": 2029, "text": "\t\tif (combiner->merge_sort)"}, {"n": 2030, "text": "\t\t{"}, {"n": 2031, "text": "\t\t\tListCell *lc;"}, {"n": 2032, "text": "\t\t\tListCell *prev;"}, {"n": 2033, "text": ""}, {"n": 2034, "text": "\t\t\telog(DEBUG1, \"Getting buffered tuple from node %x\", nodeOid);"}, {"n": 2035, "text": ""}, {"n": 2036, "text": "\t\t\tprev = combiner->tapemarks[combiner->current_conn];"}, {"n": 2037, "text": "\t\t\tif (prev)"}, {"n": 2038, "text": "\t\t\t{"}, {"n": 2039, "text": "\t\t\t\t/*"}, {"n": 2040, "text": "\t\t\t\t * Start looking through the list from the bookmark."}, {"n": 2041, "text": "\t\t\t\t * Probably the first cell we check contains row from the needed"}, {"n": 2042, "text": "\t\t\t\t * node. Otherwise continue scanning until we encounter one,"}, {"n": 2043, "text": "\t\t\t\t * advancing prev pointer as well."}, {"n": 2044, "text": "\t\t\t\t */"}, {"n": 2045, "text": "\t\t\t\twhile ((lc = lnext(prev)) != NULL)"}, {"n": 2046, "text": "\t\t\t\t{"}, {"n": 2047, "text": "\t\t\t\t\tdataRow = (RemoteDataRow) lfirst(lc);"}, {"n": 2048, "text": "\t\t\t\t\tif (dataRow->msgnode == nodeOid)"}, {"n": 2049, "text": "\t\t\t\t\t{"}, {"n": 2050, "text": "\t\t\t\t\t\tcombiner->currentRow = dataRow;"}, {"n": 2051, "text": "\t\t\t\t\t\tbreak;"}, {"n": 2052, "text": "\t\t\t\t\t}"}, {"n": 2053, "text": "\t\t\t\t\tprev = lc;"}, {"n": 2054, "text": "\t\t\t\t}"}, {"n": 2055, "text": "\t\t\t}"}, {"n": 2056, "text": "\t\t\telse"}, {"n": 2057, "text": "\t\t\t{"}, {"n": 2058, "text": "\t\t\t\t/*"}, {"n": 2059, "text": "\t\t\t\t * Either needed row is the first in the buffer or no such row"}, {"n": 2060, "text": "\t\t\t\t */"}, {"n": 2061, "text": "\t\t\t\tlc = list_head(combiner->rowBuffer);"}, {"n": 2062, "text": "\t\t\t\tdataRow = (RemoteDataRow) lfirst(lc);"}, {"n": 2063, "text": "\t\t\t\tif (dataRow->msgnode == nodeOid)"}, {"n": 2064, "text": "\t\t\t\t\tcombiner->currentRow = dataRow;"}, {"n": 2065, "text": "\t\t\t\telse"}, {"n": 2066, "text": "\t\t\t\t\tlc = NULL;"}, {"n": 2067, "text": "\t\t\t}"}, {"n": 2068, "text": ""}, {"n": 2069, "text": "\t\t\tif (lc)"}, {"n": 2070, "text": "\t\t\t{"}, {"n": 2071, "text": "\t\t\t\t/*"}, {"n": 2072, "text": "\t\t\t\t * Delete cell from the buffer. Before we delete we must check"}, {"n": 2073, "text": "\t\t\t\t * the bookmarks, if the cell is a bookmark for any tape."}, {"n": 2074, "text": "\t\t\t\t * If it is the case we are deleting last row of the current"}, {"n": 2075, "text": "\t\t\t\t * block from the current tape. That tape should have bookmark"}, {"n": 2076, "text": "\t\t\t\t * like current, and current bookmark will be advanced when we"}, {"n": 2077, "text": "\t\t\t\t * read the tape once again."}, {"n": 2078, "text": "\t\t\t\t */"}, {"n": 2079, "text": "\t\t\t\tint i;"}, {"n": 2080, "text": "\t\t\t\tfor (i = 0; i < combiner->conn_count; i++)"}, {"n": 2081, "text": "\t\t\t\t{"}, {"n": 2082, "text": "\t\t\t\t\tif (combiner->tapemarks[i] == lc)"}, {"n": 2083, "text": "\t\t\t\t\t\tcombiner->tapemarks[i] = prev;"}, {"n": 2084, "text": "\t\t\t\t}"}, {"n": 2085, "text": "\t\t\t\telog(DEBUG1, \"Found buffered tuple from node %x\", nodeOid);"}, {"n": 2086, "text": "\t\t\t\tcombiner->rowBuffer = list_delete_cell(combiner->rowBuffer,"}, {"n": 2087, "text": "\t\t\t\t\t\t\t\t\t\t\t\t\t   lc, prev);"}, {"n": 2088, "text": "\t\t\t}"}, {"n": 2089, "text": "\t\t\telog(DEBUG1, \"Update tapemark\");"}, {"n": 2090, "text": "\t\t\tcombiner->tapemarks[combiner->current_conn] = prev;"}, {"n": 2091, "text": "\t\t}"}, {"n": 2092, "text": "\t\telse"}, {"n": 2093, "text": "\t\t{"}, {"n": 2094, "text": "\t\t\tdataRow = (RemoteDataRow) linitial(combiner->rowBuffer);"}, {"n": 2095, "text": "\t\t\tcombiner->currentRow = dataRow;"}, {"n": 2096, "text": "\t\t\tcombiner->rowBuffer = list_delete_first(combiner->rowBuffer);"}, {"n": 2097, "text": "\t\t}"}, {"n": 2098, "text": "\t}"}, {"n": 2099, "text": ""}, {"n": 2100, "text": "#ifdef __OPENTENBASE__"}, {"n": 2101, "text": "\t/* fetch datarow from prerowbuffers */"}, {"n": 2102, "text": "\tif (!combiner->currentRow)"}, {"n": 2103, "text": "\t{"}, {"n": 2104, "text": "\t\tif (combiner->merge_sort)"}, {"n": 2105, "text": "\t\t{"}, {"n": 2106, "text": "\t\t\tRemoteDataRow dataRow;"}, {"n": 2107, "text": "\t\t\tint node_index = combiner->current_conn;"}, {"n": 2108, "text": ""}, {"n": 2109, "text": "\t\t\tif (combiner->prerowBuffers &&"}, {"n": 2110, "text": "\t\t\t\tlist_length(combiner->prerowBuffers[node_index]) > 0)"}, {"n": 2111, "text": "\t\t\t{"}, {"n": 2112, "text": "\t\t\t\tdataRow = (RemoteDataRow) linitial(combiner->prerowBuffers[node_index]);"}, {"n": 2113, "text": "\t\t\t\tcombiner->currentRow = dataRow;"}, {"n": 2114, "text": "\t\t\t\tcombiner->prerowBuffers[node_index] = list_delete_first(combiner->prerowBuffers[node_index]);"}, {"n": 2115, "text": "\t\t\t}"}, {"n": 2116, "text": "\t\t}"}, {"n": 2117, "text": "\t}"}, {"n": 2118, "text": ""}, {"n": 2119, "text": "\tif (!combiner->currentRow)"}, {"n": 2120, "text": "\t{"}, {"n": 2121, "text": "\t\t/* fetch data in tuplestore */"}, {"n": 2122, "text": "\t\tif (combiner->merge_sort)"}, {"n": 2123, "text": "\t\t{"}, {"n": 2124, "text": "\t\t\tint node_index = combiner->current_conn;"}, {"n": 2125, "text": ""}, {"n": 2126, "text": "\t\t\tif (combiner->dataRowBuffer && combiner->dataRowBuffer[node_index])"}, {"n": 2127, "text": "\t\t\t{"}, {"n": 2128, "text": "\t\t\t\tif (tuplestore_gettupleslot(combiner->dataRowBuffer[node_index],"}, {"n": 2129, "text": "\t\t\t\t\t\t\t\t\t\t   true, true, combiner->tmpslot))"}, {"n": 2130, "text": "\t\t\t\t{"}, {"n": 2131, "text": "\t\t\t\t\tcombiner->tmpslot->tts_shouldFreeRow = false;"}, {"n": 2132, "text": "\t\t\t\t\tcombiner->currentRow = combiner->tmpslot->tts_datarow;"}, {"n": 2133, "text": "\t\t\t\t\tcombiner->nDataRows[node_index]--;"}, {"n": 2134, "text": "\t\t\t\t}"}, {"n": 2135, "text": "\t\t\t\telse"}, {"n": 2136, "text": "\t\t\t\t{"}, {"n": 2137, "text": "\t\t\t\t\t/* sanity check */"}, {"n": 2138, "text": "\t\t\t\t\tif (combiner->nDataRows[node_index] != 0)"}, {"n": 2139, "text": "\t\t\t\t\t{"}, {"n": 2140, "text": "\t\t\t\t\t\telog(ERROR, \"connection %d has %d datarows left in tuplestore.\","}, {"n": 2141, "text": "\t\t\t\t\t\t\t\t\t node_index, combiner->nDataRows[node_index]);"}, {"n": 2142, "text": "\t\t\t\t\t}"}, {"n": 2143, "text": ""}, {"n": 2144, "text": "\t\t\t\t\t/*"}, {"n": 2145, "text": "\t\t\t\t\t  * datarows fetched from tuplestore in memory will be freed by caller,"}, {"n": 2146, "text": "\t\t\t\t\t  * we do not need to free them in tuplestore_end, tuplestore_set_tupdeleted"}, {"n": 2147, "text": "\t\t\t\t\t  * avoid to free memtuples in tuplestore_end."}, {"n": 2148, "text": "\t\t\t\t\t  */"}, {"n": 2149, "text": "\t\t\t\t\ttuplestore_end(combiner->dataRowBuffer[node_index]);"}, {"n": 2150, "text": "\t\t\t\t\tcombiner->dataRowBuffer[node_index] = NULL;"}, {"n": 2151, "text": "\t\t\t\t\tcombiner->dataRowMemSize[node_index] = 0;"}, {"n": 2152, "text": "\t\t\t\t}"}, {"n": 2153, "text": "\t\t\t}"}, {"n": 2154, "text": "\t\t}"}, {"n": 2155, "text": "\t\telse"}, {"n": 2156, "text": "\t\t{"}, {"n": 2157, "text": "\t\t\tif (combiner->dataRowBuffer && combiner->dataRowBuffer[0])"}, {"n": 2158, "text": "\t\t\t{"}, {"n": 2159, "text": "\t\t\t\tif (tuplestore_gettupleslot(combiner->dataRowBuffer[0],"}, {"n": 2160, "text": "\t\t\t\t\t\t\t\t\t\t   true, true, combiner->tmpslot))"}, {"n": 2161, "text": "\t\t\t\t{"}, {"n": 2162, "text": "\t\t\t\t\tcombiner->tmpslot->tts_shouldFreeRow = false;"}, {"n": 2163, "text": "\t\t\t\t\tcombiner->currentRow = combiner->tmpslot->tts_datarow;"}, {"n": 2164, "text": "\t\t\t\t\tcombiner->nDataRows[0]--;"}, {"n": 2165, "text": "\t\t\t\t}"}, {"n": 2166, "text": "\t\t\t\telse"}, {"n": 2167, "text": "\t\t\t\t{"}, {"n": 2168, "text": "\t\t\t\t\t/* sanity check */"}, {"n": 2169, "text": "\t\t\t\t\tif (combiner->nDataRows[0] != 0)"}, {"n": 2170, "text": "\t\t\t\t\t{"}, {"n": 2171, "text": "\t\t\t\t\t\telog(ERROR, \"%d datarows left in tuplestore.\", combiner->nDataRows[0]);"}, {"n": 2172, "text": "\t\t\t\t\t}"}, {"n": 2173, "text": ""}, {"n": 2174, "text": "\t\t\t\t\t/*"}, {"n": 2175, "text": "\t\t\t\t\t  * datarows fetched from tuplestore in memory will be freed by caller,"}, {"n": 2176, "text": "\t\t\t\t\t  * we do not need to free them in tuplestore_end, tuplestore_set_tupdeleted"}, {"n": 2177, "text": "\t\t\t\t\t  * avoid to free memtuples in tuplestore_end."}, {"n": 2178, "text": "\t\t\t\t\t  */"}, {"n": 2179, "text": "\t\t\t\t\ttuplestore_end(combiner->dataRowBuffer[0]);"}, {"n": 2180, "text": "\t\t\t\t\tcombiner->dataRowBuffer[0] = NULL;"}, {"n": 2181, "text": "\t\t\t\t\tcombiner->dataRowMemSize[0] = 0;"}, {"n": 2182, "text": "\t\t\t\t}"}, {"n": 2183, "text": "\t\t\t}"}, {"n": 2184, "text": "\t\t}"}, {"n": 2185, "text": "\t}"}, {"n": 2186, "text": "#endif"}, {"n": 2187, "text": ""}, {"n": 2188, "text": "\t/* If we have node message in the currentRow slot, and it is from a proper"}, {"n": 2189, "text": "\t * node, consume it.  */"}, {"n": 2190, "text": "\tif (combiner->currentRow)"}, {"n": 2191, "text": "\t{"}, {"n": 2192, "text": "\t\tAssert(!combiner->merge_sort ||"}, {"n": 2193, "text": "\t\t\t   combiner->currentRow->msgnode == nodeOid);"}, {"n": 2194, "text": "\t\tslot = combiner->ss.ps.ps_ResultTupleSlot;"}, {"n": 2195, "text": "\t\tCopyDataRowTupleToSlot(combiner, slot);"}, {"n": 2196, "text": ""}, {"n": 2197, "text": "\t\treturn slot;"}, {"n": 2198, "text": "\t}"}, {"n": 2199, "text": ""}, {"n": 2200, "text": "\twhile (conn)"}, {"n": 2201, "text": "\t{"}, {"n": 2202, "text": "\t\tint res;"}, {"n": 2203, "text": ""}, {"n": 2204, "text": "\t\t/* Going to use a connection, buffer it if needed */"}, {"n": 2205, "text": "\t\tDrainConnectionAndSetNewCombiner(conn, combiner);"}, {"n": 2206, "text": ""}, {"n": 2207, "text": "\t\t/*"}, {"n": 2208, "text": "\t\t * If current connection is idle it means portal on the data node is"}, {"n": 2209, "text": "\t\t * suspended. Request more and try to get it"}, {"n": 2210, "text": "\t\t */"}, {"n": 2211, "text": "\t\tif (combiner->extended_query &&"}, {"n": 2212, "text": "\t\t\t\tIsConnectionStateIdle(conn))"}, {"n": 2213, "text": "\t\t{"}, {"n": 2214, "text": "\t\t\t/*"}, {"n": 2215, "text": "\t\t\t * We do not allow to suspend if querying primary node, so that"}, {"n": 2216, "text": "\t\t\t * only may mean the current node is secondary and subplan was not"}, {"n": 2217, "text": "\t\t\t * executed there yet. Return and go on with second phase."}, {"n": 2218, "text": "\t\t\t */"}, {"n": 2219, "text": "\t\t\tif (combiner->probing_primary)"}, {"n": 2220, "text": "\t\t\t{"}, {"n": 2221, "text": "\t\t\t\treturn NULL;"}, {"n": 2222, "text": "\t\t\t}"}, {"n": 2223, "text": ""}, {"n": 2224, "text": "\t\t\tif (pgxc_node_send_execute(conn, combiner->cursor, PGXLRemoteFetchSize, false) != 0)"}, {"n": 2225, "text": "\t\t\t{"}, {"n": 2226, "text": "\t\t\t\tereport(ERROR,"}, {"n": 2227, "text": "\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2228, "text": "\t\t\t\t\t\t errmsg(\"Failed to send execute cursor '%s' to node %u\","}, {"n": 2229, "text": "\t\t\t\t\t\t\t\tcombiner->cursor, conn->nodeoid)));"}, {"n": 2230, "text": "\t\t\t}"}, {"n": 2231, "text": ""}, {"n": 2232, "text": "\t\t\tif (SendFlushRequest(conn) != 0)"}, {"n": 2233, "text": "\t\t\t{"}, {"n": 2234, "text": "\t\t\t\tereport(ERROR,"}, {"n": 2235, "text": "\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2236, "text": "\t\t\t\t\t\t errmsg(\"Failed flush cursor '%s' node %u\","}, {"n": 2237, "text": "\t\t\t\t\t\t\t\tcombiner->cursor, conn->nodeoid)));"}, {"n": 2238, "text": "\t\t\t}"}, {"n": 2239, "text": ""}, {"n": 2240, "text": "\t\t\tif (pgxc_node_receive(1, &conn, NULL))"}, {"n": 2241, "text": "\t\t\t{"}, {"n": 2242, "text": "\t\t\t\tereport(ERROR,"}, {"n": 2243, "text": "\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2244, "text": "\t\t\t\t\t\t errmsg(\"Failed receive data from node %u cursor '%s'\","}, {"n": 2245, "text": "\t\t\t\t\t\t\t\tconn->nodeoid, combiner->cursor)));"}, {"n": 2246, "text": "\t\t\t}"}, {"n": 2247, "text": "\t\t}"}, {"n": 2248, "text": ""}, {"n": 2249, "text": "\t\t/* read messages */"}, {"n": 2250, "text": "\t\tres = handle_response(conn, combiner);"}, {"n": 2251, "text": "\t\tif (res == RESPONSE_DATAROW)"}, {"n": 2252, "text": "\t\t{"}, {"n": 2253, "text": "\t\t\tslot = combiner->ss.ps.ps_ResultTupleSlot;"}, {"n": 2254, "text": "\t\t\tCopyDataRowTupleToSlot(combiner, slot);"}, {"n": 2255, "text": "\t\t\tcombiner->current_conn_rows_consumed++;"}, {"n": 2256, "text": ""}, {"n": 2257, "text": "\t\t\t/*"}, {"n": 2258, "text": "\t\t\t * If we are running simple query protocol, yield the connection"}, {"n": 2259, "text": "\t\t\t * after we process PGXLRemoteFetchSize rows from the connection."}, {"n": 2260, "text": "\t\t\t * This should allow us to consume rows quickly from other"}, {"n": 2261, "text": "\t\t\t * connections, while this node gets chance to generate more rows"}, {"n": 2262, "text": "\t\t\t * which would then be processed in the next iteration."}, {"n": 2263, "text": "\t\t\t */"}, {"n": 2264, "text": "\t\t\tif (!combiner->extended_query &&"}, {"n": 2265, "text": "\t\t\t\tcombiner->current_conn_rows_consumed >= PGXLRemoteFetchSize)"}, {"n": 2266, "text": "\t\t\t{"}, {"n": 2267, "text": "\t\t\t\tif (++combiner->current_conn >= combiner->conn_count)"}, {"n": 2268, "text": "\t\t\t\t{"}, {"n": 2269, "text": "\t\t\t\t\tcombiner->current_conn = 0;"}, {"n": 2270, "text": "\t\t\t\t}"}, {"n": 2271, "text": "\t\t\t\tcombiner->current_conn_rows_consumed = 0;"}, {"n": 2272, "text": "\t\t\t}"}, {"n": 2273, "text": ""}, {"n": 2274, "text": "\t\t\treturn slot;"}, {"n": 2275, "text": "\t\t}"}, {"n": 2276, "text": "\t\telse if (res == RESPONSE_EOF)"}, {"n": 2277, "text": "\t\t{"}, {"n": 2278, "text": "\t\t\t/*"}, {"n": 2279, "text": "\t\t\t * We encountered incomplete message."}, {"n": 2280, "text": "\t\t\t * There are two strategies;"}, {"n": 2281, "text": "\t\t\t * 1. postpone the current node and receive from other nodes."}, {"n": 2282, "text": "\t\t\t * 2. wait for current node to response."}, {"n": 2283, "text": "\t\t\t *"}, {"n": 2284, "text": "\t\t\t * In most circumstances, the first one is faster because it decreases the waiting time."}, {"n": 2285, "text": "\t\t\t * but when we encounter merge sort or other circumstance, it must wait for all nodes"}, {"n": 2286, "text": "\t\t\t * to calculate the merging result. if we use strategy one, we have to store all then data"}, {"n": 2287, "text": "\t\t\t * in memory which results in poor performance."}, {"n": 2288, "text": "\t\t\t *"}, {"n": 2289, "text": "\t\t\t * TODO: remove switch and choose strategy according to work."}, {"n": 2290, "text": "\t\t\t */"}, {"n": 2291, "text": "\t\t\tif (postpone_slow_node)"}, {"n": 2292, "text": "\t\t\t{"}, {"n": 2293, "text": "\t\t\t\t/*"}, {"n": 2294, "text": "\t\t\t\t * We encountered incomplete message, try to read more."}, {"n": 2295, "text": "\t\t\t\t * Here if we read timeout, then we move to other connections to read, because we"}, {"n": 2296, "text": "\t\t\t\t * easily got deadlock if a specific cursor run as producer on two nodes. If we can"}, {"n": 2297, "text": "\t\t\t\t * consume data from all all connections, we can break the deadlock loop."}, {"n": 2298, "text": "\t\t\t\t */"}, {"n": 2299, "text": "\t\t\t\tbool   bComplete          = false;"}, {"n": 2300, "text": "\t\t\t\tDNConnectionState state   = DN_CONNECTION_STATE_IDLE;"}, {"n": 2301, "text": "\t\t\t\tint    i                  = 0;"}, {"n": 2302, "text": "\t\t\t\tint    ret \t\t\t      = 0;"}, {"n": 2303, "text": "\t\t\t\tPGXCNodeHandle *save_conn = NULL;"}, {"n": 2304, "text": "\t\t\t\tstruct timeval timeout;"}, {"n": 2305, "text": "\t\t\t\ttimeout.tv_sec  \t      = 0;"}, {"n": 2306, "text": "\t\t\t\ttimeout.tv_usec \t      = 1000;"}, {"n": 2307, "text": ""}, {"n": 2308, "text": "\t\t\t\tsave_conn = conn;"}, {"n": 2309, "text": "\t\t\t\twhile (1)"}, {"n": 2310, "text": "\t\t\t\t{"}, {"n": 2311, "text": "\t\t\t\t\tconn  = save_conn;"}, {"n": 2312, "text": "\t\t\t\t\tstate = GetConnectionState(conn); /* Save the connection state. */"}, {"n": 2313, "text": ""}, {"n": 2314, "text": "\t\t\t\t\tif (ctl && !HAS_MESSAGE_BUFFERED(conn) && IsConnectionStateQuery(conn))"}, {"n": 2315, "text": "\t\t\t\t\t{"}, {"n": 2316, "text": "\t\t\t\t\t\t/* no timeout */"}, {"n": 2317, "text": "\t\t\t\t\t\tif (RunRemoteControllerWithFD(conn->sock, ctl, 1) == RemoteControllerEventFN)"}, {"n": 2318, "text": "\t\t\t\t\t\t\ttimeout.tv_usec = 0;"}, {"n": 2319, "text": "\t\t\t\t\t}"}, {"n": 2320, "text": ""}, {"n": 2321, "text": "\t\t\t\t\tret   = pgxc_node_receive(1, &conn, &timeout);"}, {"n": 2322, "text": "\t\t\t\t\tif (DNStatus_OK == ret)"}, {"n": 2323, "text": "\t\t\t\t\t{"}, {"n": 2324, "text": "\t\t\t\t\t\t/* We got data, handle it. */"}, {"n": 2325, "text": "\t\t\t\t\t\tbreak;"}, {"n": 2326, "text": "\t\t\t\t\t}"}, {"n": 2327, "text": "\t\t\t\t\telse if (DNStatus_ERR == ret)"}, {"n": 2328, "text": "\t\t\t\t\t{"}, {"n": 2329, "text": "\t\t\t\t\t\tereport(ERROR,"}, {"n": 2330, "text": "\t\t\t\t\t\t\t\t(errcode(ERRCODE_EXEC_REMOTE_ERROR),"}, {"n": 2331, "text": "\t\t\t\t\t\t\t\t errmsg(\"Failed to receive more data from \""}, {"n": 2332, "text": "\t\t\t\t\t\t\t\t\t\t\"data node %s pid %d\","}, {"n": 2333, "text": "\t\t\t\t\t\t\t\t\t\tconn->nodename, conn->backend_pid)));"}, {"n": 2334, "text": "\t\t\t\t\t}"}, {"n": 2335, "text": "\t\t\t\t\telse"}, {"n": 2336, "text": "\t\t\t\t\t{"}, {"n": 2337, "text": "\t\t\t\t\t\t/* Restore the saved state of connection. */"}, {"n": 2338, "text": "\t\t\t\t\t\tUpdateConnectionState(conn, state);"}, {"n": 2339, "text": "\t\t\t\t\t}"}, {"n": 2340, "text": ""}, {"n": 2341, "text": "\t\t\t\t\t/* Try to read data from other connections. */"}, {"n": 2342, "text": "\t\t\t\t\tfor (i = 0; i < combiner->conn_count; i ++)"}, {"n": 2343, "text": "\t\t\t\t\t{"}, {"n": 2344, "text": "\t\t\t\t\t\tconn  = combiner->connections[i];"}, {"n": 2345, "text": "\t\t\t\t\t\tif (save_conn != conn && conn != NULL)"}, {"n": 2346, "text": "\t\t\t\t\t\t{"}, {"n": 2347, "text": "\t\t\t\t\t\t\t/* Save the connection state. */"}, {"n": 2348, "text": "\t\t\t\t\t\t\tstate = GetConnectionState(conn);"}, {"n": 2349, "text": "\t\t\t\t\t\t\tif (IsConnectionStateQuery(conn))"}, {"n": 2350, "text": "\t\t\t\t\t\t\t{"}, {"n": 2351, "text": "\t\t\t\t\t\t\t\tret = pgxc_node_receive(1, &conn, &timeout);"}, {"n": 2352, "text": "\t\t\t\t\t\t\t\tif (DNStatus_OK == ret)"}, {"n": 2353, "text": "\t\t\t\t\t\t\t\t{"}, {"n": 2354, "text": "\t\t\t\t\t\t\t\t\t/* We got data, prefetch it. */"}, {"n": 2355, "text": "\t\t\t\t\t\t\t\t\tbComplete = PreFetchConnection(conn, i);"}, {"n": 2356, "text": "\t\t\t\t\t\t\t\t\tif (bComplete)"}, {"n": 2357, "text": "\t\t\t\t\t\t\t\t\t{"}, {"n": 2358, "text": "\t\t\t\t\t\t\t\t\t\t/* Receive Complete on one connection, we need retry to read from current_conn. */"}, {"n": 2359, "text": "\t\t\t\t\t\t\t\t\t\tbreak;"}, {"n": 2360, "text": "\t\t\t\t\t\t\t\t\t}"}, {"n": 2361, "text": "\t\t\t\t\t\t\t\t\telse"}, {"n": 2362, "text": "\t\t\t\t\t\t\t\t\t{"}, {"n": 2363, "text": "\t\t\t\t\t\t\t\t\t\t/* Maybe Suspend or Expired, just move to next connection and read. */"}, {"n": 2364, "text": "\t\t\t\t\t\t\t\t\t\tcontinue;"}, {"n": 2365, "text": "\t\t\t\t\t\t\t\t\t}"}, {"n": 2366, "text": "\t\t\t\t\t\t\t\t}"}, {"n": 2367, "text": "\t\t\t\t\t\t\t\telse if (DNStatus_EXPIRED == ret)"}, {"n": 2368, "text": "\t\t\t\t\t\t\t\t{"}, {"n": 2369, "text": "\t\t\t\t\t\t\t\t\t/* Restore the saved state of connection. */"}, {"n": 2370, "text": "\t\t\t\t\t\t\t\t\tUpdateConnectionState(conn, state);"}, {"n": 2371, "text": "\t\t\t\t\t\t\t\t\tcontinue;"}, {"n": 2372, "text": "\t\t\t\t\t\t\t\t}"}, {"n": 2373, "text": "\t\t\t\t\t\t\t\telse"}, {"n": 2374, "text": "\t\t\t\t\t\t\t\t{"}, {"n": 2375, "text": "\t\t\t\t\t\t\t\t\tereport(ERROR,"}, {"n": 2376, "text": "\t\t\t\t\t\t\t\t\t\t\t(errcode(ERRCODE_EXEC_REMOTE_ERROR),"}, {"n": 2377, "text": "\t\t\t\t\t\t\t\t\t\t\t errmsg(\"Failed to receive more \""}, {"n": 2378, "text": "\t\t\t\t\t\t\t\t\t\t\t\t\t\"data from data node %s pid %d\","}, {"n": 2379, "text": "\t\t\t\t\t\t\t\t\t\t\t\t\tconn->nodename, conn->backend_pid)));"}, {"n": 2380, "text": "\t\t\t\t\t\t\t\t}"}, {"n": 2381, "text": "\t\t\t\t\t\t\t}"}, {"n": 2382, "text": "\t\t\t\t\t\t}"}, {"n": 2383, "text": "\t\t\t\t\t}"}, {"n": 2384, "text": "\t\t\t\t}"}, {"n": 2385, "text": "\t\t\t}"}, {"n": 2386, "text": "\t\t\telse"}, {"n": 2387, "text": "\t\t\t{"}, {"n": 2388, "text": "\t\t\t\t/* incomplete message, read more */"}, {"n": 2389, "text": "\t\t\t\tif (pgxc_node_receive(1, &conn, NULL))"}, {"n": 2390, "text": "\t\t\t\t\tereport(ERROR,"}, {"n": 2391, "text": "\t\t\t\t\t\t\t(errcode(ERRCODE_EXEC_REMOTE_ERROR),"}, {"n": 2392, "text": "\t\t\t\t\t\t\t errmsg(\"Failed to receive more data from data \""}, {"n": 2393, "text": "\t\t\t\t\t\t\t\t\t\"node %s pid %d\","}, {"n": 2394, "text": "\t\t\t\t\t\t\t\t\tconn->nodename, conn->backend_pid)));"}, {"n": 2395, "text": "\t\t\t}"}, {"n": 2396, "text": "\t\t\tcontinue;"}, {"n": 2397, "text": "\t\t}"}, {"n": 2398, "text": "\t\telse if (res == RESPONSE_SUSPENDED)"}, {"n": 2399, "text": "\t\t{"}, {"n": 2400, "text": "\t\t\t/*"}, {"n": 2401, "text": "\t\t\t * If we are doing merge sort or probing primary node we should"}, {"n": 2402, "text": "\t\t\t * remain on the same node, so query next portion immediately."}, {"n": 2403, "text": "\t\t\t * Otherwise leave node suspended and fetch lazily."}, {"n": 2404, "text": "\t\t\t */"}, {"n": 2405, "text": "\t\t\tif (combiner->merge_sort || combiner->probing_primary)"}, {"n": 2406, "text": "\t\t\t{"}, {"n": 2407, "text": "\t\t\t\tif (pgxc_node_send_execute(conn, combiner->cursor, PGXLRemoteFetchSize, false) != 0)"}, {"n": 2408, "text": "\t\t\t\t\tereport(ERROR,"}, {"n": 2409, "text": "\t\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2410, "text": "\t\t\t\t\t\t\t errmsg(\"Failed to send execute cursor '%s' to node %u\","}, {"n": 2411, "text": "\t\t\t\t\t\t\t\t\tcombiner->cursor, conn->nodeoid)));"}, {"n": 2412, "text": "\t\t\t\tif (SendFlushRequest(conn) != 0)"}, {"n": 2413, "text": "\t\t\t\t\tereport(ERROR,"}, {"n": 2414, "text": "\t\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2415, "text": "\t\t\t\t\t\t\t errmsg(\"Failed flush cursor '%s' node %u\","}, {"n": 2416, "text": "\t\t\t\t\t\t\t\t\tcombiner->cursor, conn->nodeoid)));"}, {"n": 2417, "text": "\t\t\t\tif (pgxc_node_receive(1, &conn, NULL))"}, {"n": 2418, "text": "\t\t\t\t\tereport(ERROR,"}, {"n": 2419, "text": "\t\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2420, "text": "\t\t\t\t\t\t\t errmsg(\"Failed receive node from node %u cursor '%s'\","}, {"n": 2421, "text": "\t\t\t\t\t\t\t\t\tconn->nodeoid, combiner->cursor)));"}, {"n": 2422, "text": "\t\t\t\tcontinue;"}, {"n": 2423, "text": "\t\t\t}"}, {"n": 2424, "text": ""}, {"n": 2425, "text": "\t\t\t/*"}, {"n": 2426, "text": "\t\t\t * Tell the node to fetch data in background, next loop when we"}, {"n": 2427, "text": "\t\t\t * pgxc_node_receive, data is already there, so we can run faster"}, {"n": 2428, "text": "\t\t\t * */"}, {"n": 2429, "text": "\t\t\tif (pgxc_node_send_execute(conn, combiner->cursor, PGXLRemoteFetchSize, false) != 0)"}, {"n": 2430, "text": "\t\t\t{"}, {"n": 2431, "text": "\t\t\t\tereport(ERROR,"}, {"n": 2432, "text": "\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2433, "text": "\t\t\t\t\t\t errmsg(\"Failed to send execute cursor '%s' to node %u\","}, {"n": 2434, "text": "\t\t\t\t\t\t\t\tcombiner->cursor, conn->nodeoid)));"}, {"n": 2435, "text": "\t\t\t}"}, {"n": 2436, "text": ""}, {"n": 2437, "text": "\t\t\tif (SendFlushRequest(conn) != 0)"}, {"n": 2438, "text": "\t\t\t{"}, {"n": 2439, "text": "\t\t\t\tereport(ERROR,"}, {"n": 2440, "text": "\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2441, "text": "\t\t\t\t\t\t errmsg(\"Failed flush cursor '%s' node %u\","}, {"n": 2442, "text": "\t\t\t\t\t\t\t\tcombiner->cursor, conn->nodeoid)));"}, {"n": 2443, "text": "\t\t\t}"}, {"n": 2444, "text": ""}, {"n": 2445, "text": "\t\t\tif (++combiner->current_conn >= combiner->conn_count)"}, {"n": 2446, "text": "\t\t\t{"}, {"n": 2447, "text": "\t\t\t\tcombiner->current_conn = 0;"}, {"n": 2448, "text": "\t\t\t}"}, {"n": 2449, "text": "\t\t\tcombiner->current_conn_rows_consumed = 0;"}, {"n": 2450, "text": "\t\t\tconn = combiner->connections[combiner->current_conn];"}, {"n": 2451, "text": "\t\t}"}, {"n": 2452, "text": "\t\telse if (res == RESPONSE_COMPLETE)"}, {"n": 2453, "text": "\t\t{"}, {"n": 2454, "text": "\t\t\tif (IsConnectionStateFatal(conn))"}, {"n": 2455, "text": "\t\t\t{"}, {"n": 2456, "text": "\t\t\t\tereport(ERROR,"}, {"n": 2457, "text": "\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 2458, "text": "\t\t\t\t\t\t errmsg(\"Unexpected FATAL ERROR on Connection to Datanode %s pid %d\","}, {"n": 2459, "text": "\t\t\t\t\t\t\t\tconn->nodename, conn->backend_pid)));"}, {"n": 2460, "text": "\t\t\t}"}, {"n": 2461, "text": ""}, {"n": 2462, "text": "\t\t\t/*"}, {"n": 2463, "text": "\t\t\t * In case of Simple Query Protocol we should receive ReadyForQuery"}, {"n": 2464, "text": "\t\t\t * before removing connection from the list. In case of Extended"}, {"n": 2465, "text": "\t\t\t * Query Protocol we may remove connection right away."}, {"n": 2466, "text": "\t\t\t */"}, {"n": 2467, "text": "\t\t\tif (combiner->extended_query)"}, {"n": 2468, "text": "\t\t\t{"}, {"n": 2469, "text": "\t\t\t\t/* If we are doing merge sort clean current connection and return"}, {"n": 2470, "text": "\t\t\t\t * NULL, otherwise remove current connection, move last in-place,"}, {"n": 2471, "text": "\t\t\t\t * adjust current_conn and continue if it is not last connection */"}, {"n": 2472, "text": "\t\t\t\tif (combiner->merge_sort)"}, {"n": 2473, "text": "\t\t\t\t{"}, {"n": 2474, "text": ""}, {"n": 2475, "text": "\t\t\t\t\tcombiner->connections[combiner->current_conn]->combiner = NULL;"}, {"n": 2476, "text": "\t\t\t\t\tcombiner->connections[combiner->current_conn] = NULL;"}, {"n": 2477, "text": ""}, {"n": 2478, "text": "\t\t\t\t\t/* data left in row_buffer, read it */"}, {"n": 2479, "text": "\t\t\t\t\tif ((combiner->prerowBuffers && list_length(combiner->prerowBuffers[combiner->current_conn]) > 0) ||"}, {"n": 2480, "text": "\t\t\t\t\t\t(combiner->dataRowBuffer && combiner->dataRowBuffer[combiner->current_conn]))"}, {"n": 2481, "text": "\t\t\t\t\t{"}, {"n": 2482, "text": "\t\t\t\t\t\telog(DEBUG1, \"FetchTuple:data left in rowbuffer while merge_sort.\");"}, {"n": 2483, "text": "\t\t\t\t\t\tconn = NULL;"}, {"n": 2484, "text": "\t\t\t\t\t\tgoto READ_ROWBUFFER;"}, {"n": 2485, "text": "\t\t\t\t\t}"}, {"n": 2486, "text": ""}, {"n": 2487, "text": "\t\t\t\t\treturn NULL;"}, {"n": 2488, "text": "\t\t\t\t}"}, {"n": 2489, "text": ""}, {"n": 2490, "text": "\t\t\t\tREMOVE_CURR_CONN(combiner);"}, {"n": 2491, "text": "\t\t\t\tif (combiner->conn_count > 0)"}, {"n": 2492, "text": "\t\t\t\t{"}, {"n": 2493, "text": "\t\t\t\t\tconn = combiner->connections[combiner->current_conn];"}, {"n": 2494, "text": "\t\t\t\t\tcombiner->current_conn_rows_consumed = 0;"}, {"n": 2495, "text": "\t\t\t\t}"}, {"n": 2496, "text": "\t\t\t\telse"}, {"n": 2497, "text": "\t\t\t\t{"}, {"n": 2498, "text": "\t\t\t\t\t/* data left in row_buffer, read it */"}, {"n": 2499, "text": "\t\t\t\t\tif (list_length(combiner->rowBuffer) > 0 ||"}, {"n": 2500, "text": "\t\t\t\t\t\t(combiner->dataRowBuffer && combiner->dataRowBuffer[0]))"}, {"n": 2501, "text": "\t\t\t\t\t{"}, {"n": 2502, "text": "\t\t\t\t\t\telog(DEBUG1, \"FetchTuple:data left in rowbuffer in extended_query.\");"}, {"n": 2503, "text": "\t\t\t\t\t\tgoto READ_ROWBUFFER;"}, {"n": 2504, "text": "\t\t\t\t\t}"}, {"n": 2505, "text": ""}, {"n": 2506, "text": "\t\t\t\t\treturn NULL;"}, {"n": 2507, "text": "\t\t\t\t}"}, {"n": 2508, "text": "\t\t\t}"}, {"n": 2509, "text": "\t\t}"}, {"n": 2510, "text": "\t\telse if (res == RESPONSE_ERROR)"}, {"n": 2511, "text": "\t\t{"}, {"n": 2512, "text": "\t\t\t/*"}, {"n": 2513, "text": "\t\t\t * Do not wait for response from primary, it needs to wait"}, {"n": 2514, "text": "\t\t\t * for other nodes to respond. Instead go ahead and send query to"}, {"n": 2515, "text": "\t\t\t * other nodes. It will fail there, but we can continue with"}, {"n": 2516, "text": "\t\t\t * normal cleanup."}, {"n": 2517, "text": "\t\t\t */"}, {"n": 2518, "text": "\t\t\tif (combiner->probing_primary)"}, {"n": 2519, "text": "\t\t\t{"}, {"n": 2520, "text": "\t\t\t\tREMOVE_CURR_CONN(combiner);"}, {"n": 2521, "text": "\t\t\t}"}, {"n": 2522, "text": "\t\t\treturn NULL;"}, {"n": 2523, "text": "\t\t}"}, {"n": 2524, "text": "\t\telse if (res == RESPONSE_READY)"}, {"n": 2525, "text": "\t\t{"}, {"n": 2526, "text": "\t\t\t/* If we are doing merge sort clean current connection and return"}, {"n": 2527, "text": "\t\t\t * NULL, otherwise remove current connection, move last in-place,"}, {"n": 2528, "text": "\t\t\t * adjust current_conn and continue if it is not last connection */"}, {"n": 2529, "text": "\t\t\tif (combiner->merge_sort)"}, {"n": 2530, "text": "\t\t\t{"}, {"n": 2531, "text": "\t\t\t\tcombiner->connections[combiner->current_conn]->combiner = NULL;"}, {"n": 2532, "text": "\t\t\t\tcombiner->connections[combiner->current_conn] = NULL;"}, {"n": 2533, "text": ""}, {"n": 2534, "text": "\t\t\t\t/* data left in row_buffer, read it */"}, {"n": 2535, "text": "\t\t\t\tif ((combiner->prerowBuffers && list_length(combiner->prerowBuffers[combiner->current_conn]) > 0) ||"}, {"n": 2536, "text": "\t\t\t\t\t(combiner->dataRowBuffer && combiner->dataRowBuffer[combiner->current_conn]))"}, {"n": 2537, "text": "\t\t\t\t{"}, {"n": 2538, "text": "\t\t\t\t\telog(DEBUG1, \"FetchTuple:data left in rowbuffer while merge_sort.\");"}, {"n": 2539, "text": "\t\t\t\t\tconn = NULL;"}, {"n": 2540, "text": "\t\t\t\t\tgoto READ_ROWBUFFER;"}, {"n": 2541, "text": "\t\t\t\t}"}, {"n": 2542, "text": ""}, {"n": 2543, "text": "\t\t\t\treturn NULL;"}, {"n": 2544, "text": "\t\t\t}"}, {"n": 2545, "text": ""}, {"n": 2546, "text": "\t\t\tREMOVE_CURR_CONN(combiner);"}, {"n": 2547, "text": "\t\t\tif (combiner->conn_count > 0)"}, {"n": 2548, "text": "\t\t\t\tconn = combiner->connections[combiner->current_conn];"}, {"n": 2549, "text": "\t\t\telse"}, {"n": 2550, "text": "\t\t\t{"}, {"n": 2551, "text": "\t\t\t\t/* data left in row_buffer, read it */"}, {"n": 2552, "text": "\t\t\t\tif (list_length(combiner->rowBuffer) > 0 ||"}, {"n": 2553, "text": "\t\t\t\t\t(combiner->dataRowBuffer && combiner->dataRowBuffer[0]))"}, {"n": 2554, "text": "\t\t\t\t{"}, {"n": 2555, "text": "\t\t\t\t\telog(DEBUG1, \"FetchTuple:data left in rowbuffer in simple_query.\");"}, {"n": 2556, "text": "\t\t\t\t\tgoto READ_ROWBUFFER;"}, {"n": 2557, "text": "\t\t\t\t}"}, {"n": 2558, "text": "\t\t\t\treturn NULL;"}, {"n": 2559, "text": "\t\t\t}"}, {"n": 2560, "text": "\t\t}"}, {"n": 2561, "text": "\t\telse if (res == RESPONSE_TUPDESC)"}, {"n": 2562, "text": "\t\t{"}, {"n": 2563, "text": "\t\t\tExecSetSlotDescriptor(combiner->ss.ps.ps_ResultTupleSlot,"}, {"n": 2564, "text": "\t\t\t\t\t\t\t\t  combiner->tuple_desc);"}, {"n": 2565, "text": "\t\t\t/* Now slot is responsible for freeng the descriptor */"}, {"n": 2566, "text": "\t\t\tcombiner->tuple_desc = NULL;"}, {"n": 2567, "text": "\t\t}"}, {"n": 2568, "text": "\t\telse if (res == RESPONSE_ASSIGN_GXID)"}, {"n": 2569, "text": "\t\t{"}, {"n": 2570, "text": "\t\t\t/* Do nothing. It must have been handled in handle_response() */"}, {"n": 2571, "text": "\t\t}"}, {"n": 2572, "text": "\t\telse if (res == RESPONSE_WAITXIDS)"}, {"n": 2573, "text": "\t\t{"}, {"n": 2574, "text": "\t\t\t/* Do nothing. It must have been handled in handle_response() */"}, {"n": 2575, "text": "\t\t}"}, {"n": 2576, "text": "\t\telse"}, {"n": 2577, "text": "\t\t{"}, {"n": 2578, "text": "\t\t\t/* Can not get here? */"}, {"n": 2579, "text": "\t\t\tAssert(false);"}, {"n": 2580, "text": "\t\t}"}, {"n": 2581, "text": "\t}"}, {"n": 2582, "text": ""}, {"n": 2583, "text": "\treturn NULL;"}, {"n": 2584, "text": "}"}, {"n": 2585, "text": ""}, {"n": 2586, "text": "#ifdef __OPENTENBASE__"}, {"n": 3043, "text": " * RESPONSE_DATAROW - got data row"}, {"n": 3044, "text": " * RESPONSE_COPY - got copy response"}, {"n": 3045, "text": " * RESPONSE_BARRIER_OK - barrier command completed successfully"}, {"n": 3046, "text": " */"}, {"n": 3047, "text": "int"}, {"n": 3048, "text": "handle_response_internal(PGXCNodeHandle *conn, ResponseCombiner *combiner, char *file, int line)"}, {"n": 3049, "text": "{"}, {"n": 3050, "text": "\tchar\t   *msg;"}, {"n": 3051, "text": "\tint\t\t\tmsg_len;"}, {"n": 3052, "text": "\tchar\t\tmsg_type;"}, {"n": 3053, "text": "\tuint8\t\tres_seq;"}, {"n": 3054, "text": ""}, {"n": 3055, "text": "\tfor (;;)"}, {"n": 3056, "text": "\t{"}, {"n": 3057, "text": "\t\t/*"}, {"n": 3058, "text": "\t\t * If we are in the process of shutting down, we"}, {"n": 3059, "text": "\t\t * may be rolling back, and the buffer may contain other messages."}, {"n": 3060, "text": "\t\t * We want to avoid a procarray exception"}, {"n": 3061, "text": "\t\t * as well as an error stack overflow."}, {"n": 3062, "text": "\t\t */"}, {"n": 3063, "text": "\t\tif (proc_exit_inprogress)"}, {"n": 3064, "text": "\t\t{"}, {"n": 3065, "text": "\t\t\tUpdateConnectionState(conn, DN_CONNECTION_STATE_FATAL);"}, {"n": 3066, "text": "\t\t}"}, {"n": 3067, "text": ""}, {"n": 3068, "text": "\t\t/*"}, {"n": 3069, "text": "\t\t * Don't read from from the connection if there is a fatal error."}, {"n": 3070, "text": "\t\t * We still return RESPONSE_COMPLETE, not RESPONSE_ERROR, since"}, {"n": 3071, "text": "\t\t * Handling of RESPONSE_ERROR assumes sending SYNC message, but"}, {"n": 3072, "text": "\t\t * State DN_CONNECTION_STATE_FATAL indicates connection is"}, {"n": 3073, "text": "\t\t * not usable."}, {"n": 3074, "text": "\t\t */"}, {"n": 3075, "text": "\t\tif (IsConnectionStateFatal(conn))"}, {"n": 3076, "text": "\t\t{"}, {"n": 3077, "text": "\t\t\treturn RESPONSE_COMPLETE;"}, {"n": 3078, "text": "\t\t}"}, {"n": 3079, "text": ""}, {"n": 3080, "text": "\t\t/* No data available, exit */"}, {"n": 3081, "text": "\t\tif (!HAS_MESSAGE_BUFFERED(conn))"}, {"n": 3082, "text": "\t\t\treturn RESPONSE_EOF;"}, {"n": 3083, "text": ""}, {"n": 3084, "text": "\t\t/* TODO handle other possible responses */"}, {"n": 3085, "text": "\t\tmsg_type = get_message(conn, &msg_len, &msg);"}, {"n": 3086, "text": ""}, {"n": 3087, "text": "\t\tif (enable_distri_print)"}, {"n": 3088, "text": "\t\t\telog(LOG, \"handle_response - received message %c, node %s %d, current_state %s txn state:  %c, file %s:%d\","}, {"n": 3089, "text": "\t\t\t\t msg_type, conn->nodename, conn->backend_pid, GetConnectionStateTag(conn), GetTxnState(conn), file, line);"}, {"n": 3090, "text": ""}, {"n": 3091, "text": "\t\t/*"}, {"n": 3092, "text": "\t\t * Add some protection code when receiving a messy message,"}, {"n": 3093, "text": "\t\t * close the connection, and throw error"}, {"n": 3094, "text": "\t\t */"}, {"n": 3095, "text": "\t\tif (msg_len < 0)"}, {"n": 3096, "text": "\t\t\tDestroyHandle(conn);"}, {"n": 3097, "text": ""}, {"n": 3098, "text": "\t\tif (msg_type != 'D' && msg_type != '9')"}, {"n": 3099, "text": "\t\t\tRecordRecvMessage(conn, msg_type, NULL, 0);"}, {"n": 3100, "text": ""}, {"n": 3101, "text": "\t\t/*  the state */"}, {"n": 3102, "text": "\t\tSafeSwitchConnectionState(conn, combiner, msg_type, msg_len, msg);"}, {"n": 3103, "text": ""}, {"n": 3104, "text": "\t\tswitch (msg_type)"}, {"n": 3105, "text": "\t\t{"}, {"n": 3106, "text": "\t\t\tcase '\\0':\t\t\t/* Not enough data in the buffer */"}, {"n": 3107, "text": "\t\t\t\treturn RESPONSE_EOF;"}, {"n": 3108, "text": ""}, {"n": 3109, "text": "\t\t\tcase 'c':\t\t\t/* CopyToCommandComplete */"}, {"n": 3110, "text": "\t\t\t\tif (combiner)"}, {"n": 3111, "text": "\t\t\t\t\tHandleCopyOutComplete(combiner);"}, {"n": 3112, "text": "\t\t\t\tbreak;"}, {"n": 3113, "text": ""}, {"n": 3114, "text": "\t\t\tcase 'C':\t\t\t/* CommandComplete */"}, {"n": 3115, "text": "\t\t\t\t/*"}, {"n": 3116, "text": "\t\t\t\t * After the CommandComplete message, some message dislocation can be tolerated."}, {"n": 3117, "text": "\t\t\t\t * For example, the DN node reports an error and sends ReadyForQuery to this node"}, {"n": 3118, "text": "\t\t\t\t */"}, {"n": 3119, "text": "\t\t\t\tconn->cmd_strict = false;"}, {"n": 3120, "text": ""}, {"n": 3121, "text": "\t\t\t\tif (combiner)"}, {"n": 3122, "text": "\t\t\t\t\tHandleCommandComplete(combiner, msg, msg_len, conn);"}, {"n": 3123, "text": "\t\t\t\tconn->combiner = NULL;"}, {"n": 3124, "text": "\t\t\t\treturn RESPONSE_COMPLETE;"}, {"n": 3125, "text": "\t\t\tcase 'F':\t\t\t/* Session Hold flag */"}, {"n": 3126, "text": "\t\t\t\tbreak;"}, {"n": 3127, "text": "\t\t\tcase 'T':\t\t\t/* RowDescription */"}, {"n": 3128, "text": "#ifdef DN_CONNECTION_DEBUG"}, {"n": 3129, "text": "\t\t\t\tAssert(!conn->have_row_desc);"}, {"n": 3130, "text": "\t\t\t\tconn->have_row_desc = true;"}, {"n": 3131, "text": "#endif"}, {"n": 3132, "text": "\t\t\t\tAssert(!IsTransactionCommit());"}, {"n": 3133, "text": "\t\t\t\tif (IsTransactionCommit())"}, {"n": 3134, "text": "\t\t\t\t{"}, {"n": 3135, "text": "\t\t\t\t\t/* Shouldn't be here. */"}, {"n": 3136, "text": "\t\t\t\t\telog(FATAL, \"Unexpected T message when transacation is already committed, \""}, {"n": 3137, "text": "\t\t\t\t\t\t\t\t\"remote node %s, remote pid %d, current_state %s, transaction_state %c, subtrans_id %d\","}, {"n": 3138, "text": "\t\t\t\t\t\t conn->nodename, conn->backend_pid,"}, {"n": 3139, "text": "\t\t\t\t\t\t GetConnectionStateTag(conn), GetTxnState(conn), GetSubTransactionId(conn));"}, {"n": 3140, "text": "\t\t\t\t}"}, {"n": 3141, "text": "\t\t\t\tif (combiner && HandleRowDescription(combiner, msg, msg_len))"}, {"n": 3142, "text": "\t\t\t\t\treturn RESPONSE_TUPDESC;"}, {"n": 3143, "text": "\t\t\t\tbreak;"}, {"n": 3144, "text": ""}, {"n": 3145, "text": "\t\t\tcase 'D':\t\t\t/* DataRow */"}, {"n": 3146, "text": "\t\t\tcase 'X':\t\t\t/* DataRow ,but from remote tid scan*/"}, {"n": 3147, "text": "#ifdef DN_CONNECTION_DEBUG"}, {"n": 3148, "text": "\t\t\t\tAssert(conn->have_row_desc);"}, {"n": 3149, "text": "#endif"}, {"n": 3150, "text": "\t\t\t\t/* Do not return if data row has not been actually handled */"}, {"n": 3151, "text": "\t\t\t\tif (combiner && HandleDataRow(combiner, msg, msg_len, conn->nodeoid, msg_type == 'X'))"}, {"n": 3152, "text": "\t\t\t\t{"}, {"n": 3153, "text": "\t\t\t\t\telog(DEBUG1, \"HandleDataRow from node %s, remote pid %d\","}, {"n": 3154, "text": "\t\t\t\t\t\t conn->nodename, conn->backend_pid);"}, {"n": 3155, "text": "\t\t\t\t\treturn RESPONSE_DATAROW;"}, {"n": 3156, "text": "\t\t\t\t}"}, {"n": 3157, "text": "\t\t\t\tbreak;"}, {"n": 3158, "text": ""}, {"n": 3159, "text": "\t\t\tcase 's':\t\t\t/* PortalSuspended */"}, {"n": 3160, "text": "\t\t\t\t/* No activity is expected on the connection until next query */"}, {"n": 3161, "text": "\t\t\t\treturn RESPONSE_SUSPENDED;"}, {"n": 3162, "text": ""}, {"n": 3163, "text": "\t\t\tcase '2': /* BindComplete */"}, {"n": 3164, "text": "\t\t\t{"}, {"n": 3165, "text": "\t\t\t\tif (combiner && combiner->waitfor2)"}, {"n": 3166, "text": "\t\t\t\t\treturn RESPONSE_BIND_COMPLETE;"}, {"n": 3167, "text": "\t\t\t\tbreak;"}, {"n": 3168, "text": "\t\t\t}"}, {"n": 3169, "text": ""}, {"n": 3170, "text": "\t\t\tcase '1': /* ParseComplete */"}, {"n": 3171, "text": "\t\t\tcase '3': /* CloseComplete */"}, {"n": 3172, "text": "\t\t\tcase 'n': /* NoData */"}, {"n": 3173, "text": "\t\t\t\t/* simple notifications, continue reading */"}, {"n": 3174, "text": "\t\t\t\tbreak;"}, {"n": 3175, "text": "#ifdef __SUBSCRIPTION__"}, {"n": 3176, "text": "\t\t\tcase '4': /* ApplyDone */"}, {"n": 3177, "text": "\t\t\t\tif (combiner)"}, {"n": 3178, "text": "\t\t\t\t\tHandleApplyDone(combiner);"}, {"n": 3179, "text": "\t\t\t\treturn RESPONSE_READY;"}, {"n": 3180, "text": "\t\t\t\tbreak;"}, {"n": 3181, "text": "#endif"}, {"n": 3182, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 3183, "text": "\t\t\tcase '5': /* FtableDone */"}, {"n": 3184, "text": "\t\t\t\tif (combiner)"}, {"n": 3185, "text": "\t\t\t\t\tHandleFtableDone(combiner);"}, {"n": 3186, "text": "\t\t\t\treturn RESPONSE_READY;"}, {"n": 3187, "text": "\t\t\t\tbreak;"}, {"n": 3188, "text": "#endif"}, {"n": 3189, "text": "\t\t\tcase 'G': /* CopyInResponse */"}, {"n": 3190, "text": "\t\t\t\tif(combiner)"}, {"n": 3191, "text": "\t\t\t\t\tHandleCopyIn(combiner);"}, {"n": 3192, "text": "\t\t\t\t/* Done, return to caller to let it know the data can be passed in */"}, {"n": 3193, "text": "\t\t\t\treturn RESPONSE_COPY;"}, {"n": 3194, "text": ""}, {"n": 3195, "text": "\t\t\tcase 'H': /* CopyOutResponse */"}, {"n": 3196, "text": "\t\t\t\tif (combiner)"}, {"n": 3197, "text": "\t\t\t\t\tHandleCopyOut(combiner);"}, {"n": 3198, "text": "\t\t\t\treturn RESPONSE_COPY;"}, {"n": 3199, "text": ""}, {"n": 3200, "text": "\t\t\tcase 'd': /* CopyOutDataRow */"}, {"n": 3201, "text": "\t\t\t\tif (combiner)"}, {"n": 3202, "text": "\t\t\t\t\tHandleCopyDataRow(combiner, msg, msg_len);"}, {"n": 3203, "text": "\t\t\t\tbreak;"}, {"n": 3204, "text": ""}, {"n": 3205, "text": "\t\t\tcase 'E':\t\t\t/* ErrorResponse */"}, {"n": 3206, "text": "\t\t\t    /*"}, {"n": 3207, "text": "\t\t\t     * If an error occurs, cn may send sync messages for many times."}, {"n": 3208, "text": "\t\t\t     * At this time, it can tolerate some message misplacements"}, {"n": 3209, "text": "\t\t\t     */"}, {"n": 3210, "text": "\t\t\t\tconn->cmd_strict = false;"}, {"n": 3211, "text": "\t\t\t\tif (combiner)"}, {"n": 3212, "text": "\t\t\t\t{"}, {"n": 3213, "text": "\t\t\t\t\tHandleError(combiner, msg, msg_len, conn);"}, {"n": 3214, "text": "\t\t\t\t\tadd_error_message_from_combiner(conn, combiner);"}, {"n": 3215, "text": "\t\t\t\t}"}, {"n": 3216, "text": "\t\t\t\t/*"}, {"n": 3217, "text": "\t\t\t\t * In case the remote node was running an extended query"}, {"n": 3218, "text": "\t\t\t\t * protocol and reported an error, it will keep ignoring all"}, {"n": 3219, "text": "\t\t\t\t * subsequent commands until it sees a SYNC message. So make"}, {"n": 3220, "text": "\t\t\t\t * sure that we send down SYNC even before sending a ROLLBACK"}, {"n": 3221, "text": "\t\t\t\t * command"}, {"n": 3222, "text": "\t\t\t\t */"}, {"n": 3223, "text": "\t\t\t\tif (conn->state.in_extended_query)"}, {"n": 3224, "text": "\t\t\t\t{"}, {"n": 3225, "text": "\t\t\t\t\tconn->needSync = true;"}, {"n": 3226, "text": "\t\t\t\t}"}, {"n": 3227, "text": "#ifdef \t_PG_REGRESS_"}, {"n": 3228, "text": "\t\t\t\telog(LOG, \"HandleError from node %s, remote pid %d, errorMessage:%s, %s: %d\","}, {"n": 3229, "text": "\t\t\t\t\t\tconn->nodename, conn->backend_pid, combiner ? combiner->errorMessage : \"combiner NULL\", file, line);"}, {"n": 3230, "text": "#endif"}, {"n": 3231, "text": "\t\t\t\treturn RESPONSE_ERROR;"}, {"n": 3232, "text": ""}, {"n": 3233, "text": "\t\t\tcase 'A':\t\t\t/* NotificationResponse */"}, {"n": 3234, "text": "\t\t\tcase 'N':\t\t\t/* NoticeResponse */"}, {"n": 3235, "text": "\t\t\tcase 'S':\t\t\t/* SetCommandComplete */"}, {"n": 3236, "text": "\t\t\t\t/*"}, {"n": 3237, "text": "\t\t\t\t * Ignore these to prevent multiple messages, one from each"}, {"n": 3238, "text": "\t\t\t\t * node. Coordinator will send one for DDL anyway"}, {"n": 3239, "text": "\t\t\t\t */"}, {"n": 3240, "text": "\t\t\t\tbreak;"}, {"n": 3241, "text": ""}, {"n": 3242, "text": "\t\t\tcase 'Z':\t\t\t/* ReadyForQuery */"}, {"n": 3243, "text": "\t\t\t{"}, {"n": 3244, "text": "\t\t\t\t/*"}, {"n": 3245, "text": "\t\t\t\t * Return result depends on previous connection state."}, {"n": 3246, "text": "\t\t\t\t * If it was PORTAL_SUSPENDED Coordinator want to send down"}, {"n": 3247, "text": "\t\t\t\t * another EXECUTE to fetch more rows, otherwise it is done"}, {"n": 3248, "text": "\t\t\t\t * with the connection"}, {"n": 3249, "text": "\t\t\t\t */"}, {"n": 3250, "text": "\t\t\t\tSetHandleUsed(conn, false);"}, {"n": 3251, "text": "\t\t\t\tconn->combiner = NULL;"}, {"n": 3252, "text": ""}, {"n": 3253, "text": "\t\t\t\telog(DEBUG5, \"remote_node %s remote_pid %d, conn->state.transaction_state %c\","}, {"n": 3254, "text": "\t\t\t\t\tconn->nodename, conn->backend_pid, GetTxnState(conn));"}, {"n": 3255, "text": "#ifdef DN_CONNECTION_DEBUG"}, {"n": 3256, "text": "\t\t\t\tconn->have_row_desc = false;"}, {"n": 3257, "text": "#endif"}, {"n": 3258, "text": ""}, {"n": 3259, "text": "#ifdef \t_PG_REGRESS_"}, {"n": 3260, "text": "\t\t\t\telog(LOG, \"ReadyForQuery from node %s, remote pid %d\", conn->nodename, conn->backend_pid);"}, {"n": 3261, "text": "#endif"}, {"n": 3262, "text": "\t\t\t\tif (HandledAllReplay(conn))"}, {"n": 3263, "text": "\t\t\t\t\treturn RESPONSE_READY;"}, {"n": 3264, "text": "\t\t\t\telog(LOG, \"node %s pid %d received ready for query, but not expected one expected: %d, received: %d\","}, {"n": 3265, "text": "\t\t\t\t\t\tconn->nodename, conn->backend_pid, conn->state.sequence_number, conn->state.received_sno);"}, {"n": 3266, "text": "\t\t\t\treturn RESPONSE_READY_MISMATCH;"}, {"n": 3267, "text": "\t\t\t}"}, {"n": 3268, "text": "\t\t\tcase '8':"}, {"n": 3269, "text": "\t\t\t{"}, {"n": 3270, "text": "\t\t\t\tuint64 feedbackGts = pg_ntoh64(*(uint64*)msg);"}, {"n": 3271, "text": "\t\t\t\tif(enable_distri_print)"}, {"n": 3272, "text": "\t\t\t\t\telog(LOG, \"get feedbackGts \" INT64_FORMAT \" from datanode:%s\", feedbackGts, conn->nodename);"}, {"n": 3273, "text": ""}, {"n": 3274, "text": "\t\t\t\tUpdatelocalCacheGtsUseFeedbackGts(feedbackGts);"}, {"n": 3275, "text": "\t\t\t\tbreak;"}, {"n": 3276, "text": "\t\t\t}"}, {"n": 3277, "text": ""}, {"n": 3278, "text": "#ifdef __SUPPORT_DISTRIBUTED_TRANSACTION__"}, {"n": 3279, "text": "\t\t\tcase 'Y':\t\t\t/* ReadyForCommit */"}, {"n": 3280, "text": "\t\t\t{"}, {"n": 3281, "text": "\t\t\t\tconn->combiner = NULL;"}, {"n": 3282, "text": "#ifdef DN_CONNECTION_DEBUG"}, {"n": 3283, "text": "\t\t\t\tconn->have_row_desc = false;"}, {"n": 3284, "text": "#endif"}, {"n": 3285, "text": "\t\t\t\tif (enable_distri_print)"}, {"n": 3286, "text": "\t\t\t\t\telog(LOG, \"ReadyForQuery from node %s, remote pid %d\", conn->nodename, conn->backend_pid);"}, {"n": 3287, "text": "\t\t\t\treturn RESPONSE_READY;"}, {"n": 3288, "text": "\t\t\t}"}, {"n": 3289, "text": "#endif"}, {"n": 3290, "text": "\t\t\tcase 'M':\t\t\t/* Command Id */"}, {"n": 3291, "text": "\t\t\t\tif (combiner)"}, {"n": 3292, "text": "\t\t\t\t\tHandleDatanodeCommandId(combiner, msg, msg_len);"}, {"n": 3293, "text": "\t\t\t\tbreak;"}, {"n": 3294, "text": ""}, {"n": 3295, "text": "\t\t\tcase 'b':"}, {"n": 3296, "text": "\t\t\t\treturn RESPONSE_BARRIER_OK;"}, {"n": 3297, "text": ""}, {"n": 3298, "text": "\t\t\tcase 'I':\t\t\t/* EmptyQuery */"}, {"n": 3299, "text": "#ifdef \t_PG_REGRESS_"}, {"n": 3300, "text": "\t\t\t\telog(LOG, \"RESPONSE_COMPLETE_3 from node %s, remote pid %d\", conn->nodename, conn->backend_pid);"}, {"n": 3301, "text": "#endif"}, {"n": 3302, "text": "\t\t\t\treturn RESPONSE_COMPLETE;"}, {"n": 3303, "text": ""}, {"n": 3304, "text": "\t\t\tcase 'W':"}, {"n": 3305, "text": "\t\t\t\tHandleWaitXids(msg, msg_len);"}, {"n": 3306, "text": "\t\t\t\treturn RESPONSE_WAITXIDS;"}, {"n": 3307, "text": ""}, {"n": 3308, "text": "\t\t\tcase 'x':"}, {"n": 3309, "text": "\t\t\t\t#ifdef __USE_GLOBAL_SNAPSHOT__"}, {"n": 3310, "text": "\t\t\t\tHandleGlobalTransactionId(msg, msg_len);"}, {"n": 3311, "text": "\t\t\t\t#else"}, {"n": 3312, "text": "\t\t\t\telog(ERROR, \"should not set global xid\");"}, {"n": 3313, "text": "\t\t\t\t#endif"}, {"n": 3314, "text": "\t\t\t\treturn RESPONSE_ASSIGN_GXID;"}, {"n": 3315, "text": "\t\t\tcase 'J':"}, {"n": 3316, "text": "\t\t\t\tCNReceiveResGroupReply();"}, {"n": 3317, "text": "\t\t\t\tconn->combiner = NULL;"}, {"n": 3318, "text": "\t\t\t\treturn RESPONSE_COMPLETE;"}, {"n": 3319, "text": "\t\t\tcase 't': /*simple dml ctid*/"}, {"n": 3320, "text": "\t\t\t\tif (combiner)"}, {"n": 3321, "text": "\t\t\t\t\tHandleSimpleDmlCtid(combiner, msg, msg_len);"}, {"n": 3322, "text": "\t\t\t\tbreak;"}, {"n": 3323, "text": "\t\t\tcase '9':"}, {"n": 3324, "text": "\t\t\t\tres_seq = (uint8)msg[0];"}, {"n": 3325, "text": "\t\t\t\tconn->state.received_sno = res_seq;"}, {"n": 3326, "text": "\t\t\t\tRecordRecvMessage(conn, msg_type, (char *)&res_seq, 1);"}, {"n": 3327, "text": "\t\t\t\tif (enable_distri_print)"}, {"n": 3328, "text": "\t\t\t\t\telog(LOG, \"get cmd_seq from datanode:%s cmd_seq:%u\", conn->nodename, res_seq);"}, {"n": 3329, "text": "\t\t\t\tbreak;"}, {"n": 3330, "text": "\t\t\tcase 'a':"}, {"n": 3331, "text": "\t\t\t\tconn->combiner = NULL;"}, {"n": 3332, "text": "\t\t\t\tSetHandleUsed(conn, false);"}, {"n": 3333, "text": "\t\t\t\treturn ERSPONSE_ANALYZE;"}, {"n": 3334, "text": "\t\t\tcase 'e':"}, {"n": 3335, "text": "\t\t\t\tconn->combiner = NULL;"}, {"n": 3336, "text": "\t\t\t\treturn RESPONSE_COMPLETE;"}, {"n": 3337, "text": "\t\t\tcase 'i': /* Remote Instrument */"}, {"n": 3338, "text": "\t\t\t\tif (msg_len > 0)"}, {"n": 3339, "text": "\t\t\t\t\tHandleRemoteInstr(msg, msg_len, conn->nodeoid, conn->fid);"}, {"n": 3340, "text": "\t\t\t\tbreak;"}, {"n": 3341, "text": "\t\t\tdefault:"}, {"n": 3342, "text": "\t\t\t\t/* sync lost? */"}, {"n": 3343, "text": "\t\t\t\telog(WARNING, \"Received unsupported message type: %c\", msg_type);"}, {"n": 3344, "text": "\t\t\t\tUpdateConnectionState(conn, DN_CONNECTION_STATE_FATAL);"}, {"n": 3345, "text": "\t\t\t\t/* stop reading */"}, {"n": 3346, "text": "\t\t\t\telog(LOG, \"RESPONSE_COMPLETE_4 from node %s, remote pid %d\", conn->nodename, conn->backend_pid);"}, {"n": 3347, "text": "\t\t\t\treturn RESPONSE_COMPLETE;"}, {"n": 3348, "text": "\t\t}"}, {"n": 3349, "text": "\t}"}, {"n": 3350, "text": "\t/* never happen, but keep compiler quiet */"}, {"n": 3351, "text": "\treturn RESPONSE_EOF;"}, {"n": 3352, "text": "}"}, {"n": 3353, "text": ""}, {"n": 3354, "text": "/*"}, {"n": 6750, "text": "\treturn pgxc_handles;"}, {"n": 6751, "text": "}"}, {"n": 6752, "text": ""}, {"n": 6753, "text": ""}, {"n": 6754, "text": "static bool"}, {"n": 6755, "text": "pgxc_start_command_on_connection(PGXCNodeHandle *connection,"}, {"n": 6756, "text": "\t\t\t\t\t\t\t\t RemoteQueryState *remotestate,"}, {"n": 6757, "text": "\t\t\t\t\t\t\t\t Snapshot snapshot,"}, {"n": 6758, "text": "\t\t\t\t\t\t\t\t bool prepared)"}, {"n": 6759, "text": "{"}, {"n": 6760, "text": "\tCommandId\tcid;"}, {"n": 6761, "text": "\tResponseCombiner *combiner = (ResponseCombiner *) remotestate;"}, {"n": 6762, "text": "\tRemoteQuery\t*step = (RemoteQuery *) combiner->ss.ps.plan;"}, {"n": 6763, "text": "\tEState *estate = combiner->ss.ps.state;"}, {"n": 6764, "text": "\tint16 *formats = NULL;"}, {"n": 6765, "text": "\tint   n_formats = 0;"}, {"n": 6766, "text": ""}, {"n": 6767, "text": "\tDrainConnectionAndSetNewCombiner(connection, combiner);"}, {"n": 6768, "text": ""}, {"n": 6769, "text": "\telog(DEBUG5, \"pgxc_start_command_on_connection - node %s, state %d\","}, {"n": 6770, "text": "\t\t\tconnection->nodename, GetConnectionState(connection));"}, {"n": 6771, "text": ""}, {"n": 6772, "text": "\t/*"}, {"n": 6773, "text": "\t * Scan descriptor would be valid and would contain a valid snapshot"}, {"n": 6774, "text": "\t * in cases when we need to send out of order command id to data node"}, {"n": 6775, "text": "\t * e.g. in case of a fetch"}, {"n": 6776, "text": "\t */"}, {"n": 6777, "text": "\tif (snapshot && ActivePortal && ActivePortal->cursor)"}, {"n": 6778, "text": "\t{"}, {"n": 6779, "text": "\t\tcid = snapshot->curcid;"}, {"n": 6780, "text": ""}, {"n": 6781, "text": "\t\tif (cid == InvalidCommandId)"}, {"n": 6782, "text": "\t\t{"}, {"n": 6783, "text": "\t\t\telog(LOG, \"commandId in snapshot is invalid.\");"}, {"n": 6784, "text": "\t\t\tcid = GetCurrentCommandId(false);"}, {"n": 6785, "text": "\t\t}"}, {"n": 6786, "text": "\t}"}, {"n": 6787, "text": "\telse"}, {"n": 6788, "text": "\t{"}, {"n": 6789, "text": "\t\tcid = GetCurrentCommandId(false);"}, {"n": 6790, "text": "\t}"}, {"n": 6791, "text": ""}, {"n": 6792, "text": "\tif (pgxc_node_send_cmd_id(connection, cid) < 0 )"}, {"n": 6793, "text": "\t\treturn false;"}, {"n": 6794, "text": ""}, {"n": 6795, "text": "\tif (IsA(combiner->ss.ps.plan, RemoteQuery) &&"}, {"n": 6796, "text": "\t\t!(remotestate->eflags & (EXEC_FLAG_WITH_DESC | EXEC_FLAG_EXPLAIN_ONLY))"}, {"n": 6797, "text": "\t\t&& !combiner->merge_sort && IS_PGXC_COORDINATOR && combiner->ss.ps.plan->targetlist != NULL)"}, {"n": 6798, "text": "\t{"}, {"n": 6799, "text": "\t\tcombiner->ss.ps.state->cn_penetrate_tuple = true;"}, {"n": 6800, "text": "\t\tif (pgxc_node_send_no_tuple_descriptor(connection) < 0 )"}, {"n": 6801, "text": "\t\t\treturn false;"}, {"n": 6802, "text": "\t\tif (pgxc_node_send_dn_direct_printtup(connection) < 0 )"}, {"n": 6803, "text": "\t\t\treturn false;"}, {"n": 6804, "text": "\t}"}, {"n": 6805, "text": ""}, {"n": 6806, "text": "\tif (snapshot && pgxc_node_send_snapshot(connection, snapshot))"}, {"n": 6807, "text": "\t\treturn false;"}, {"n": 6808, "text": "\tif (ORA_MODE && pgxc_node_send_exec_env_if(connection))"}, {"n": 6809, "text": "\t\treturn false;"}, {"n": 6810, "text": "\tif (step->statement || step->cursor || remotestate->rqs_num_params)"}, {"n": 6811, "text": "\t{"}, {"n": 6812, "text": "\t\t/* need to use Extended Query Protocol */"}, {"n": 6813, "text": "\t\tint\tfetch = 0;"}, {"n": 6814, "text": ""}, {"n": 6815, "text": "\t\t/*"}, {"n": 6816, "text": "\t\t * execute and fetch rows only if they will be consumed"}, {"n": 6817, "text": "\t\t * immediately by the sorter"}, {"n": 6818, "text": "\t\t */"}, {"n": 6819, "text": "\t\tif (step->cursor)"}, {"n": 6820, "text": "#ifdef __OPENTENBASE__"}, {"n": 6821, "text": "\t\t{"}, {"n": 6822, "text": "\t\t\t/* we need all rows one time */"}, {"n": 6823, "text": "\t\t\tif (step->dml_on_coordinator)"}, {"n": 6824, "text": "\t\t\t\tfetch = 0;"}, {"n": 6825, "text": "\t\t\telse"}, {"n": 6826, "text": "\t\t\t\tfetch = 1;"}, {"n": 6827, "text": "\t\t}"}, {"n": 6828, "text": "#else"}, {"n": 6829, "text": "\t\t\tfetch = 1;"}, {"n": 6830, "text": "#endif"}, {"n": 6831, "text": "\t\tcombiner->extended_query = true;"}, {"n": 6832, "text": "\t\tif (IsA(combiner->ss.ps.plan, RemoteQuery) &&"}, {"n": 6833, "text": "\t\t\t!combiner->merge_sort && IS_PGXC_COORDINATOR)"}, {"n": 6834, "text": "\t\t{"}, {"n": 6835, "text": "\t\t\tformats = estate->resultFormats;"}, {"n": 6836, "text": "\t\t\tn_formats = estate->nResultFormats;"}, {"n": 6837, "text": "\t\t}"}, {"n": 6838, "text": ""}, {"n": 6839, "text": "\t\tif (pgxc_node_send_query_extended(connection,"}, {"n": 6840, "text": "\t\t\t\t\t\t\tprepared ? NULL : step->sql_statement,"}, {"n": 6841, "text": "\t\t\t\t\t\t\tstep->statement,"}, {"n": 6842, "text": "\t\t\t\t\t\t\tstep->cursor,"}, {"n": 6843, "text": "\t\t\t\t\t\t\tremotestate->rqs_num_params,"}, {"n": 6844, "text": "\t\t\t\t\t\t\tremotestate->rqs_param_types,"}, {"n": 6845, "text": "\t\t\t\t\t\t\tremotestate->paramval_len,"}, {"n": 6846, "text": "\t\t\t\t\t\t\tremotestate->paramval_data,"}, {"n": 6847, "text": "\t\t\t\t\t\t\tremotestate->rqs_param_formats,"}, {"n": 6848, "text": "\t\t\t\t\t\t\tremotestate->rqs_num_params,"}, {"n": 6849, "text": "\t\t\t\t\t\t\tstep->has_row_marks ? true : step->read_only,"}, {"n": 6850, "text": "\t\t\t\t\t\t\tfetch,"}, {"n": 6851, "text": "\t\t\t\t\t\t\tformats,"}, {"n": 6852, "text": "\t\t\t\t\t\t\tn_formats) != 0)"}, {"n": 6853, "text": "\t\t\treturn false;"}, {"n": 6854, "text": "\t}"}, {"n": 6855, "text": "\telse"}, {"n": 6856, "text": "\t{"}, {"n": 6857, "text": "\t\tcombiner->extended_query = false;"}, {"n": 6858, "text": "\t\tif (pgxc_node_send_query(connection, step->sql_statement) != 0)"}, {"n": 6859, "text": "\t\t\treturn false;"}, {"n": 6860, "text": "\t}"}, {"n": 6861, "text": "\treturn true;"}, {"n": 6862, "text": "}"}, {"n": 6863, "text": ""}, {"n": 6864, "text": "/*"}, {"n": 6865, "text": " * Execute utility statement on multiple Datanodes"}, {"n": 6866, "text": " * It does approximately the same as"}, {"n": 6867, "text": " *"}, {"n": 8874, "text": " * Simplified versions of ExecInitRemoteQuery, ExecRemoteQuery and"}, {"n": 8875, "text": " * ExecEndRemoteQuery: in XCP they are only used to execute simple queries."}, {"n": 8876, "text": " *"}, {"n": 8877, "text": " *****************************************************************************/"}, {"n": 8878, "text": "RemoteQueryState *"}, {"n": 8879, "text": "ExecInitRemoteQuery(RemoteQuery *node, EState *estate, int eflags)"}, {"n": 8880, "text": "{"}, {"n": 8881, "text": "\tRemoteQueryState   *remotestate;"}, {"n": 8882, "text": "\tResponseCombiner   *combiner;"}, {"n": 8883, "text": "\tRemoteQueryExecType exec_type = node->exec_type;"}, {"n": 8884, "text": "\tExecDirectType\t\texec_direct_type = node->exec_direct_type;"}, {"n": 8885, "text": "\tbool \t\t\t\texec_direct_dn_allow = node->exec_direct_dn_allow;"}, {"n": 8886, "text": "\tbool\t\t\t\texpr_context_from_estate = false;"}, {"n": 8887, "text": "\tExecNodes          *exec_nodes = node->exec_nodes;"}, {"n": 8888, "text": "\tif (exec_type == EXEC_ON_DATANODES &&"}, {"n": 8889, "text": "\t\texec_direct_dn_allow == false &&"}, {"n": 8890, "text": "\t\texec_direct_type != EXEC_DIRECT_NONE &&"}, {"n": 8891, "text": "\t\texec_direct_type != EXEC_DIRECT_SELECT && !IsInplaceUpgrade)"}, {"n": 8892, "text": "\t{"}, {"n": 8893, "text": "\t\telog(ERROR, \"EXECUTE DIRECT non select command cannot be executed on Datanode\");"}, {"n": 8894, "text": "\t}"}, {"n": 8895, "text": ""}, {"n": 8896, "text": "\tremotestate = makeNode(RemoteQueryState);"}, {"n": 8897, "text": "\tremotestate->eflags = eflags;"}, {"n": 8898, "text": "\tcombiner = &remotestate->combiner;"}, {"n": 8899, "text": "\tcombiner->combine_type = node->combine_type;"}, {"n": 8900, "text": "\tcombiner->context = CurrentMemoryContext;"}, {"n": 8901, "text": "\tcombiner->resowner = CurrentResourceOwner;"}, {"n": 8902, "text": "\tcombiner->ss.ps.plan = (Plan *) node;"}, {"n": 8903, "text": "\tcombiner->ss.ps.state = estate;"}, {"n": 8904, "text": "\tcombiner->ss.ps.ExecProcNode = ExecRemoteQuery;"}, {"n": 8905, "text": "\tcombiner->request_type = REQUEST_TYPE_QUERY;"}, {"n": 8906, "text": ""}, {"n": 8907, "text": "\tif (node->exec_nodes && node->exec_nodes->nExprs > 0 && node->exec_nodes->dis_exprs[0])"}, {"n": 8908, "text": "\t{"}, {"n": 8909, "text": "\t\tExpr *expr = node->exec_nodes->dis_exprs[0];"}, {"n": 8910, "text": ""}, {"n": 8911, "text": "\t\tif (IsA(expr, Var) && ((Var *) expr)->vartype == TIDOID)"}, {"n": 8912, "text": "\t\t{"}, {"n": 8913, "text": "\t\t\t/* Special case if expression does not need to be evaluated */"}, {"n": 8914, "text": "\t\t}"}, {"n": 8915, "text": "\t\telse"}, {"n": 8916, "text": "\t\t{"}, {"n": 8917, "text": "\t\t\t/* prepare expression evaluation */"}, {"n": 8918, "text": "\t\t\tExecAssignExprContext(estate, &combiner->ss.ps);"}, {"n": 8919, "text": "\t\t\texpr_context_from_estate = true;"}, {"n": 8920, "text": "\t\t}"}, {"n": 8921, "text": "\t}"}, {"n": 8922, "text": ""}, {"n": 8923, "text": "\t/* We need expression context to evaluate */"}, {"n": 8924, "text": "\tif (node->exec_nodes && node->exec_nodes->en_param_expr)"}, {"n": 8925, "text": "\t{"}, {"n": 8926, "text": "\t\tMemoryContext old;"}, {"n": 8927, "text": "\t\tint\t\t\t\ti;"}, {"n": 8928, "text": "\t\tint\t\t\t\tparam_idx = 0;"}, {"n": 8929, "text": "\t\tint\t\t\t\ten_param_expr_num = 0;"}, {"n": 8930, "text": ""}, {"n": 8931, "text": "\t\tAssert(estate->es_query_cxt);"}, {"n": 8932, "text": ""}, {"n": 8933, "text": "\t\ten_param_expr_num = GetValidEnParamExprNum(node->exec_nodes);"}, {"n": 8934, "text": ""}, {"n": 8935, "text": "\t\tif (estate->es_param_list_info == NULL)"}, {"n": 8936, "text": "\t\t{"}, {"n": 8937, "text": "\t\t\told = MemoryContextSwitchTo(estate->es_query_cxt);"}, {"n": 8938, "text": "\t\t\testate->es_param_list_info ="}, {"n": 8939, "text": "\t\t\t\t(ParamListInfo) palloc0(offsetof(ParamListInfoData, params) +"}, {"n": 8940, "text": "\t\t\t\t                        en_param_expr_num * sizeof(ParamExternData));"}, {"n": 8941, "text": "\t\t\tMemoryContextSwitchTo(old);"}, {"n": 8942, "text": "\t\t\testate->es_param_list_info->numParams = en_param_expr_num;"}, {"n": 8943, "text": "\t\t}"}, {"n": 8944, "text": "\t\telse"}, {"n": 8945, "text": "\t\t{"}, {"n": 8946, "text": "\t\t\tparam_idx = estate->es_param_list_info->numParams;"}, {"n": 8947, "text": "\t\t\testate->es_param_list_info->numParams += en_param_expr_num;"}, {"n": 8948, "text": "\t\t\told = MemoryContextSwitchTo(estate->es_query_cxt);"}, {"n": 8949, "text": "\t\t\testate->es_param_list_info = repalloc(estate->es_param_list_info,"}, {"n": 8950, "text": "\t\t\t                                      offsetof(ParamListInfoData, params) +"}, {"n": 8951, "text": "\t\t\t                                      estate->es_param_list_info->numParams *"}, {"n": 8952, "text": "\t\t\t                                      sizeof(ParamExternData));"}, {"n": 8953, "text": "\t\t\tMemoryContextSwitchTo(old);"}, {"n": 8954, "text": "\t\t}"}, {"n": 8955, "text": ""}, {"n": 8956, "text": "\t\tif (expr_context_from_estate)"}, {"n": 8957, "text": "\t\t\tcombiner->ss.ps.ps_ExprContext->ecxt_param_list_info = estate->es_param_list_info;"}, {"n": 8958, "text": ""}, {"n": 8959, "text": "\t\tfor (i = 0; i < node->exec_nodes->nExprs; i++)"}, {"n": 8960, "text": "\t\t{"}, {"n": 8961, "text": "\t\t\tParamExternData data;"}, {"n": 8962, "text": "\t\t\tExpr        *expr;"}, {"n": 8963, "text": "\t\t\tOid          type;"}, {"n": 8964, "text": ""}, {"n": 8965, "text": "\t\t\tif (!node->exec_nodes->en_param_expr[i])"}, {"n": 8966, "text": "\t\t\t\tcontinue;"}, {"n": 8967, "text": ""}, {"n": 8968, "text": "\t\t\t/*"}, {"n": 8969, "text": "\t\t\t * Simplify constant expressions before evaluating exec_nodes->en_expr."}, {"n": 8970, "text": "\t\t\t * The same work in preprocess_targetlist."}, {"n": 8971, "text": "\t\t\t */"}, {"n": 8972, "text": "\t\t\texpr = (Expr *) eval_const_expressions(NULL,"}, {"n": 8973, "text": "\t\t\t\t\t\t\t\t\t\t\t\t(Node *) exec_nodes->en_param_expr[i]);"}, {"n": 8974, "text": "\t\t\t/* Fill in opfuncid values if missing */"}, {"n": 8975, "text": "\t\t\tfix_opfuncids((Node *) expr);"}, {"n": 8976, "text": "\t\t\ttype = exprType((Node *) expr);"}, {"n": 8977, "text": ""}, {"n": 8978, "text": "\t\t\tif (eflags & EXEC_FLAG_EXPLAIN_ONLY)"}, {"n": 8979, "text": "\t\t\t{"}, {"n": 8980, "text": "\t\t\t\tdata.value = (Datum) 0;"}, {"n": 8981, "text": "\t\t\t\tdata.isnull = true;"}, {"n": 8982, "text": "\t\t\t}"}, {"n": 8983, "text": "\t\t\telse"}, {"n": 8984, "text": "\t\t\t{"}, {"n": 8985, "text": "\t\t\t\tExprState *exprState = ExecInitExpr(expr, NULL);"}, {"n": 8986, "text": "\t\t\t\tdata.value = ExecEvalExpr(exprState,"}, {"n": 8987, "text": "\t\t\t\t\t\t\t\t\t\tcombiner->ss.ps.ps_ExprContext,"}, {"n": 8988, "text": "\t\t\t\t\t\t\t\t\t\t&data.isnull);"}, {"n": 8989, "text": "\t\t\t}"}, {"n": 8990, "text": "\t\t\tdata.ptype = type;"}, {"n": 8991, "text": "\t\t\tdata.pflags = PARAM_FLAG_CONST;"}, {"n": 8992, "text": "\t\t\testate->es_param_list_info->params[param_idx++] = data;"}, {"n": 8993, "text": "\t\t}"}, {"n": 8994, "text": "\t}"}, {"n": 8995, "text": ""}, {"n": 8996, "text": "\tif (!(remotestate->eflags & (EXEC_FLAG_WITH_DESC | EXEC_FLAG_EXPLAIN_ONLY)) &&"}, {"n": 8997, "text": "\t\t\t!combiner->merge_sort && estate->cn_penetrate_tupleDesc)"}, {"n": 8998, "text": "\t{"}, {"n": 8999, "text": "\t\tcombiner->ss.ps.state->cn_penetrate_tuple = true;"}, {"n": 9000, "text": "\t\t/*"}, {"n": 9001, "text": "\t\t * when there has a tupleDesc from CachedPlanSource, and cn can only"}, {"n": 9002, "text": "\t\t * transparently transmits tuples, just copy the tupleDesc as the ResultTupleDesc"}, {"n": 9003, "text": "\t\t */"}, {"n": 9004, "text": "\t\tcombiner->ss.ps.ps_ResultTupleDesc = CreateTupleDescCopy(estate->cn_penetrate_tupleDesc);"}, {"n": 9005, "text": "\t\tExecInitResultSlot(&combiner->ss.ps);"}, {"n": 9006, "text": "\t}"}, {"n": 9007, "text": "\t/* Use tuple desc from dn if EXEC_FLAG_WITH_DESC */"}, {"n": 9008, "text": "\telse if (eflags & EXEC_FLAG_WITH_DESC)"}, {"n": 9009, "text": "\t\tExecInitResultSlot(&combiner->ss.ps);"}, {"n": 9010, "text": "\telse"}, {"n": 9011, "text": "\t\tExecInitResultTupleSlotTL(&combiner->ss.ps);"}, {"n": 9012, "text": ""}, {"n": 9013, "text": "\t/*"}, {"n": 9014, "text": "\t * If there are parameters supplied, get them into a form to be sent to the"}, {"n": 9015, "text": "\t * Datanodes with bind message. We should not have had done this before."}, {"n": 9016, "text": "\t */"}, {"n": 9017, "text": "\tSetDataRowForExtParams(estate->es_param_list_info, remotestate);"}, {"n": 9018, "text": ""}, {"n": 9019, "text": "\treturn remotestate;"}, {"n": 9020, "text": "}"}, {"n": 9021, "text": ""}, {"n": 9022, "text": "/*"}, {"n": 9028, "text": " * If there is a tuple it is returned, otherwise returned NULL. The NULL result"}, {"n": 9029, "text": " * from the function indicates completed step."}, {"n": 9030, "text": " * The function returns at most one tuple per invocation."}, {"n": 9031, "text": " */"}, {"n": 9032, "text": "TupleTableSlot *"}, {"n": 9033, "text": "ExecRemoteQuery(PlanState *pstate)"}, {"n": 9034, "text": "{"}, {"n": 9035, "text": "\tRemoteQueryState *node = castNode(RemoteQueryState, pstate);"}, {"n": 9036, "text": "\tResponseCombiner *combiner = (ResponseCombiner *) node;"}, {"n": 9037, "text": "\tRemoteQuery    *step = (RemoteQuery *) combiner->ss.ps.plan;"}, {"n": 9038, "text": "\tTupleTableSlot *resultslot = combiner->ss.ps.ps_ResultTupleSlot;"}, {"n": 9039, "text": "\tbool\t\t\tneed_free_in_combiner = false;"}, {"n": 9040, "text": ""}, {"n": 9041, "text": "\tif (!node->query_Done)"}, {"n": 9042, "text": "\t{"}, {"n": 9043, "text": "\t\tGlobalTransactionId gxid = InvalidGlobalTransactionId;"}, {"n": 9044, "text": "\t\tSnapshot\t\tsnapshot = GetActiveSnapshot();"}, {"n": 9045, "text": "\t\tPGXCNodeHandle **connections = NULL;"}, {"n": 9046, "text": "\t\tbool\t\t   *prepared;"}, {"n": 9047, "text": "\t\tint\t\t\t\ti;"}, {"n": 9048, "text": "\t\tint\t\t\t\tregular_conn_count = 0;"}, {"n": 9049, "text": "\t\tint\t\t\t\ttotal_conn_count = 0;"}, {"n": 9050, "text": "\t\tbool\t\t\tneed_tran_block;"}, {"n": 9051, "text": "\t\tPGXCNodeAllHandles *pgxc_connections = NULL;"}, {"n": 9052, "text": "\t\tDatanodeStatement *entry = NULL;"}, {"n": 9053, "text": "\t\tExecNodes *nodes = step->exec_nodes;"}, {"n": 9054, "text": ""}, {"n": 9055, "text": "\t\tprepared = palloc0(sizeof(bool) * NumDataNodes);"}, {"n": 9056, "text": ""}, {"n": 9057, "text": "\t\t/* if prepared statement is referenced see if it is already exist */"}, {"n": 9058, "text": "\t\tif (step->statement && step->exec_nodes)"}, {"n": 9059, "text": "\t\t{"}, {"n": 9060, "text": "\t\t\tentry = FetchDatanodeStatement(step->statement, true);"}, {"n": 9061, "text": ""}, {"n": 9062, "text": "\t\t\tif (entry != NULL && entry->number_of_nodes > 0)"}, {"n": 9063, "text": "\t\t\t{"}, {"n": 9064, "text": "\t\t\t\tif (nodes->nExprs > 0 && nodes->dis_exprs[0])"}, {"n": 9065, "text": "\t\t\t\t{"}, {"n": 9066, "text": "\t\t\t\t\t/*"}, {"n": 9067, "text": "\t\t\t\t\t * The execnodes of this Query need to be redistributed based on the"}, {"n": 9068, "text": "\t\t\t\t\t * expression, and the new parameters may result in new redistribution"}, {"n": 9069, "text": "\t\t\t\t\t * results. Therefore, Attempt to obtain the connections corresponding"}, {"n": 9070, "text": "\t\t\t\t\t * to the nodelist."}, {"n": 9071, "text": "\t\t\t\t\t *"}, {"n": 9072, "text": "\t\t\t\t\t * Notice a valid dis_exprs means this is a generic plan and we need"}, {"n": 9073, "text": "\t\t\t\t\t * to evaluate nodelist with params now. (custom plan has done this"}, {"n": 9074, "text": "\t\t\t\t\t * during planning a FQS)."}, {"n": 9075, "text": "\t\t\t\t\t */"}, {"n": 9076, "text": "\t\t\t\t\tnodes = paramGetExecNodes(nodes, pstate);"}, {"n": 9077, "text": "\t\t\t\t}"}, {"n": 9078, "text": "\t\t\t\telse"}, {"n": 9079, "text": "\t\t\t\t{"}, {"n": 9080, "text": "\t\t\t\t\tnodes = copyObject(nodes);"}, {"n": 9081, "text": "\t\t\t\t}"}, {"n": 9082, "text": ""}, {"n": 9083, "text": "\t\t\t\tpgxc_connections = DatanodeStatementGetHandle(entry, &nodes->nodeList);"}, {"n": 9084, "text": "\t\t\t\tif (pgxc_connections != NULL)"}, {"n": 9085, "text": "\t\t\t\t{"}, {"n": 9086, "text": "\t\t\t\t\t/* determine if this connection can be read only */"}, {"n": 9087, "text": "\t\t\t\t\tbool write = nodes->accesstype != RELATION_ACCESS_READ_FQS &&"}, {"n": 9088, "text": "\t\t\t\t\t\t\t\t !step->read_only;"}, {"n": 9089, "text": ""}, {"n": 9090, "text": "\t\t\t\t\tmemset(prepared, 1, sizeof(bool) * pgxc_connections->dn_conn_count);"}, {"n": 9091, "text": "\t\t\t\t\tregister_transaction_handles_all(pgxc_connections, !write);"}, {"n": 9092, "text": "\t\t\t\t}"}, {"n": 9093, "text": "\t\t\t}"}, {"n": 9094, "text": "\t\t}"}, {"n": 9095, "text": ""}, {"n": 9096, "text": "\t\tif (pgxc_connections == NULL || list_length(nodes->nodeList) > 0)"}, {"n": 9097, "text": "\t\t{"}, {"n": 9098, "text": "\t\t\tPGXCNodeAllHandles *diff;"}, {"n": 9099, "text": "\t\t\t/*"}, {"n": 9100, "text": "\t\t\t * Get connections for Datanodes only, utilities and DDLs"}, {"n": 9101, "text": "\t\t\t * are launched in ExecRemoteUtility"}, {"n": 9102, "text": "\t\t\t */"}, {"n": 9103, "text": "\t\t\tdiff = get_exec_connections(node, nodes, step->exec_type, true);"}, {"n": 9104, "text": "\t\t\tif (entry != NULL && diff->dn_conn_count > 0)"}, {"n": 9105, "text": "\t\t\t{"}, {"n": 9106, "text": "\t\t\t\t/* a new statement needs prepare, save related connections */"}, {"n": 9107, "text": "\t\t\t\tDatanodeStatementStoreHandle(entry, diff);"}, {"n": 9108, "text": "\t\t\t}"}, {"n": 9109, "text": ""}, {"n": 9110, "text": "\t\t\tif (pgxc_connections == NULL)"}, {"n": 9111, "text": "\t\t\t{"}, {"n": 9112, "text": "\t\t\t\tpgxc_connections = diff;"}, {"n": 9113, "text": "\t\t\t}"}, {"n": 9114, "text": "\t\t\telse"}, {"n": 9115, "text": "\t\t\t{"}, {"n": 9116, "text": "\t\t\t\tpgxc_connections->datanode_handles ="}, {"n": 9117, "text": "\t\t\t\t\trepalloc(pgxc_connections->datanode_handles,"}, {"n": 9118, "text": "\t\t\t\t\t\t\t sizeof(PGXCNodeHandle *) *"}, {"n": 9119, "text": "\t\t\t\t\t\t\t (pgxc_connections->dn_conn_count + diff->dn_conn_count));"}, {"n": 9120, "text": ""}, {"n": 9121, "text": "\t\t\t\tfor (i = 0; i < diff->dn_conn_count; i++)"}, {"n": 9122, "text": "\t\t\t\t{"}, {"n": 9123, "text": "\t\t\t\t\tpgxc_connections->datanode_handles[pgxc_connections->dn_conn_count++] ="}, {"n": 9124, "text": "\t\t\t\t\t\tdiff->datanode_handles[i];"}, {"n": 9125, "text": "\t\t\t\t}"}, {"n": 9126, "text": "\t\t\t}"}, {"n": 9127, "text": "\t\t}"}, {"n": 9128, "text": ""}, {"n": 9129, "text": "\t\tif (step->exec_type == EXEC_ON_DATANODES)"}, {"n": 9130, "text": "\t\t{"}, {"n": 9131, "text": "\t\t\tconnections = pgxc_connections->datanode_handles;"}, {"n": 9132, "text": "\t\t\ttotal_conn_count = regular_conn_count = pgxc_connections->dn_conn_count;"}, {"n": 9133, "text": "\t\t}"}, {"n": 9134, "text": "\t\telse if (step->exec_type == EXEC_ON_COORDS)"}, {"n": 9135, "text": "\t\t{"}, {"n": 9136, "text": "\t\t\tconnections = pgxc_connections->coord_handles;"}, {"n": 9137, "text": "\t\t\ttotal_conn_count = regular_conn_count = pgxc_connections->co_conn_count;"}, {"n": 9138, "text": "\t\t}"}, {"n": 9139, "text": "\t\telse if (step->exec_type == EXEC_ON_ALL_NODES || step->exec_type == EXEC_ON_CURRENT_TXN)"}, {"n": 9140, "text": "\t\t{"}, {"n": 9141, "text": "\t\t\ttotal_conn_count = regular_conn_count ="}, {"n": 9142, "text": "\t\t\t\tpgxc_connections->dn_conn_count + pgxc_connections->co_conn_count;"}, {"n": 9143, "text": ""}, {"n": 9144, "text": "\t\t\tconnections = palloc(mul_size(total_conn_count, sizeof(PGXCNodeHandle *)));"}, {"n": 9145, "text": "\t\t\tmemcpy(connections, pgxc_connections->datanode_handles,"}, {"n": 9146, "text": "\t\t\t\t   pgxc_connections->dn_conn_count * sizeof(PGXCNodeHandle *));"}, {"n": 9147, "text": "\t\t\tmemcpy(connections + pgxc_connections->dn_conn_count, pgxc_connections->coord_handles,"}, {"n": 9148, "text": "\t\t\t\t   pgxc_connections->co_conn_count * sizeof(PGXCNodeHandle *));"}, {"n": 9149, "text": ""}, {"n": 9150, "text": "\t\t\tneed_free_in_combiner = true;"}, {"n": 9151, "text": "\t\t}"}, {"n": 9152, "text": ""}, {"n": 9153, "text": "#ifdef __OPENTENBASE__"}, {"n": 9154, "text": "\t\t/* initialize */"}, {"n": 9155, "text": "\t\tcombiner->recv_node_count = regular_conn_count;"}, {"n": 9156, "text": "\t\tcombiner->recv_tuples\t  = 0;"}, {"n": 9157, "text": "\t\tcombiner->recv_total_time = -1;"}, {"n": 9158, "text": "\t\tcombiner->recv_datarows = 0;"}, {"n": 9159, "text": "#endif"}, {"n": 9160, "text": "\t\tcombiner->node_count = regular_conn_count;"}, {"n": 9161, "text": ""}, {"n": 9162, "text": "\t\t/*"}, {"n": 9163, "text": "\t\t * Start transaction on data nodes if we are in explicit transaction"}, {"n": 9164, "text": "\t\t * or going to use extended query protocol or write to multiple nodes"}, {"n": 9165, "text": "\t\t *"}, {"n": 9166, "text": "\t\t * for mult_sql_query_containing, the special syntax '\\;' connects two SQL statements"}, {"n": 9167, "text": "\t\t * that need to be executed within the same transaction block."}, {"n": 9168, "text": "\t\t * Here, we are actively starting a new transaction."}, {"n": 9169, "text": "\t\t */"}, {"n": 9170, "text": "\t\tif (step->force_autocommit)"}, {"n": 9171, "text": "\t\t\tneed_tran_block = false;"}, {"n": 9172, "text": "\t\telse"}, {"n": 9173, "text": "\t\t\tneed_tran_block = step->cursor ||"}, {"n": 9174, "text": "\t\t\t\t\t(!step->read_only && total_conn_count > 1) ||"}, {"n": 9175, "text": "\t\t\t\t\texec_event_trigger_stmt ||"}, {"n": 9176, "text": "\t\t\t\t\t(TransactionBlockStatusCode() == 'T' ) ||"}, {"n": 9177, "text": "\t\t\t\t\t(step->remote_mt && step->remote_mt->global_index) ||"}, {"n": 9178, "text": "\t\t\t\t\tmult_sql_query_containing;"}, {"n": 9179, "text": ""}, {"n": 9180, "text": "\t\tstat_statement();"}, {"n": 9181, "text": "\t\tstat_transaction(total_conn_count);"}, {"n": 9182, "text": "\t\tgxid = GetCurrentTransactionIdIfAny();"}, {"n": 9183, "text": "#ifdef __OPENTENBASE__"}, {"n": 9184, "text": "\t\tif (regular_conn_count > 0)"}, {"n": 9185, "text": "\t\t{"}, {"n": 9186, "text": "\t\t\tcombiner->connections = connections;"}, {"n": 9187, "text": "\t\t\tcombiner->conn_count = regular_conn_count;"}, {"n": 9188, "text": "\t\t\tcombiner->current_conn = 0;"}, {"n": 9189, "text": "\t\t}"}, {"n": 9190, "text": "#endif"}, {"n": 9191, "text": ""}, {"n": 9192, "text": "\t\tif (pgxc_node_begin(regular_conn_count, connections, gxid, need_tran_block, true))"}, {"n": 9193, "text": "\t\t\tereport(ERROR,"}, {"n": 9194, "text": "\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 9195, "text": "\t\t\t\t\t\terrmsg(\"Could not begin transaction on connections.\")));"}, {"n": 9196, "text": ""}, {"n": 9197, "text": "\t\tfor (i = 0; i < regular_conn_count; i++)"}, {"n": 9198, "text": "\t\t{"}, {"n": 9199, "text": "\t\t\t/* If explicit transaction is needed gxid is already sent */"}, {"n": 9200, "text": "\t\t\tif (!pgxc_start_command_on_connection(connections[i], node,"}, {"n": 9201, "text": "\t\t\t\t\t\t\t\t\t\t\t\t  snapshot, prepared[i]))"}, {"n": 9202, "text": "\t\t\t{"}, {"n": 9203, "text": "\t\t\t\tereport(ERROR,"}, {"n": 9204, "text": "\t\t\t\t\t\t(errcode(ERRCODE_CONNECTION_EXCEPTION),"}, {"n": 9205, "text": "\t\t\t\t\t\t\t\terrmsg(\"Failed to send command\"),"}, {"n": 9206, "text": "\t\t\t\t\t\t\t\terrnode(connections[i])));"}, {"n": 9207, "text": "\t\t\t}"}, {"n": 9208, "text": "\t\t\tconnections[i]->combiner = combiner;"}, {"n": 9209, "text": "\t\t}"}, {"n": 9210, "text": ""}, {"n": 9211, "text": "\t\tif (step->cursor)"}, {"n": 9212, "text": "\t\t{"}, {"n": 9213, "text": "\t\t\tcombiner->cursor = step->cursor;"}, {"n": 9214, "text": "\t\t\tcombiner->cursor_count = regular_conn_count;"}, {"n": 9215, "text": "\t\t\tcombiner->cursor_connections = (PGXCNodeHandle **) palloc(regular_conn_count * sizeof(PGXCNodeHandle *));"}, {"n": 9216, "text": "\t\t\tmemcpy(combiner->cursor_connections, connections, regular_conn_count * sizeof(PGXCNodeHandle *));"}, {"n": 9217, "text": "\t\t}"}, {"n": 9218, "text": ""}, {"n": 9219, "text": "\t\tcombiner->connections = connections;"}, {"n": 9220, "text": "\t\tcombiner->conn_count = regular_conn_count;"}, {"n": 9221, "text": "\t\tcombiner->current_conn = 0;"}, {"n": 9222, "text": ""}, {"n": 9223, "text": "\t\tif (combiner->cursor_count)"}, {"n": 9224, "text": "\t\t{"}, {"n": 9225, "text": "\t\t\tcombiner->conn_count = combiner->cursor_count;"}, {"n": 9226, "text": "\t\t\tmemcpy(connections, combiner->cursor_connections,"}, {"n": 9227, "text": "\t\t\t\t   combiner->cursor_count * sizeof(PGXCNodeHandle *));"}, {"n": 9228, "text": "\t\t\tcombiner->connections = connections;"}, {"n": 9229, "text": "\t\t}"}, {"n": 9230, "text": ""}, {"n": 9231, "text": "\t\tnode->query_Done = true;"}, {"n": 9232, "text": ""}, {"n": 9233, "text": "\t\tif (step->sort)"}, {"n": 9234, "text": "\t\t{"}, {"n": 9235, "text": "\t\t\tSimpleSort *sort = step->sort;"}, {"n": 9236, "text": ""}, {"n": 9237, "text": "\t\t\t/*"}, {"n": 9238, "text": "\t\t\t * First message is already in the buffer"}, {"n": 9239, "text": "\t\t\t * Further fetch will be under tuplesort control"}, {"n": 9240, "text": "\t\t\t * If query does not produce rows tuplesort will not"}, {"n": 9241, "text": "\t\t\t * be initialized"}, {"n": 9242, "text": "\t\t\t */"}, {"n": 9243, "text": "\t\t\tcombiner->tuplesortstate = tuplesort_begin_merge("}, {"n": 9244, "text": "\t\t\t\t\t\t\t\t   resultslot->tts_tupleDescriptor,"}, {"n": 9245, "text": "\t\t\t\t\t\t\t\t   sort->numCols,"}, {"n": 9246, "text": "\t\t\t\t\t\t\t\t   sort->sortColIdx,"}, {"n": 9247, "text": "\t\t\t\t\t\t\t\t   sort->sortOperators,"}, {"n": 9248, "text": "\t\t\t\t\t\t\t\t   sort->sortCollations,"}, {"n": 9249, "text": "\t\t\t\t\t\t\t\t   sort->nullsFirst,"}, {"n": 9250, "text": "\t\t\t\t\t\t\t\t   combiner,"}, {"n": 9251, "text": "\t\t\t\t\t\t\t\t   work_mem);"}, {"n": 9252, "text": "\t\t}"}, {"n": 9253, "text": "\t}"}, {"n": 9254, "text": ""}, {"n": 9255, "text": "\tif (combiner->tuplesortstate)"}, {"n": 9256, "text": "\t{"}, {"n": 9257, "text": "\t\tif (tuplesort_gettupleslot((Tuplesortstate *) combiner->tuplesortstate,"}, {"n": 9258, "text": "\t\t\t\t\t\t\t\t\t  true, true, resultslot, NULL))"}, {"n": 9259, "text": "\t\t\treturn resultslot;"}, {"n": 9260, "text": "\t\telse"}, {"n": 9261, "text": "\t\t\tExecClearTuple(resultslot);"}, {"n": 9262, "text": "\t}"}, {"n": 9263, "text": "\telse"}, {"n": 9264, "text": "\t{"}, {"n": 9265, "text": "\t\tTupleTableSlot *slot = FetchTuple(combiner);"}, {"n": 9266, "text": "\t\tif (!TupIsNull(slot))"}, {"n": 9267, "text": "\t\t\treturn slot;"}, {"n": 9268, "text": "\t}"}, {"n": 9269, "text": ""}, {"n": 9270, "text": "\tif (combiner->errorMessage)"}, {"n": 9271, "text": "\t\tpgxc_node_report_error(combiner);"}, {"n": 9272, "text": ""}, {"n": 9273, "text": "\tif (need_free_in_combiner)"}, {"n": 9274, "text": "\t\tpfree(combiner->connections);"}, {"n": 9275, "text": ""}, {"n": 9276, "text": "\treturn NULL;"}, {"n": 9277, "text": "}"}, {"n": 9278, "text": ""}, {"n": 9279, "text": "/* ----------------------------------------------------------------"}]}, "wire": {"path": "src/backend/pgxc/pool/pgxcnode.c", "sha256": "ba493602c45ddcceb6526eb392c400cb3be41d80c4b215c40ab6cf9d6ae6466f", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/backend/pgxc/pool/pgxcnode.c", "lines": [{"n": 3203, "text": ""}, {"n": 3204, "text": "/*"}, {"n": 3205, "text": " * Send specified statement down to the PGXC node"}, {"n": 3206, "text": " */"}, {"n": 3207, "text": "static int"}, {"n": 3208, "text": "pgxc_node_send_query_internal(PGXCNodeHandle * handle, const char *query,"}, {"n": 3209, "text": "\t\tbool rollback)"}, {"n": 3210, "text": "{"}, {"n": 3211, "text": "\tint\t\t\tstrLen;"}, {"n": 3212, "text": "\tint\t\t\tmsgLen;"}, {"n": 3213, "text": ""}, {"n": 3214, "text": "\tif (pgxc_node_send_cmd_seq(handle))"}, {"n": 3215, "text": "\t\treturn EOF;"}, {"n": 3216, "text": ""}, {"n": 3217, "text": "\t/*"}, {"n": 3218, "text": "\t * Its appropriate to send ROLLBACK commands on a failed connection, but"}, {"n": 3219, "text": "\t * for everything else we expect the connection to be in a sane state"}, {"n": 3220, "text": "\t */"}, {"n": 3221, "text": "\tif (enable_distri_print)"}, {"n": 3222, "text": "\t\telog(LOG, \"pgxc_node_send_query - handle->nodename=%s, handle->sock=%d, \""}, {"n": 3223, "text": "\t\t\t\t\t \"handle->read_only=%d, handle->transaction_status=%c, handle->state %d, node %s %d, query: %s\","}, {"n": 3224, "text": "\t\t\t handle->nodename, handle->sock, handle->read_only, GetTxnState(handle),"}, {"n": 3225, "text": "\t\t\t GetConnectionState(handle), handle->nodename, handle->backend_pid, query);"}, {"n": 3226, "text": ""}, {"n": 3227, "text": "\tstrLen = strlen(query) + 1;"}, {"n": 3228, "text": "\t/* size + strlen */"}, {"n": 3229, "text": "\tmsgLen = 4 + strLen;"}, {"n": 3230, "text": ""}, {"n": 3231, "text": "\t/* msgType + msgLen */"}, {"n": 3232, "text": "\tif (ensure_out_buffer_capacity(handle->outEnd + 1 + msgLen, handle) != 0)"}, {"n": 3233, "text": "\t{"}, {"n": 3234, "text": "\t\tadd_error_message(handle, \"out of memory\");"}, {"n": 3235, "text": "\t\treturn EOF;"}, {"n": 3236, "text": "\t}"}, {"n": 3237, "text": ""}, {"n": 3238, "text": "\thandle->outBuffer[handle->outEnd++] = 'Q';"}, {"n": 3239, "text": "\tmsgLen = pg_hton32(msgLen);"}, {"n": 3240, "text": "\tmemcpy(handle->outBuffer + handle->outEnd, &msgLen, 4);"}, {"n": 3241, "text": "\thandle->outEnd += 4;"}, {"n": 3242, "text": "\tmemcpy(handle->outBuffer + handle->outEnd, query, strLen);"}, {"n": 3243, "text": "\thandle->outEnd += strLen;"}, {"n": 3244, "text": ""}, {"n": 3245, "text": "\tSetTransitionInExtendedQuery(handle, false);"}, {"n": 3246, "text": "\tRecordSendMessage(handle, 'Q', query, strlen(query));"}, {"n": 3247, "text": "\treturn SendRequest(handle);"}, {"n": 3248, "text": "}"}, {"n": 3249, "text": ""}, {"n": 3250, "text": "int"}, {"n": 3264, "text": "\t\treturn ret;"}, {"n": 3265, "text": "\treturn pgxc_node_send_query_internal(handle, query, true);"}, {"n": 3266, "text": "}"}, {"n": 3267, "text": ""}, {"n": 3268, "text": "int"}, {"n": 3269, "text": "pgxc_node_send_query(PGXCNodeHandle *handle, const char *query)"}, {"n": 3270, "text": "{"}, {"n": 3271, "text": "#ifdef __TWO_PHASE_TESTS__"}, {"n": 3272, "text": "\tif ((IN_REMOTE_PREPARE == twophase_in && !handle->read_only) ||"}, {"n": 3273, "text": "        IN_PREPARE_ERROR == twophase_in ||"}, {"n": 3274, "text": "        IN_REMOTE_FINISH == twophase_in ||"}, {"n": 3275, "text": "        IN_PG_CLEAN == twophase_in)"}, {"n": 3276, "text": "    {"}, {"n": 3277, "text": "        capacity_stack = SEND_QUERY;"}, {"n": 3278, "text": "    }"}, {"n": 3279, "text": "#endif"}, {"n": 3280, "text": "\treturn pgxc_node_send_query_internal(handle, query, false);"}, {"n": 3281, "text": "}"}, {"n": 3282, "text": ""}, {"n": 3283, "text": "/*"}, {"n": 3284, "text": " * Send opentenbase internal command to the remote with an internal flag,"}, {"n": 3285, "text": " * this is introduced to optimize pg_stat_statements performance"}, {"n": 3286, "text": " */"}, {"n": 3287, "text": "int"}, {"n": 3288, "text": "pgxc_node_send_query_with_internal_flag(PGXCNodeHandle *handle, const char *query)"}, {"n": 3289, "text": "{"}]}, "dispatch": {"path": "src/backend/executor/execProcnode.c", "sha256": "6a4b462eb8ecc23a19e97b20253193283003bac5e6456abc7f157ed59889658b", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/backend/executor/execProcnode.c", "lines": [{"n": 390, "text": "\t\t\t\t\t\t\t\t\t\t\t\t estate, eflags);"}, {"n": 391, "text": "\t\t\tbreak;"}, {"n": 392, "text": ""}, {"n": 393, "text": "#ifdef PGXC"}, {"n": 394, "text": "\t\tcase T_RemoteQuery:"}, {"n": 395, "text": "\t\t\tresult = (PlanState *) ExecInitRemoteQuery((RemoteQuery *) node,"}, {"n": 396, "text": "\t\t\t\t\t\t\t\t\t\t\t\t\t    estate, eflags);"}, {"n": 397, "text": "\t\t\tbreak;"}, {"n": 398, "text": "#endif"}, {"n": 399, "text": ""}, {"n": 400, "text": "#ifdef XCP"}, {"n": 401, "text": "\t\tcase T_RemoteSubplan:"}, {"n": 402, "text": "\t\t\tresult = (PlanState *) ExecInitRemoteFragment((RemoteSubplan *) node,"}, {"n": 403, "text": "\t\t\t\t\t\t\t\t\t\t\t\t\t\t  estate, eflags);"}, {"n": 404, "text": "\t\t\tbreak;"}]}, "state": {"path": "src/include/pgxc/execRemote.h", "sha256": "0892dd00c1d42f15ddbba3d2f2c6f4e2b523ab30e0168d1fd57869e429ac0db7", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/include/pgxc/execRemote.h", "lines": [{"n": 110, "text": "\tstruct epoll_event *events;"}, {"n": 111, "text": "\tint \t\t   efd;"}, {"n": 112, "text": "\tbool          external_fd;"}, {"n": 113, "text": ""}, {"n": 114, "text": "\tvoid         *libpq;"}, {"n": 115, "text": "} RemoteFragmentController;"}, {"n": 116, "text": ""}, {"n": 117, "text": "/*"}, {"n": 118, "text": " * Common part for all plan state nodes needed to access remote datanodes"}, {"n": 119, "text": " * ResponseCombiner must be the first field of the plan state node so we can"}, {"n": 120, "text": " * typecast"}, {"n": 121, "text": " */"}, {"n": 122, "text": "typedef struct ResponseCombiner"}, {"n": 123, "text": "{"}, {"n": 124, "text": "\tScanState\tss;\t\t\t\t\t\t/* its first field is NodeTag */"}, {"n": 125, "text": "\tint\t\t\tnode_count;\t\t\t\t/* total count of participating nodes */"}, {"n": 126, "text": "\tPGXCNodeHandle **connections;\t\t/* Datanode connections being combined */"}, {"n": 127, "text": "\tint\t\t\tconn_count;\t\t\t\t/* count of active connections */"}, {"n": 128, "text": "\tint\t\t\tcurrent_conn;\t\t\t/* used to balance load when reading from connections */"}, {"n": 129, "text": "\tlong\t\tcurrent_conn_rows_consumed;"}, {"n": 130, "text": "\tCombineType combine_type;\t\t\t/* see CombineType enum */"}, {"n": 131, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 132, "text": "\tbool        DML_replicated_return;  /* DML on replication table returned */"}, {"n": 133, "text": "\tbool        handle_ftable_resp;  \t/* when true, means call by HandleFtableResponse */"}, {"n": 134, "text": "#endif"}, {"n": 135, "text": "\tint\t\t\tcommand_complete_count; /* count of received CommandComplete messages */"}, {"n": 136, "text": "\tRequestType request_type;\t\t\t/* see RequestType enum */"}, {"n": 137, "text": "\tTupleDesc\ttuple_desc;\t\t\t\t/* tuple descriptor to be referenced by emitted tuples */"}, {"n": 138, "text": "\tint\t\t\tdescription_count;\t\t/* count of received RowDescription messages */"}, {"n": 139, "text": "\tint\t\t\tcopy_in_count;\t\t\t/* count of received CopyIn messages */"}, {"n": 140, "text": "\tint\t\t\tcopy_out_count;\t\t\t/* count of received CopyOut messages */"}, {"n": 141, "text": "\tFILE\t   *copy_file;      \t\t/* used if copy_dest == COPY_FILE */"}, {"n": 142, "text": "\tuint64\t\tprocessed;\t\t\t\t/* count of data rows handled */"}, {"n": 143, "text": "\tchar\t\terrorCode[5];\t\t\t/* error code to send back to client */"}, {"n": 144, "text": "\tchar\t   *errorMessage;\t\t\t/* error message to send back to client */"}, {"n": 145, "text": "\tchar\t   *errorDetail;\t\t\t/* error detail to send back to client */"}, {"n": 146, "text": "\tchar\t   *errorHint;\t\t\t\t/* error hint to send back to client */"}, {"n": 147, "text": "\tOid\t\t\treturning_node;\t\t\t/* returning replicated node */"}, {"n": 148, "text": "\tRemoteDataRow currentRow;\t\t\t/* next data ro to be wrapped into a tuple */"}, {"n": 149, "text": "\t/* TODO use a tuplestore as a rowbuffer */"}, {"n": 150, "text": "\tList \t   *rowBuffer;\t\t\t\t/* buffer where rows are stored when connection"}, {"n": 151, "text": "\t\t\t\t\t\t\t\t\t\t * should be cleaned for reuse by other RemoteQuery */"}, {"n": 152, "text": "\t/*"}, {"n": 153, "text": "\t * To handle special case - if there is a simple sort and sort connection"}, {"n": 154, "text": "\t * is buffered. If EOF is reached on a connection it should be removed from"}, {"n": 155, "text": "\t * the array, but we need to know node number of the connection to find"}, {"n": 156, "text": "\t * messages in the buffer. So we store nodenum to that array if reach EOF"}, {"n": 157, "text": "\t * when buffering"}, {"n": 158, "text": "\t */"}, {"n": 159, "text": "\tOid \t   *tapenodes;"}, {"n": 160, "text": "\t/*"}, {"n": 161, "text": "\t * If some tape (connection) is buffered, contains a reference on the cell"}, {"n": 162, "text": "\t * right before first row buffered from this tape, needed to speed up"}, {"n": 163, "text": "\t * access to the data"}, {"n": 164, "text": "\t */"}, {"n": 165, "text": "\tListCell  **tapemarks;"}, {"n": 166, "text": "\t/*"}, {"n": 167, "text": "\t * The node_count may change, record tapemarks count for repalloc"}, {"n": 168, "text": "\t */"}, {"n": 169, "text": "\tint\t\t\ttapemarks_count;"}, {"n": 170, "text": "#ifdef __OPENTENBASE__"}, {"n": 171, "text": "\tList            **prerowBuffers;    /* used for each connection in prefetch with merge_sort,"}, {"n": 172, "text": "\t\t\t\t\t\t\t\t\t\t * put datarows in each rowbuffer in order */"}, {"n": 173, "text": "\tTuplestorestate **dataRowBuffer;    /* used for prefetch */"}, {"n": 174, "text": "\tlong             *dataRowMemSize;   /* size of datarow in memory */"}, {"n": 175, "text": "\tint             *nDataRows;         /* number of datarows in tuplestore */"}, {"n": 176, "text": "\tTupleTableSlot  *tmpslot;           "}, {"n": 177, "text": "\tchar*            errorNode;\t\t    /* node Oid, who raise an error, set when handle_response */"}, {"n": 178, "text": "\tint              backend_pid;\t    /* backend_pid, who raise an error, set when handle_response */"}, {"n": 179, "text": "\tbool             is_abort;"}, {"n": 180, "text": "#endif"}, {"n": 181, "text": "\tbool\t\tignore_datarow;"}, {"n": 182, "text": "\tbool\t\tmerge_sort;             /* perform mergesort of node tuples */"}, {"n": 183, "text": "\tbool\t\textended_query;         /* running extended query protocol */"}, {"n": 184, "text": "\tbool\t\tprobing_primary;\t\t/* trying replicated on primary node */"}, {"n": 185, "text": "\tvoid\t   *tuplesortstate;\t\t\t/* for merge sort */"}, {"n": 186, "text": "\t/* COPY support */"}, {"n": 187, "text": "\tRemoteCopyType remoteCopyType;"}, {"n": 188, "text": "\tTuplestorestate *tuplestorestate;"}, {"n": 189, "text": "\t/* cursor support */"}, {"n": 190, "text": "\tchar\t   *cursor;\t\t\t\t\t/* cursor name */"}, {"n": 191, "text": "\tchar\t   *update_cursor;\t\t\t/* throw this cursor current tuple can be updated */"}, {"n": 192, "text": "\tint\t\t\tcursor_count;\t\t\t/* total count of participating nodes */"}, {"n": 193, "text": "\tPGXCNodeHandle **cursor_connections;/* data node connections being combined */"}, {"n": 194, "text": "#ifdef __OPENTENBASE__"}, {"n": 195, "text": "\t/* statistic information for debug */"}, {"n": 196, "text": "\tint         recv_node_count;       /* number of recv nodes */"}, {"n": 197, "text": "\tuint64      recv_tuples;           /* number of recv tuples */"}, {"n": 198, "text": "\tTimestampTz recv_total_time;       /* total time to recv tuples */"}, {"n": 199, "text": "\t/* used for remoteDML */"}, {"n": 200, "text": "\tint32      DML_processed;         /* count of DML data rows handled on remote nodes */"}, {"n": 201, "text": "\tPGXCNodeHandle **conns;\t\t"}, {"n": 202, "text": "\tint\t\t\t     ccount;\t"}, {"n": 203, "text": "\tuint64     recv_datarows;"}, {"n": 204, "text": "\tItemPointerData simpledml_newctid;"}, {"n": 205, "text": "\tMemoryContext context;\t\t/* memory context for holding tuples */"}, {"n": 206, "text": "    ResourceOwner resowner;\t\t/* resowner for holding temp files */"}, {"n": 207, "text": "#endif"}, {"n": 208, "text": "    bool         waitforC;"}, {"n": 209, "text": "    bool         waitforE;"}, {"n": 210, "text": "\tbool         waitfor2;"}, {"n": 211, "text": ""}, {"n": 212, "text": "\tRemoteFragmentController *controller;"}, {"n": 213, "text": "}\tResponseCombiner;"}, {"n": 214, "text": ""}, {"n": 215, "text": "typedef struct RemoteQueryState"}, {"n": 216, "text": "{"}, {"n": 217, "text": "\tResponseCombiner combiner;\t\t\t/* see ResponseCombiner struct */"}, {"n": 218, "text": "\tbool\t\tquery_Done;\t\t\t\t/* query has been sent down to Datanodes */"}, {"n": 219, "text": ""}, {"n": 220, "text": "\t/* Support for parameters */"}, {"n": 221, "text": "\tchar\t   *paramval_data;\t\t/* parameter data, format is like in BIND */"}, {"n": 222, "text": "\tint\t\t\tparamval_len;\t\t/* length of parameter values data */"}, {"n": 223, "text": "\tOid\t\t   *rqs_param_types;\t/* Types of the remote params */"}, {"n": 224, "text": "\tint\t\t\trqs_num_params;"}, {"n": 225, "text": "\tint16\t   *rqs_param_formats;\t/* a format code for each param */"}, {"n": 226, "text": ""}, {"n": 227, "text": "\tint\t\t\teflags;\t\t\t/* capability flags to pass to tuplestore */"}, {"n": 228, "text": "#ifdef __OPENTENBASE__"}, {"n": 229, "text": "\tParallelWorkerStatus *parallel_status; /*Shared storage for parallel worker .*/"}, {"n": 230, "text": ""}, {"n": 231, "text": "\t/* parameters for insert...on conflict do update */"}, {"n": 232, "text": "\tchar\t   *ss_paramval_data;\t\t"}, {"n": 233, "text": "\tint\t\t\tss_paramval_len;\t\t"}, {"n": 234, "text": "\tOid\t\t   *ss_param_types;"}, {"n": 235, "text": "\tint\t\t\tss_num_params;"}, {"n": 236, "text": ""}, {"n": 237, "text": "    char\t   *su_paramval_data;"}, {"n": 238, "text": "\tint\t\t\tsu_paramval_len;\t\t"}, {"n": 239, "text": "\tOid\t\t   *su_param_types;\t"}, {"n": 240, "text": "\tint\t\t\tsu_num_params;"}, {"n": 241, "text": ""}, {"n": 242, "text": "\tuint32\t\tdml_prepared_mask[WORD_NUMBER_FOR_NODES]; "}, {"n": 243, "text": "#endif"}, {"n": 244, "text": "}\tRemoteQueryState;"}, {"n": 375, "text": "extern void pgxc_node_cleanup_and_release_handles(bool force, bool waitOnResGroup);"}, {"n": 376, "text": "extern void pgxc_sync_connections(PGXCNodeAllHandles *all_handles, bool ignore_invalid);"}, {"n": 377, "text": "extern void pgxc_node_clean_all_handles_distribute_msg(void);"}, {"n": 378, "text": "extern int handle_response_internal(PGXCNodeHandle *conn, ResponseCombiner *combiner, char *file, int line);"}, {"n": 379, "text": "#define handle_response(conn, combiner) \\"}, {"n": 380, "text": "\t\thandle_response_internal(conn, combiner, __FILE__, __LINE__)"}, {"n": 381, "text": "extern int handle_response_on_proxy(PGXCNodeHandle *conn, ResponseCombiner *combiner);"}, {"n": 382, "text": "extern void HandleCmdComplete(CmdType commandType, CombineTag *combine, const char *msg_body,"}]}, "rq": {"path": "src/include/pgxc/planner.h", "sha256": "ed7e0bbe6bf66c79e408a79197bf00299832a4ba734b64455e498a46e8bfda2d", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/include/pgxc/planner.h", "lines": [{"n": 90, "text": "\tFQS_MODE_FQS_PLANER,"}, {"n": 91, "text": "\tFQS_MODE_STD_PLANER"}, {"n": 92, "text": "} FQS_MODE;"}, {"n": 93, "text": ""}, {"n": 94, "text": "extern char* fqs_mode_string[];"}, {"n": 95, "text": "/*"}, {"n": 96, "text": " * Contains instructions on processing a step of a query."}, {"n": 97, "text": " * In the prototype this will be simple, but it will eventually"}, {"n": 98, "text": " * evolve into a GridSQL-style QueryStep."}, {"n": 99, "text": " */"}, {"n": 100, "text": "typedef struct"}, {"n": 101, "text": "{"}, {"n": 102, "text": "\tScan\t\t\tscan;"}, {"n": 103, "text": "\tExecDirectType\t\texec_direct_type;\t/* track if remote query is execute direct and what type it is */"}, {"n": 104, "text": "\tbool\t\t\texec_direct_dn_allow;"}, {"n": 105, "text": "\tchar\t\t\t*sql_statement;"}, {"n": 106, "text": "\tExecNodes\t\t*exec_nodes;\t\t/* List of Datanodes where to launch query */"}, {"n": 107, "text": "\tCombineType\t\tcombine_type;"}, {"n": 108, "text": "\tSimpleSort\t\t*sort;"}, {"n": 109, "text": "\tbool\t\t\tread_only;\t\t/* do not use 2PC when committing read only steps */"}, {"n": 110, "text": "\tbool\t\t\tforce_autocommit;\t/* some commands like VACUUM require autocommit mode */"}, {"n": 111, "text": "\tchar\t\t\t*statement;\t\t/* if specified use it as a PreparedStatement name on Datanodes */"}, {"n": 112, "text": "\tchar\t\t\t*cursor;\t\t/* if specified use it as a Portal name on Datanodes */"}, {"n": 113, "text": "\tint             rq_num_params;      /* number of parameters present in"}, {"n": 114, "text": "\t\t\t\t\t\t\t\t\t\t   remote statement */"}, {"n": 115, "text": "\tOid             *rq_param_types;    /* parameter types for the remote"}, {"n": 116, "text": "\t\t\t\t\t\t\t\t\t\t   statement */"}, {"n": 117, "text": "\tRemoteQueryExecType\texec_type;"}, {"n": 118, "text": "\tint\t\t\treduce_level;\t\t/* in case of reduced JOIN, it's level    */"}, {"n": 119, "text": "\tchar\t\t\t*outer_alias;"}, {"n": 120, "text": "\tchar\t\t\t*inner_alias;"}, {"n": 121, "text": "\tint\t\t\touter_reduce_level;"}, {"n": 122, "text": "\tint\t\t\tinner_reduce_level;"}, {"n": 123, "text": "\tRelids\t\t\touter_relids;"}, {"n": 124, "text": "\tRelids\t\t\tinner_relids;"}, {"n": 125, "text": "\tchar\t\t\t*inner_statement;"}, {"n": 126, "text": "\tchar\t\t\t*outer_statement;"}, {"n": 127, "text": "\tchar\t\t\t*join_condition;"}, {"n": 128, "text": "\tbool\t\t\thas_row_marks;\t\t/* Did SELECT had FOR UPDATE/SHARE? */"}, {"n": 129, "text": "\tbool\t\t\thas_ins_child_sel_parent;\t/* This node is part of an INSERT SELECT that"}, {"n": 130, "text": "\t\t\t\t\t\t\t\t * inserts into child by selecting from its parent */"}, {"n": 131, "text": ""}, {"n": 132, "text": "\tbool            rq_finalise_aggs;   /* Aggregates should be finalised at"}, {"n": 133, "text": "\t\t\t\t\t\t\t\t\t\t   the "}, {"n": 134, "text": "\t\t\t\t\t\t\t\t\t\t * Datanode */"}, {"n": 135, "text": "\tbool            rq_sortgroup_colno; /* Use resno for sort group references"}, {"n": 136, "text": "\t\t\t\t\t\t\t\t\t\t * instead of expressions */"}, {"n": 137, "text": "\tQuery           *remote_query;  /* Query structure representing the query"}, {"n": 138, "text": "\t\t\t\t\t\t\t\t\t   to be"}, {"n": 139, "text": "\t\t\t\t\t\t\t\t\t * sent to the datanodes */"}, {"n": 140, "text": "\tList            *base_tlist;    /* the targetlist representing the result"}, {"n": 141, "text": "\t\t\t\t\t\t\t\t\t   of "}, {"n": 142, "text": "\t\t\t\t\t\t\t\t\t * the query to be sent to the datanode */"}, {"n": 143, "text": ""}, {"n": 144, "text": "\t/*"}, {"n": 145, "text": "\t * Reference targetlist of Vars to match the Vars in the plan nodes on"}, {"n": 146, "text": "\t * coordinator to the corresponding Vars in the remote_query.  These"}, {"n": 147, "text": "\t * targetlists are used to while replacing/adding targetlist and quals in"}, {"n": 148, "text": "\t * the remote_query."}, {"n": 149, "text": "\t */ "}, {"n": 150, "text": "\tList            *coord_var_tlist;"}, {"n": 151, "text": "\tList            *query_var_tlist;"}, {"n": 152, "text": "\tbool\t\t\tis_temp;"}, {"n": 153, "text": "#ifdef __OPENTENBASE__"}, {"n": 154, "text": "\t/*"}, {"n": 155, "text": "\t  * This part is used for 'insert...on onconflict do update' while the target"}, {"n": 156, "text": "\t  * relation has unshippable triggers, we have to do the UPSERT on coordinator with"}, {"n": 157, "text": "\t  * triggers. In order to make triggers work, we separate UPSERT into INSERT and"}, {"n": 158, "text": "\t  * UPDATE."}, {"n": 159, "text": "      */"}, {"n": 160, "text": "\tchar\t\t\t*sql_select;      /* select statement */"}, {"n": 161, "text": "\tchar            *sql_select_base;"}, {"n": 162, "text": "\tbool            forUpadte;"}, {"n": 163, "text": "\tint             ss_num_params;"}, {"n": 164, "text": "\tOid \t\t\t*ss_param_types;"}, {"n": 165, "text": "\tchar            *select_cursor;"}, {"n": 166, "text": "\tchar\t\t\t*sql_update;      /* update statement */"}, {"n": 167, "text": "\tint             su_num_params;"}, {"n": 168, "text": "\tOid \t\t\t*su_param_types;"}, {"n": 169, "text": "\tchar            *update_cursor;"}, {"n": 170, "text": "\tUPSERT_ACTION   action;"}, {"n": 171, "text": "\tbool            dml_on_coordinator;"}, {"n": 172, "text": "\tAttrNumber\t    jf_ctid;"}, {"n": 173, "text": "\tAttrNumber\t    jf_xc_node_id;"}, {"n": 174, "text": "\tAttrNumber\t    jf_xc_wholerow;"}, {"n": 175, "text": "\tBitmapset       *conflict_cols;"}, {"n": 176, "text": ""}, {"n": 177, "text": "\tNode\t\t\t*parsetree;  /* to recognize subtxn cmds (savepoint, rollback to, release savepoint) */"}, {"n": 178, "text": "\tbool            is_set;      /* is SET statement ? */"}, {"n": 179, "text": "#endif"}, {"n": 180, "text": "\tModifyTable     *remote_mt;     /* DML plan generated by standard planner */"}, {"n": 181, "text": "\tList            *remote_target; /* remote lock projection result */"}, {"n": 182, "text": "\tList            *remote_quals;  /* remote lock qualifications */"}, {"n": 183, "text": "\tRCmdType         rcmdtype;       /* this remote query for ... */"}, {"n": 184, "text": "\tbool             ignore_tuple_desc; /* should ignore received tuple slot desc ? */"}, {"n": 185, "text": "\tFQS_MODE         fqs_mode;          /* this remote query for ... */"}, {"n": 186, "text": "\tbool             is_node_stmt;"}, {"n": 187, "text": "} RemoteQuery;"}, {"n": 188, "text": ""}]}, "en": {"path": "src/include/pgxc/locator.h", "sha256": "9a6af68127c2983e1a8a9c45b91decd9400abd49c89b88d1892beb1627ddf200", "url": "https://github.com/OpenTenBase/OpenTenBase/blob/v5.0/src/include/pgxc/locator.h", "lines": [{"n": 103, "text": "#define IsRelationDistributedByValue(rel_loc)\tIsLocatorDistributedByValue((rel_loc)->locatorType)"}, {"n": 104, "text": "/*"}, {"n": 105, "text": " * Nodes to execute on"}, {"n": 106, "text": " * primarynodelist is for replicated table writes, where to execute first."}, {"n": 107, "text": " * If it succeeds, only then should it be executed on nodelist."}, {"n": 108, "text": " * primarynodelist should be set to NULL if not doing replicated write operations"}, {"n": 109, "text": " */"}, {"n": 110, "text": "typedef struct"}, {"n": 111, "text": "{"}, {"n": 112, "text": "\tNodeTag\t\ttype;"}, {"n": 113, "text": "\tList\t\t*primarynodelist;"}, {"n": 114, "text": "\tList\t\t*nodeList;"}, {"n": 115, "text": "\tchar\t\tbaselocatortype;"}, {"n": 116, "text": "#ifdef __OPENTENBASE_C__"}, {"n": 117, "text": "\tint         nExprs;"}, {"n": 118, "text": "\tExpr        **dis_exprs;    /* Elements in the array are allowed to be null. */"}, {"n": 119, "text": "#endif"}, {"n": 120, "text": "\tOid\t\t\ten_relid;\t\t\t/* Relation to determine execution nodes */"}, {"n": 121, "text": "\tRelationAccessType accesstype;\t/* Access type to determine execution nodes */"}, {"n": 122, "text": "#ifdef __OPENTENBASE__"}, {"n": 123, "text": "\tbool    \trestrict_shippable; /* The ExecNode is choose by join qual on distribute column */"}, {"n": 124, "text": "\tbool\t\tconst_subquery; \t/* The subquery rte only got constant values */"}, {"n": 125, "text": "#endif"}, {"n": 126, "text": "\tDatum\t\trewrite_value;\t/* function evaluate result */"}, {"n": 127, "text": "\tbool\t\tisnull;"}, {"n": 128, "text": "\tbool\t\trewrite_done;\t\t/* function rewritted */"}, {"n": 129, "text": "\tbool\t\tinclude_local_cn;"}, {"n": 130, "text": "\tchar\t\t*g_index_table_name;  /* which index use to restrict datanodes */"}, {"n": 131, "text": "\tList        *dist_attno;"}, {"n": 132, "text": "\tOid          groupid;"}, {"n": 133, "text": "\tExpr        **en_param_expr;"}, {"n": 134, "text": "} ExecNodes;"}]}}, "nodes": [{"id": "entry", "file": "entry", "name": "exec_simple_query", "title": "简单查询入口", "phase": "entry", "line": 1370, "end": 1919, "summary": "串起解析、分析重写、规划与 Portal 执行。它是整条阅读路线的上层控制函数。", "input": "SQL 文本 query_string", "output": "查询树、计划列表，随后交给 Portal", "insight": "本图聚焦简单查询协议；预编译与扩展协议不能直接照搬这条路径。"}, {"id": "planquery", "file": "entry", "name": "pg_plan_query", "title": "把查询树交给规划器", "phase": "entry", "line": 1140, "end": 1203, "summary": "调用 planner() 生成 PlannedStmt，并设置查询标识等信息。", "input": "Query *querytree", "output": "PlannedStmt *plan", "insight": "上层经 pg_plan_queries() / pg_plan_queries_internal() 逐条进入这里；不是 exec_simple_query 的直接调用。"}, {"id": "planner", "file": "planner", "name": "planner", "title": "选择规划入口", "phase": "planning", "line": 360, "end": 385, "summary": "先检查 planner_hook；没有 hook 时，本地协调节点进入 pgxc_planner，其他情况进入 standard_planner。", "input": "Query、参数、cursorOptions", "output": "PlannedStmt", "insight": "本地 CN 条件是 IS_PGXC_LOCAL_COORDINATOR。DN 不会再次沿本地 CN 的 FQS 入口递归下推。"}, {"id": "pgxc", "file": "fqs", "name": "pgxc_planner", "title": "先尝试整条下推", "phase": "planning", "line": 237, "end": 251, "summary": "先调用 pgxc_FQS_planner。返回非空就直接采用；返回 NULL 才进入 standard_planner。", "input": "已经分析重写的 Query", "output": "FQS 计划或标准规划结果", "insight": "FQS 失败是规划回退，不是 SQL 执行失败；标准路径仍可涉及远程执行。"}, {"id": "fqs", "file": "fqs", "name": "pgxc_FQS_planner", "title": "FQS 资格与开关", "phase": "planning", "line": 390, "end": 658, "summary": "检查可下推性，再检查 enable_fast_query_shipping、滚动游标等限制；通过后创建远程查询计划。", "input": "Query + boundParams + cursorOptions", "output": "PlannedStmt 或 NULL", "insight": "先做 pgxc_is_query_shippable 再检查开关，是源码中的实际顺序；关闭开关不意味着停止可下推性分析。"}, {"id": "ship", "file": "ship", "name": "pgxc_is_query_shippable", "title": "分析可下推性与执行节点", "phase": "planning", "line": 2432, "end": 2710, "summary": "遍历 Query，收集执行节点和可下推性标志，再结合节点数、分布类型、表达式等条件作判断。", "input": "Query 与 Shippability_context", "output": "ExecNodes * 或 NULL", "insight": "不能用“SELECT 都能下推”概括。SS_NEED_SINGLENODE 也不是简单地看到多个 DN 就结束判断，代码还考虑复制与分布表达式。"}, {"id": "create", "file": "fqs", "name": "pgxc_FQS_create_remote_plan", "title": "构造 RemoteQuery", "phase": "planning", "line": 661, "end": 767, "summary": "构造 RemoteQuery，保存 exec_nodes；用 deparse_query 生成 sql_statement，并为普通只读 SELECT 设置 read_only。", "input": "Query + ExecNodes + FQS_MODE", "output": "RemoteQuery *", "insight": "下推的是由查询树反解析得到的 SQL，未必与用户原始字符串逐字相同。"}, {"id": "standard", "file": "planner", "name": "standard_planner", "title": "回退到标准规划", "phase": "planning", "line": 388, "end": 961, "summary": "当 pgxc_planner 没有得到 FQS 结果时进入标准规划。该函数还包含其他优化与分布式处理逻辑。", "input": "Query + cursorOptions + 参数", "output": "PlannedStmt", "insight": "“标准规划”不等于“只在 CN 执行”。本次关闭 FQS 的真实计划仍是 Remote Subquery Scan，目标为 dn001。"}, {"id": "init", "file": "remote", "name": "ExecInitRemoteQuery", "title": "绑定远程执行回调", "phase": "sending", "line": 8879, "end": 9020, "summary": "构建 RemoteQueryState，并把 ExecProcNode 函数指针设为 ExecRemoteQuery。", "input": "RemoteQuery + EState", "output": "RemoteQueryState", "insight": "这是计划节点到运行时执行状态的转换；不是规划函数直接调用远程执行函数。"}, {"id": "execute", "file": "remote", "name": "ExecRemoteQuery", "title": "首次发送，后续取行", "phase": "sending", "line": 9033, "end": 9277, "summary": "query_Done 为 false 时取执行连接、处理事务上下文并发送命令；随后设置 true，再通过 FetchTuple 或排序器取结果。", "input": "RemoteQueryState / ResponseCombiner", "output": "至多一个 TupleTableSlot，或 NULL", "insight": "query_Done 表示查询已发给 DN，不表示 DN 已把所有行执行完。这个区别是理解流式取行的关键。"}, {"id": "start", "file": "remote", "name": "pgxc_start_command_on_connection", "title": "按连接发送上下文与 SQL", "phase": "sending", "line": 6755, "end": 6862, "summary": "发送命令 ID、必要的快照等上下文；有 statement、cursor 或参数时走扩展协议，否则调用 pgxc_node_send_query。", "input": "PGXCNodeHandle + RemoteQueryState + Snapshot", "output": "发送成功 / 失败", "insight": "图中展示无参数普通 SELECT 的简单协议分支；不是所有远程 SQL 都使用 Q 消息。"}, {"id": "send", "file": "wire", "name": "pgxc_node_send_query", "title": "简单查询协议封装", "phase": "sending", "line": 3269, "end": 3281, "summary": "将 SQL 传入 pgxc_node_send_query_internal，rollback 标志为 false。", "input": "连接句柄 + SQL 文本", "output": "内部发送函数的状态码", "insight": "它是薄封装；真正写协议缓冲区和发请求的逻辑在下一层。"}, {"id": "wire", "file": "wire", "name": "pgxc_node_send_query_internal", "title": "写 Q 消息并发送", "phase": "sending", "line": 3208, "end": 3248, "summary": "将 Q、网络字节序长度和以空字符结束的 SQL 写入 outBuffer，最后调用 SendRequest。", "input": "SQL 字符串 + 连接缓冲区", "output": "面向 DN 的协议请求", "insight": "跨进程边界传递的是协议消息，不是把 CN 的 C 函数直接调用到 DN。"}, {"id": "fetch", "file": "remote", "name": "FetchTuple", "title": "从连接与缓冲区取行", "phase": "receiving", "line": 1990, "end": 2584, "summary": "检查已有行和缓冲区；通过 handle_response 处理消息，拿到 DataRow 后放入结果槽并返回。", "input": "ResponseCombiner", "output": "TupleTableSlot *", "insight": "多连接与缓冲处理比单一循环更复杂；本图只展开普通 DataRow 路线，排序、游标和部分优化另有分支。"}, {"id": "response", "file": "remote", "name": "handle_response_internal", "title": "按消息类型分派", "phase": "receiving", "line": 3048, "end": 3352, "summary": "get_message 取出协议消息；T 处理行描述、D/X 处理数据行、C 处理命令完成、E 处理错误。", "input": "PGXCNodeHandle + ResponseCombiner", "output": "RESPONSE_* 状态", "insight": "FetchTuple 调用的是 handle_response 宏，该宏在 execRemote.h 中展开为此函数，并带上文件与行号。"}, {"id": "row", "file": "remote", "name": "HandleDataRow", "title": "把 DataRow 放入 currentRow", "phase": "receiving", "line": 751, "end": 817, "summary": "接受数据行后，将连接缓冲区中的消息复制到 combiner->currentRow，保存长度和来源节点。", "input": "DataRow 消息体、长度与节点 OID", "output": "combiner->currentRow", "insight": "必须复制，因为后续 socket 读取会覆盖原连接缓冲区；该函数也会按错误状态或合并策略拒绝行。"}, {"id": "slot", "file": "remote", "name": "CopyDataRowTupleToSlot", "title": "将远程行装入结果槽", "phase": "receiving", "line": 1956, "end": 1970, "summary": "把 currentRow 复制到 slot 的内存上下文，ExecStoreDataRowTuple 保存它，再释放 currentRow 并清空指针。", "input": "currentRow + TupleTableSlot", "output": "可供上层使用的 slot", "insight": "slot 返回给执行器上层；这里不把所有客户端输出路径压缩成一个未经核对的直接调用。"}], "edges": [{"a": "entry", "b": "planquery", "kind": "path", "file": "entry", "line": 1667, "label": "经 pg_plan_queries / internal"}, {"a": "planquery", "b": "planner", "kind": "call", "file": "entry", "line": 1162, "label": "直接调用"}, {"a": "planner", "b": "pgxc", "kind": "call", "file": "planner", "line": 379, "label": "直接调用"}, {"a": "planner", "b": "standard", "kind": "call", "file": "planner", "line": 383, "label": "直接调用"}, {"a": "pgxc", "b": "fqs", "kind": "call", "file": "fqs", "line": 243, "label": "直接调用"}, {"a": "pgxc", "b": "standard", "kind": "call", "file": "fqs", "line": 249, "label": "FQS 返回 NULL 后回退"}, {"a": "fqs", "b": "ship", "kind": "call", "file": "fqs", "line": 420, "label": "直接调用"}, {"a": "fqs", "b": "create", "kind": "call", "file": "fqs", "line": 586, "label": "所有限制通过后"}, {"a": "create", "b": "init", "kind": "data", "file": "dispatch", "line": 395, "label": "T_RemoteQuery 分派初始化"}, {"a": "init", "b": "execute", "kind": "callback", "file": "remote", "line": 8904, "label": "ExecProcNode 函数指针绑定"}, {"a": "execute", "b": "start", "kind": "call", "file": "remote", "line": 9200, "label": "直接调用"}, {"a": "execute", "b": "fetch", "kind": "call", "file": "remote", "line": 9265, "label": "直接调用"}, {"a": "start", "b": "send", "kind": "call", "file": "remote", "line": 6858, "label": "无 statement / cursor / params"}, {"a": "send", "b": "wire", "kind": "call", "file": "wire", "line": 3280, "label": "直接调用"}, {"a": "fetch", "b": "response", "kind": "call", "file": "remote", "line": 2250, "label": "经 handle_response 宏"}, {"a": "response", "b": "row", "kind": "call", "file": "remote", "line": 3151, "label": "直接调用"}, {"a": "fetch", "b": "slot", "kind": "call", "file": "remote", "line": 2195, "label": "直接调用"}], "explain": {"query": "SELECT aid, abalance FROM pgbench_accounts WHERE aid = 42;", "captured_at": "2026-11-07T08:45:19.224933+00:00", "method": "EXPLAIN (VERBOSE, COSTS OFF, FORMAT JSON); BEGIN READ ONLY; SET LOCAL; ROLLBACK; no ANALYZE", "plans": {"on": [{"Plan": {"Node Type": "Remote Fast Query Execution", "Parallel Aware": false, "Output": ["pgbench_accounts.aid", "pgbench_accounts.abalance"], "Node/s": "dn001", "Remote query": "SELECT aid, abalance FROM public.pgbench_accounts WHERE (aid = 42)", "Remote plan": [{"Plan": {"Node Type": "Index Scan", "Parallel Aware": false, "Scan Direction": "Forward", "Index Name": "pgbench_accounts_pkey", "Relation Name": "pgbench_accounts", "Schema": "public", "Alias": "pgbench_accounts", "Output": ["aid", "abalance"], "Index Cond": "(pgbench_accounts.aid = 42)"}}]}}], "off": [{"Plan": {"Node Type": "Remote Subquery Scan", "Parallel Aware": false, "Replicated": "no", "Node List": ["dn001"], "Output": ["aid", "abalance"], "Plans": [{"Node Type": "Index Scan", "Parent Relationship": "Outer", "Parallel Aware": false, "Scan Direction": "Forward", "Index Name": "pgbench_accounts_pkey", "Relation Name": "pgbench_accounts", "Schema": "public", "Alias": "pgbench_accounts", "Output": ["aid", "abalance"], "Index Cond": "(pgbench_accounts.aid = 42)"}]}}]}}};
